create or replace view mts.bpm_group_info as
select t.ID AS GROUP_CODE,
       t.ORG_NAME AS GROUP_NAME,
       t.ORG_NAME AS GROUP_DESC,
       t.ORGINFO_ID AS PARENT_GROUP_CODE,
       t.ORGTYPE_ID AS GROUP_TYPE_CODE,
       t.TENANT_ID AS TENANT_ID
  from orginfo t;

create or replace view mts.bpm_group_type_info as
select orgtype . ID AS GROUP_TYPE_CODE,
       orgtype . ORGTYPE_NAME AS GROUP_TYPE_NAME
  from orgtype;

create or replace view mts.bpm_role_info as
select roleinfo.ROLE_CODE AS ROLE_CODE,
       roleinfo.ROLE_NAME AS ROLE_NAME,
       roleinfo.ROLE_NAME AS ROLE_DESC,
       b.ROLE_CODE AS PARENT_ROLE_CODE,
       (case roleinfo.ROLE_CODE
         when 'jg_manager' then
          '1'
         else
          '0'
       end) AS IS_MANAGER_ROLE,
       roleinfo.TENANT_ID AS tenant_id
  from (roleinfo left join roleinfo b on((roleinfo.ROLEINFO_ID = b.ID)));

create or replace view mts.bpm_user_info as
select distinct userinfo.ID AS ID,
                userinfo.LOGIN_ID AS LOGIN_ID,
                userinfo.USER_NAME AS USER_NAME,
                userinfo.USER_NAME AS USER_DESC,
                userinfo.EMAIL AS EMAIL,
                userinfo.MOBILE AS MOBILE,
                userinfo.IS_ADMIN AS IS_ADMIN,
                userinfo.TENANT_ID AS TENANT_ID
  from userinfo;

create or replace view mts.bpm_user_ext_info as
select '' AS LOGIN_ID,
       '' AS ATTRIBUTE_CODE,
       '' AS ATTRIBUTE_VALUE,
       '' AS TENANT_ID
  from bpm_user_info;

create or replace view mts.bpm_user_group_rel as
select distinct a.LOGIN_ID AS LOGIN_ID,
                b.ID AS GROUP_CODE,
                (case b.ORGTYPE_ID
                  when '333' then
                   '1'
                  else
                   '0'
                end) AS IS_MASTER_GROUP,
                a.TENANT_ID AS TENANT_ID
  from ((userinfo_orginfo_rel c join orginfo b on((b.ID = c.ORGINFO_ID))) join
        bpm_user_info a on((a.ID = c.USERINFO_ID)));

create or replace view mts.bpm_user_role_rel as
select a.LOGIN_ID AS LOGIN_ID,
       b.ROLE_CODE AS ROLE_CODE,
       a.TENANT_ID AS TENANT_ID
  from ((userinfo_roleinfo_rel c join roleinfo b
        on((b.ID = c.ROLEINFO_ID))) join userinfo a
        on((a.ID = c.USERINFO_ID)));

CREATE OR REPLACE VIEW MTS.ONLINE_USER_INFO AS
SELECT
        a.id            AS id,
        a.clientip      AS clientip,
        a.login_id      AS login_id,
        a.login_time    AS login_time,
        a.logout_time   AS logout_time,
        c.user_name     AS login_name,
        a.tgt           AS tgt,
        a.app_code      AS app_code,
        a.online1       AS online1,
        a.client_type   AS client_type,
        c.tenant_id     AS tenant_id
    FROM
        userinfo c
        LEFT JOIN tenantinfo b ON c.tenant_id = b.tenant_id
        LEFT JOIN online_user_info_t a ON a.login_id = c.login_id;

