CREATE OR REPLACE VIEW MTS.V_MTS_ST_COLUMN_REL AS
WITH A AS
 (

  SELECT M.S_TABLE || M.T_TABLE || M.S_TABLE_COLUMN || M.T_TABLE_COLUMN ZJ,
          M.S_TABLE,
          M.S_TABLE_COLUMN,
          U.DATA_TYPE ,
          U.DATA_LENGTH
    FROM MTS_ST_TABLE_COLUMN_REL M
    LEFT JOIN USER_TAB_COLUMNS U
      ON M.S_TABLE = U.TABLE_NAME
     AND M.S_TABLE_COLUMN = U.COLUMN_NAME
     WHERE M.S_TABLE_COLUMN NOT LIKE '%系统计算%' OR M.S_TABLE_COLUMN <>'默认值'),
B AS
 (SELECT M.S_TABLE || M.T_TABLE || M.S_TABLE_COLUMN || M.T_TABLE_COLUMN ZJ,
         M.T_TABLE,
         M.T_TABLE_COLUMN,
         U.DATA_TYPE,
         U.DATA_LENGTH
    FROM MTS_ST_TABLE_COLUMN_REL M
    LEFT JOIN USER_TAB_COLUMNS U
      ON M.T_TABLE = U.TABLE_NAME
     AND M.T_TABLE_COLUMN = U.COLUMN_NAME)
SELECT A.S_TABLE,
       A.S_TABLE_COLUMN,
       A.DATA_TYPE S_DATA_TYPE,
       A.DATA_LENGTH S_DATA_LENGTH,
       B.T_TABLE,
       B.T_TABLE_COLUMN,
       B.DATA_TYPE T_DATA_TYPE,
       B.DATA_LENGTH T_DATA_LENGTH
  FROM A, B
 WHERE A.ZJ = B.ZJ
   AND ((A.DATA_TYPE <> B.DATA_TYPE) OR (A.DATA_TYPE = B.DATA_TYPE AND A.DATA_LENGTH >B.DATA_LENGTH ));

create or replace function mts.add_days(col IN date,n IN int) return  date is begin   return col+n; end;
/

create or replace function mts.add_daytimes(col in date, n in int) return date is   Result date; begin   return(col+n); end add_daytimes;
/

create or replace function mts.cast_int(col1 in varchar,col2 in decimal) return integer  is   Result integer; begin     IF col1 !='' THEN     RETURN to_number(col1);   ELSe     RETURN to_number(col2);   END IF; end cast_int;
/

create or replace function mts.day(c_date in date) return varchar is   rday varchar(2); begin   return(TO_CHAR(c_date,'DD')); end day;
/

CREATE OR REPLACE FUNCTION MTS.FUN_ISLEGAL(PHONENUMBER IN VARCHAR2)
  RETURN NUMBER
--返回1表示是合法，返回0表示是不合法
 AS
BEGIN
  IF LENGTH(PHONENUMBER) != 11 THEN
    RETURN 0;
  ELSIF REPLACE(TRANSLATE(PHONENUMBER, '0123456789', '0'), '0', '') IS NOT NULL THEN
    --dbms_output.put_line(phoneNumber || '不是[0-9]的数字序列');
    RETURN 0;
  ELSIF SUBSTR(PHONENUMBER, 1, 2) NOT IN ('13', '15', '18') THEN
    --dbms_output.put_line('前二位数字不合法：'||substr(phoneNumber,1,2));
    RETURN 0;
  ELSE
    --dbms_output.put_line('合法号码');
    RETURN 1;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    --dbms_output.put_line('异常：');
    RETURN 0;
END FUN_ISLEGAL;
/

CREATE OR REPLACE FUNCTION MTS.FUN_LAST_DATE(P_DAT IN VARCHAR2,
                                         P_PD  IN INTEGER) RETURN VARCHAR2 IS
  --函数说明：
  /*根据实际存放数据的日期返回数据计算的日期 否则返回 999
  报表频度为：
  0：日期
  1：旬报
  2  月报
  3：季报
  4：半年报
  5：年报*/
  MM VARCHAR2(2);
  YY VARCHAR2(4);
  DD VARCHAR2(2);
  DT VARCHAR2(8);
BEGIN
  --日期
  SELECT SUBSTR(P_DAT, 7, 2) INTO DD FROM DUAL;
  --月份
  SELECT SUBSTR(P_DAT, 5, 2) INTO MM FROM DUAL;
  --年份
  SELECT SUBSTR(P_DAT, 1, 4) INTO YY FROM DUAL;

  IF P_PD = 0 THEN
    DT := TO_CHAR(TO_DATE(P_DAT, 'YYYYMMDD') - 1, 'YYYYMMDD');

  ELSIF P_PD = 1 THEN
    CASE
      WHEN DD <= 10 THEN
        DT := TO_CHAR(TO_DATE(SUBSTR(P_DAT, 1, 6) || '01', 'YYYYMMDD') - 1,
                      'YYYYMMDD');
      WHEN DD <= 20 THEN
        DT := SUBSTR(P_DAT, 1, 6) || '10';
      ELSE
        DT := SUBSTR(P_DAT, 1, 6) || '20';
    END CASE;

  ELSIF P_PD = 2 THEN
    --根据本月末日期返回上月末日期
    DT := TO_CHAR(TRUNC(TO_DATE(P_DAT, 'YYYYMMDD'), 'MONTH') - 1,
                  'YYYYMMDD');
  ELSIF P_PD = 3 THEN
    --根据本季的任何一天日期返回本季末的日期
    DT := TO_CHAR(TRUNC(TO_DATE(P_DAT, 'YYYYMMDD'), 'Q') - 1, 'YYYYMMDD');
  ELSIF P_PD = 4 AND MM > 6 THEN
    DT := SUBSTR(P_DAT, 1, 4) || '0630';
  ELSIF P_PD = 4 AND MM <= 6 THEN
    DT := SUBSTR(P_DAT, 1, 4) - 1 || '1231';
  ELSIF P_PD = 5 THEN
    DT := SUBSTR(P_DAT, 1, 4) - 1 || '1231';
  ELSIF P_PD = 7 THEN
    DT := SUBSTR(P_DAT, 1, 4) - 1 || SUBSTR(P_DAT, 5, 4);
  ELSE
    DT := TO_CHAR(TO_DATE(P_DAT, 'YYYYMMDD') - 366, 'YYYYMMDD');
  END IF;
  RETURN(DT);

  -- 例外处理
EXCEPTION
  WHEN OTHERS THEN
    RETURN 999;
END;
/

CREATE OR REPLACE FUNCTION MTS.FUN_MTS_CHECKIDCARD(P_IDCARD IN VARCHAR2)
  RETURN INT IS
  V_REGSTR    VARCHAR2(2000);
  V_SUM       NUMBER;
  V_MOD       NUMBER;
  V_CHECKCODE CHAR(11) := '10X98765432';
  V_CHECKBIT  CHAR(1);
  V_AREACODE  VARCHAR2(2000) := '11,12,13,14,15,21,22,23,31,32,33,34,35,36,37,41,42,43,44,45,46,50,51,52,53,54,61,62,63,64,65,71,81,82,91,';
BEGIN
  CASE LENGTHB(P_IDCARD)
    WHEN 15 THEN
      -- 15位
      IF INSTRB(V_AREACODE, SUBSTR(P_IDCARD, 1, 2) || ',') = 0 THEN
        RETURN 0;
      END IF;

      IF MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 2)) + 1900, 400) = 0 OR
         (MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 2)) + 1900, 100) <> 0 AND
          MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 2)) + 1900, 4) = 0) THEN
        -- 闰年
        V_REGSTR := '^[1-9][0-9]{5}[0-9]{2}((01|03|05|07|08|10|12)(0[1-9]|[1-2][0-9]|3[0-1])|(04|06|09|11)(0[1-9]|[1-2][0-9]|30)|02(0[1-9]|[1-2][0-9]))[0-9]{3}$';
      ELSE
        V_REGSTR := '^[1-9][0-9]{5}[0-9]{2}((01|03|05|07|08|10|12)(0[1-9]|[1-2][0-9]|3[0-1])|(04|06|09|11)(0[1-9]|[1-2][0-9]|30)|02(0[1-9]|1[0-9]|2[0-8]))[0-9]{3}$';
      END IF;

      IF REGEXP_LIKE(P_IDCARD, V_REGSTR) THEN
        RETURN 1;
      ELSE
        RETURN 0;
      END IF;
    WHEN 18 THEN
      -- 18位
      IF INSTRB(V_AREACODE, SUBSTRB(P_IDCARD, 1, 2) || ',') = 0 THEN
        RETURN 0;
      END IF;

      IF MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 4)), 400) = 0 OR
         (MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 4)), 100) <> 0 AND
          MOD(TO_NUMBER(SUBSTRB(P_IDCARD, 7, 4)), 4) = 0) THEN
        -- 闰年
        V_REGSTR := '^[1-9][0-9]{5}(19|20)[0-9]{2}((01|03|05|07|08|10|12)(0[1-9]|[1-2][0-9]|3[0-1])|(04|06|09|11)(0[1-9]|[1-2][0-9]|30)|02(0[1-9]|[1-2][0-9]))[0-9]{3}[0-9Xx]$';
      ELSE
        V_REGSTR := '^[1-9][0-9]{5}(19|20)[0-9]{2}((01|03|05|07|08|10|12)(0[1-9]|[1-2][0-9]|3[0-1])|(04|06|09|11)(0[1-9]|[1-2][0-9]|30)|02(0[1-9]|1[0-9]|2[0-8]))[0-9]{3}[0-9Xx]$';
      END IF;

      IF REGEXP_LIKE(P_IDCARD, V_REGSTR) THEN
        V_SUM      := (TO_NUMBER(SUBSTRB(P_IDCARD, 1, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 11, 1))) * 7 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 2, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 12, 1))) * 9 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 3, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 13, 1))) * 10 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 4, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 14, 1))) * 5 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 5, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 15, 1))) * 8 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 6, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 16, 1))) * 4 +
                      (TO_NUMBER(SUBSTRB(P_IDCARD, 7, 1)) +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 17, 1))) * 2 +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 8, 1)) * 1 +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 9, 1)) * 6 +
                      TO_NUMBER(SUBSTRB(P_IDCARD, 10, 1)) * 3;
        V_MOD      := MOD(V_SUM, 11);
        V_CHECKBIT := SUBSTRB(V_CHECKCODE, V_MOD + 1, 1);

        IF V_CHECKBIT = UPPER(SUBSTRB(P_IDCARD, 18, 1)) THEN
          RETURN 1;
        ELSE
          RETURN 0;
        END IF;
      ELSE
        RETURN 0;
      END IF;
    ELSE
      RETURN 0; -- 身份证号码位数不对
  END CASE;
EXCEPTION
  WHEN OTHERS THEN
    RETURN 0;
END FUN_MTS_CHECKIDCARD;
/

create or replace function mts.instr_func(f_str in varchar, f_substr in varchar,f_str_pos in int,f_count in int) return integer is  Result integer; begin   return instr(f_str,f_substr,f_str_pos,f_count ); end instr_func;
/

create or replace function mts.month(c_date in date) return varchar is   rmonth varchar(2); begin   return(TO_CHAR(c_date,'MM')); end month;
/

create or replace function mts.QUARTER(c_date in date) return varchar is   rquarter varchar(1); begin   return(TO_CHAR(c_date,'Q')); end QUARTER;
/

create or replace function mts.weekofyear(cdate in date) return integer is   week integer; begin   return(to_char(cdate, 'ww')); end weekofyear;
/

create or replace function mts.year(c_date in date) return varchar is ryear varchar(4); begin   return(TO_CHAR(c_date,'YYYY')); end year;
/

create or replace procedure mts.P_BAK_DECD(Name in out type, Name in out type, ...) is
begin
 --------------------大额存单

  SELECT A.KEHUHAOO,
        A.ZHANGHAO,
        A.KEHUZHAO, 
        A.KAIHRIQI,
        C.ZHANGHAO,
        C.KEHUZHAO,
        C.ZHHAOXUH,
        D.TERM_ACCT_NO,
        D.TERM_SERIAL_NO
   FROM (SELECT *
           FROM CBS_KDPA_ZHXINX A
          WHERE A.CUNKZLEI = '26'
          ) A
   LEFT JOIN CBS_KDPA_ZHDUIZ C
     ON A.ZHANGHAO = C.ZHANGHAO
    AND A.KEHUZHAO = C.KEHUZHAO
   LEFT JOIN CDS_TB_CASH_ACCT_INFO D
     ON C.KEHUZHAO || C.ZHHAOXUH = D.TERM_ACCT_NO || D.TERM_SERIAL_NO
    AND D.STATUS = '0' --状态为正常
   LEFT JOIN CDS_TB_PROD_PUB_INFO E
     ON D.PROD_CODE = E.PROD_CODE
   LEFT JOIN MTS_SYS_XTHLCS HL
     ON A.HUOBDAIH = HL.HUOBDAIH
  WHERE D.TERM_ACCT_NO || D.TERM_SERIAL_NO IS NULL;
   
   SELECT A.KEHUHAOO,
        A.ZHANGHAO,
        A.KEHUZHAO, 
        A.KAIHRIQI ,ZHHUZTAI ,ZHHUYUEE,CSDOQIRQ,KAIHUQUD FROM CBS_KDPA_ZHXINX A WHERE ZHANGHAO='030101010000055040'
   
------------------信贷
SELECT count(*)
      FROM MTS_CUST_LABEL_POPULATION A
      inner JOIN MTS_CUST_LABEL_cd02 C
        ON A.AA01 = C.AA01
     WHERE A.AG02 <'120000'
     
    SELECT count(*)
      FROM (SELECT A.ECIF_CUST_NO, SUM(A.JINE) ZJZ
              FROM MTS_CUST_OWER_PROD A
             WHERE A.PROD_B_TYPE IN ('11')/* and DAOQI_FLAG='1' */
             GROUP BY A.ECIF_CUST_NO)
     WHERE     ZJZ=0
     
      SELECT T.ECIF_CUST_NO,T.OPEN_ORG, T.OPEN_ORG,COI.MAINFRAMEORGID,
         CASE
           WHEN LENGTH(T.OPEN_ORG) = 6 THEN
            T.OPEN_ORG
           ELSE
            COI.MAINFRAMEORGID
         END AG01
    FROM (select * from MTS.ECIF_T01_P_CUST_INFO where ECIF_CUST_NO='10008356546') T
    left JOIN CMS_ORG_INFO COI
      ON T.OPEN_ORG = COI.ORGID  
      
      
      
      SELECT count(*)
           FROM CMS_ACCT_LOAN A
           LEFT JOIN CMS_BUSINESS_CONTRACT B
             ON A.CONTRACTSERIALNO = B.SERIALNO
           LEFT JOIN CMS_CUSTOMER_INFO C
             ON A.CUSTOMERID = C.CUSTOMERID
           LEFT JOIN MTS_CUST_OWER_PROD_TMP GOUGOU
             ON C.MFCUSTOMERID = GOUGOU.ECIF_CUST_NO
            AND A.SERIALNO = GOUGOU.ZHANGHAO
            AND NVL(A.BUSINESSTYPE, 0) = NVL(GOUGOU.PROD_S_CODE, 0) --空空不相等
            AND GOUGOU.PROD_B_TYPE = '11'
           LEFT JOIN MTS_SYS_XTHLCS HL
             ON A.CURRENCY = HL.HUOBDAIH
           LEFT JOIN CMS_ORG_INFO D
             ON A.ACCOUNTINGORGID = D.ORGID
          WHERE NVL(C.MFCUSTOMERID, 'ISNULL') <> 'ISNULL'
          
      select count(*)
  from (select a.customerid
          from CMS_ACCT_LOAN a
         where NVL(A.NORMALBALANCE, 0) + NVL(A.OVERDUEBALANCE, 0) > 0
         group by a.customerid);    
          
                SELECT count(*)
           FROM CMS_ACCT_LOAN A
           LEFT  JOIN CMS_CUSTOMER_INFO C
            ON A.CUSTOMERID = C.CUSTOMERID
            WHERE NVL(C.MFCUSTOMERID, 'ISNULL') = 'ISNULL'
            
            
            
            
            
         select count(1) from (   
             SELECT distinct a.CUSTOMERID
           FROM CMS_ACCT_LOAN A
           LEFT  JOIN CMS_CUSTOMER_INFO C
            ON A.CUSTOMERID = C.CUSTOMERID
            WHERE NVL(C.MFCUSTOMERID, 'ISNULL') = 'ISNULL' and NVL(A.NORMALBALANCE, 0) + NVL(A.OVERDUEBALANCE, 0) > 0)
            
            
 SELECT M.CUSTOMERID,M.CUSTOMERNAME,M.MFCUSTOMERID FROM CMS_CUSTOMER_INFO  M WHERE M.CUSTOMERID='L20170607000008'
end P_BAK_DECD;
/

CREATE OR REPLACE PROCEDURE MTS.SYS_PRC_STEP_LOGS(INDATE     IN VARCHAR2,
                                              PRC_NAME   IN VARCHAR2,
                                              PRC_DESC   IN VARCHAR2,
                                              LOG_MSG    IN VARCHAR2,
                                              V_LOGSEC   IN NUMBER,
                                              LOG_BUTTON IN NUMBER) AS
  /*
  AUTHOR:SOLIN
  CREATE DATE: 20141126
  CONTENT:单步调试日志
  CHANGE DATE: 20141127
  CONTENT:增加调试开关，0为关闭，1为打开。默认关闭
  */
  V_INDATE   VARCHAR(8);
  V_PRC_NAME VARCHAR(80);
  V_PRC_DESC VARCHAR(600);
  V_LOG_MSG  VARCHAR(2000);
BEGIN
  --PROCEDURE START!
  IF LOG_BUTTON = 1 THEN
    --1表示调试开关为打开，需要计入日志
    IF TRANSLATE(INDATE, '1234567890', '0000000000') = '00000000' THEN
      --判断日期格式YYYYMMDD
      V_INDATE  := TO_CHAR(TO_DATE(INDATE,'YYYY/MM/DD'),'YYYYMMDD');
      V_LOG_MSG := SUBSTR(LOG_MSG, 1, 1000);
    ELSE
      V_INDATE  := SUBSTR(INDATE, 1, 8);
      V_LOG_MSG := SUBSTR('警告：日期格式不是YYYYMMDD;插入日志为：' || LOG_MSG,
                          1,
                          1000);
    END IF;
    V_PRC_NAME := SUBSTR(PRC_NAME, 1, 40);
    V_PRC_DESC := SUBSTR(PRC_DESC, 1, 300);

    INSERT INTO MTS.MTS_LOGS
      (LOGID, LOGMOD, LOGTYP, LOGDATE, SYS_DATE, LOGMSG, LOGSEC)
    VALUES
      (MTS.MTS_LOGSEQ.NEXTVAL,
       V_PRC_NAME,
       V_PRC_DESC,
       V_INDATE,
       SYSDATE,
       V_LOG_MSG,
       V_LOGSEC);
    COMMIT;
  END IF;
  --PROCEDURE END!
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_ACTIVITY_DATA(V_SYSDAT IN VARCHAR2,
                                                     OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客群监控
  -- 报表编号：P_MTS_CUST_ACTIVITY_DATA
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '客群监控'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_ACTIVITY_DATA'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_SQL        VARCHAR2(4000);
  CURSOR CC IS
    SELECT 'INSERT INTO MTS_CUST_ACTIVITY_DATA SELECT MTS_LOGSEQ.NEXTVAL, AA01, BA01, BA05, BA06, CF01, BA11, BA12, BB02, BB03, ORGPATH, CA01,
    CA02, CA07, CA08, CA11, CA12, CA15, CA16, CA23, CA26, CA27, CA34, CA35, CC07, CC08, CC11, CC12, CC14, CC17, CC18,
    CD03, CD04, CD05, CD06, CD08, CD09, CD11, CD14, CD16, CD19, CD20, CE06, CE07, CG01, CG02, CH08, CH09, CH11, CH12,
    DA03, DA04, DA06, EA01, EA02, FA01, FA03, AA02,' ||
           C.FREQUENCY || ',''' || C.ACTIVITY_ID || ''',' || C.STARTE_DATE || ',' ||
           C.END_DATE || ',' || V_SYSDAT || ',' ||
           TO_CHAR(TO_DATE(C.STARTE_DATE, '''YYYYMMDD''') + C.FREQUENCY,
                   '''YYYYMMDD''') || ',''' || ACTIVITY_NAME || ''' FROM ' ||
           B.LEFT_TABLE || ' ' || B.LEFT_TABLE || ' where ' ||
           REPLACE(TO_CHAR(A.CG_SQL_WHERE),
                   B.DBM_DSBASIC_NAME,
                   B.LEFT_TABLE) QSQL
      FROM MTS.EPM_CG_GROUP_INFO A,
           (SELECT C.DBM_DSBASIC_NAME, B.LEFT_TABLE
              FROM MTS.DBM_DATASET_RELATION B, MTS.DBM_DATASET_BASIC C
             WHERE B.BASIC_ID = C.ID) B,
           MTS_ACTIVITY_CONTROL_DATA C
     WHERE TO_CHAR(A.CG_SQL_FROM) = TO_CHAR(B.DBM_DSBASIC_NAME)
       AND A.CG_CODE = C.CUST_GROUP_ID
       AND C.STARTE_DATE = V_SYSDAT
     ORDER BY A.CG_CODE;
  --定义一个游标变量
  CCREC CC%ROWTYPE;
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --当日创建的活动监控
  DELETE FROM MTS_CUST_ACTIVITY_DATA A WHERE A.D_DATE = V_SYSDAT;
  COMMIT;
  FOR CCREC IN CC LOOP
    V_SQL := CCREC.QSQL;
    EXECUTE IMMEDIATE V_SQL;
  END LOOP;

  --按照快照周期保存数据
  INSERT INTO MTS_CUST_ACTIVITY_DATA
    SELECT MTS_LOGSEQ.NEXTVAL,
           A.AA01,
           NVL(B.BA01, 0),
           NVL(B.BA05, 0),
           NVL(B.BA06, 0),
           B.CF01,
           B.BA11,
           B.BA12,
           B.BB02,
           NVL(B.BB03, 0),
           B.ORGPATH,
           NVL(B.CA01, 0),
           NVL(B.CA02, 0),
           NVL(B.CA07, 0),
           NVL(B.CA08, 0),
           NVL(B.CA11, 0),
           NVL(B.CA12, 0),
           NVL(B.CA15, 0),
           NVL(B.CA16, 0),
           NVL(B.CA23, 0),
           NVL(B.CA26, 0),
           NVL(B.CA27, 0),
           NVL(B.CA34, 0),
           NVL(B.CA35, 0),
           NVL(B.CC07, 0),
           NVL(B.CC08, 0),
           NVL(B.CC11, 0),
           NVL(B.CC12, 0),
           NVL(B.CC14, 0),
           NVL(B.CC17, 0),
           NVL(B.CC18, 0),
           NVL(B.CD03, 0),
           NVL(B.CD04, 0),
           NVL(B.CD05, 0),
           NVL(B.CD06, 0),
           NVL(B.CD08, 0),
           NVL(B.CD09, 0),
           NVL(B.CD11, 0),
           NVL(B.CD14, 0),
           NVL(B.CD16, 0),
           NVL(B.CD19, 0),
           NVL(B.CD20, 0),
           NVL(B.CE06, 0),
           NVL(B.CE07, 0),
           NVL(B.CG01, 0),
           NVL(B.CG02, 0),
           NVL(B.CH08, 0),
           NVL(B.CH09, 0),
           NVL(B.CH11, 0),
           NVL(B.CH12, 0),
           NVL(B.DA03, 0),
           NVL(B.DA04, 0),
           NVL(B.DA06, 0),
           NVL(B.EA01, 0),
           NVL(B.EA02, 0),
           NVL(B.FA01, 0),
           NVL(B.FA03, 0),
           B.AA02,
           A.PD,
           A.ACTIVITY_ID,
           A.STARTE_DATE,
           A.END_DATE,
           V_SYSDAT,
           TO_CHAR(TO_DATE(V_SYSDAT, 'YYYYMMDD') + A.PD, 'YYYYMMDD'),
           A.ACTIVITY_NAME
      FROM MTS_CUST_ACTIVITY_DATA A
      LEFT JOIN MTS_CUST_LABEL B
        ON A.AA01 = B.AA01
     WHERE A.NEXT_DATE = V_SYSDAT
       AND A.END_DATE >= V_SYSDAT;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_001数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.SYS_GET_PARTITION_NAME(TAL_OWER IN VARCHAR2,TAL_NAME IN VARCHAR2,V_SYSDAT IN VARCHAR2,PARTITION_NAME OUT VARCHAR2,OUTCDE   OUT NUMBER) AS
---------------------------------------------------------------------------------------
--根据表信息和时间参数，返回分区名称
---------------------------------------------------------------------------------------
  V_RPTNAME VARCHAR2(100) := '根据表信息和时间参数，返回分区名称'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'SYS_GET_PARTITION_NAME'; --存储过程名

  V_TAL_OWER VARCHAR2(20);
  V_TAL_NAME VARCHAR2(40);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE;
  V_P_DAT   VARCHAR2(8);
  V_PARTITION_NAME VARCHAR2(40);
  V_ERRORTEXT VARCHAR2(4000);
  V_LOG_BUTTON  VARCHAR2(2);

BEGIN

  V_TAL_OWER :=TAL_OWER;
  V_TAL_NAME :=TAL_NAME;
  V_P_DAT    :=V_SYSDAT;
    --调试日志打开
  V_LOG_BUTTON := 1;

 with xs as

 (select x.*,
         to_date(substr(high_value, 11, 19), 'YYYY-MM-DD HH24:MI:SS') dates,
         replace(high_value, 'TIMESTAMP''') datestr
    from xmltable('/ROWSET/ROW' passing (select dbms_xmlgen.getxmltype('
select t.table_owner, t.table_name, t.partition_name, t.high_value
  from all_tab_partitions t')
                      from dual) columns table_owner varchar2(30) path
                   'TABLE_OWNER',
                   table_name varchar2(30) path 'TABLE_NAME',
                   partition_name varchar2(30) path 'PARTITION_NAME',
                   high_value varchar2(30) path 'HIGH_VALUE') x)

select partition_name
  into V_PARTITION_NAME
  from xs
 WHERE xs.table_owner = V_TAL_OWER
   and xs.table_name = V_TAL_NAME
   and replace(to_char(xs.dates, 'YYYY-MM-DD'), '-', '') = V_P_DAT;


   --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工获取分区名称数据处理完成'||V_PARTITION_NAME||V_TAL_OWER||V_TAL_NAME||V_P_DAT||SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(    V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);

 PARTITION_NAME :=V_PARTITION_NAME;
 RETURN;


   --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

CREATE OR REPLACE PROCEDURE MTS.SYS_JUDGE_DATEFLAG(DATVAL IN VARCHAR2,
                                               DATFLG IN CHAR,
                                               OUTCDE OUT NUMBER,
                                               RSTCDE OUT NUMBER) AS
---------------------------------------------------------------------------------------
--频度判断，根据传入值判断当前日期频度
--Y  年末
--H  半年
--Q  季度
--M  月末
--T  旬
--W  周（周日）
---------------------------------------------------------------------------------------
  TYPE TCUR_TMP IS REF CURSOR;
  V_DATNXT VARCHAR2(8);
  CUR_TMP  TCUR_TMP;
BEGIN

  OPEN CUR_TMP FOR
    SELECT TO_CHAR(TO_DATE(DATVAL, 'YYYY/MM/DD') + 1, 'YYYYMMDD') FROM DUAL;
  FETCH CUR_TMP
    INTO V_DATNXT;
  IF CUR_TMP%NOTFOUND OR CUR_TMP%NOTFOUND IS NULL THEN
    OUTCDE := -1;
    RETURN;
  END IF;
  CLOSE CUR_TMP;

  RSTCDE := 0;

  IF (DATFLG = 'Y') THEN
    IF SUBSTR(V_DATNXT, 5, 4) = '0101' THEN
      RSTCDE := 1;
      OUTCDE := 0;
      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'H') THEN
    IF SUBSTR(V_DATNXT, 5, 4) = '0701' OR SUBSTR(V_DATNXT, 5, 4) = '0101' THEN
      RSTCDE := 1;
      OUTCDE := 0;
      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'Q') THEN
    IF SUBSTR(V_DATNXT, 5, 4) = '0401' OR SUBSTR(V_DATNXT, 5, 4) = '0701' OR
       SUBSTR(V_DATNXT, 5, 4) = '1001' OR SUBSTR(V_DATNXT, 5, 4) = '0101' THEN
      RSTCDE := 1;
      OUTCDE := 0;

      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'M') THEN
    IF SUBSTR(V_DATNXT, 7, 2) = '01' THEN
      RSTCDE := 1;
      OUTCDE := 0;

      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'T') THEN
    IF SUBSTR(V_DATNXT, 7, 2) = '01' OR SUBSTR(V_DATNXT, 7, 2) = '11' OR
       SUBSTR(V_DATNXT, 7, 2) = '21' THEN
      RSTCDE := 1;
      OUTCDE := 0;

      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'W') THEN
    IF TO_CHAR(TO_DATE(V_DATNXT, 'YYYYMMDD'), 'D') = 2 THEN
      RSTCDE := 1;
      OUTCDE := 0;

      RETURN;
    END IF;
  END IF;

  IF (DATFLG = 'D') THEN
      RSTCDE := 1;
      OUTCDE := 0;
      RETURN;
  END IF;

  OUTCDE := 0;
  RSTCDE := 0;

EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := SQLCODE;
      RAISE;
    END;
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL(V_SYSDAT IN VARCHAR2,
                                             OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户标签宽表
  -- 报表编号：P_MTS_CUST_LABEL
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
