  V_PRCNAME        VARCHAR2(32) := 'P_MTS_CUST_LABEL'; --存储过程名
  V_OUTCDE         NUMBER; --日期判断返回码
  V_RSTCDE         NUMBER; --日期判断返回码
  V_ERRORTEXT      VARCHAR2(4000);
  V_START_DT       DATE;
  V_LOGSEC         NUMBER(10);
  V_COUNT          NUMBER(20);
  V_PARTITION_NAME VARCHAR2(40); --存放返回分区名称
  V_LOG_BUTTON     VARCHAR2(2); --日志是否打印参数
  V_NEXT_M_F       VARCHAR2(8); --当前月份下一个的第一天
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  V_NEXT_M_F   := TO_CHAR(LAST_DAY(TO_DATE(V_SYSDAT, 'YYYYMMDD')) + 1,
                          'YYYYMMDD'); --当前月份下一个的第一天

