      LEFT JOIN MTS_CUST_LABEL_PRODUCT C
        ON A.AA01 = C.AA01
      LEFT JOIN MTS_CUST_LABEL_TRANSACTION D
        ON A.AA01 = D.AA01
      LEFT JOIN MTS_CUST_LABEL_APPACTION E
        ON A.AA01 = E.AA01
      LEFT JOIN MTS_CUST_LABEL_CUSTRISK F
        ON A.AA01 = F.AA01
     WHERE A.AG02 <= '120000';
