  V_ERRORTEXT := '表MTS.MTS_CUST_LABEL_B中插入数据完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --月末备份数据
  SYS_JUDGE_DATEFLAG(V_SYSDAT, 'M', V_OUTCDE, V_RSTCDE);
  IF (V_OUTCDE = 0 AND V_RSTCDE = 1) THEN
    V_ERRORTEXT := V_OUTCDE || V_RSTCDE || SUBSTR(SQLERRM, 1, 1000);
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
  
    SELECT COUNT(*)
      INTO V_COUNT
      FROM MTS_CUST_LABEL_HIS
     WHERE DATA_DATE >= TO_DATE(V_SYSDAT, 'yyyy-mm-dd');
    V_ERRORTEXT := V_SYSDAT || SUBSTR(SQLERRM, 1, 1000);
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
    --防止重复跑批，删除当前跑批批次分区
    IF V_COUNT > 0 THEN
      MTS.SYS_GET_PARTITION_NAME('MTS',
                                 'MTS_CUST_LABEL_HIS',
                                 V_NEXT_M_F,
                                 V_PARTITION_NAME,
                                 OUTCDE);
    
      V_ERRORTEXT := '返回MTS_CUST_LABEL_HIS需要删除的分区名称' || V_PARTITION_NAME ||
                     SUBSTR(SQLERRM, 1, 1000);
      V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      EXECUTE IMMEDIATE 'ALTER TABLE MTS.MTS_CUST_LABEL_HIS DROP PARTITION ' || ' ' ||
                        V_PARTITION_NAME;
    
    END IF;
