             DB05, --近1月累计转出笔数
             DB06, --近1月转出单笔最大金额
             DB07, --是否我行资金过路户
             DB08, --是否向他行同名户规律转出
             DC01, --渠道偏好
             DC02, --储蓄产品偏好
             DC03, --乐惠存期限偏好
             DC04, --储蓄期限偏好
             DC05, --理财产品期限偏好
             EA01, --手机银行是否下载登录
             EA02, --是否手机银行活跃客户
             EA03, --手机银行柜面签约时间
             EA04, --距首次登陆天数
             EA05, --距最近一次登陆天数
             FA01, --是否贷款逾期
             FA02, --近24月内是否存在逾期
             FA03, --征信逾期次数
             FA04, --征信是否存在不良贷款记录
             FA05, --最近征信查询日期
             AG12, --客户经理名称
             TO_DATE(V_SYSDAT, 'YYYYMMDD')
        FROM MTS_CUST_LABEL_B;
    COMMIT;
  END IF;

  OUTCDE      := 0;
  V_ERRORTEXT := '判断是否月末，插入存放历史数据表完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --修改 MTS_CUST_LABEL_B 到备用名称   MTS_CUST_LABEL_A               
  EXECUTE IMMEDIATE 'ALTER TABLE MTS_CUST_LABEL_B RENAME TO MTS_CUST_LABEL_A';

  --修改 MTS_CUST_LABEL 到备用名称   MTS_CUST_LABEL_B              

  EXECUTE IMMEDIATE 'ALTER TABLE MTS_CUST_LABEL RENAME TO MTS_CUST_LABEL_B';

  --修改 MTS_CUST_LABEL_A 到备用名称   MTS_CUST_LABEL               

  EXECUTE IMMEDIATE 'ALTER TABLE MTS_CUST_LABEL_A RENAME TO MTS_CUST_LABEL';

  OUTCDE      := 0;
  V_ERRORTEXT := '宽表数据加载量大，缓存完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.SYS_EXC_ANALYZE(INDATE     IN VARCHAR2,
                                              TAB_OWNER IN VARCHAR2,
                                              TAB_NAME   IN VARCHAR2,
                                              LOG_BUTTON IN NUMBER) AUTHID CURRENT_USER AS
  /*
  AUTHOR:SOLIN
  CREATE DATE: 20170901
  CONTENT:表统计信息
  CONTENT:增加执行开关，0为关闭，1为打开。默认关闭
  */
  V_SQL  VARCHAR(1000);
BEGIN
  --PROCEDURE START!
  IF LOG_BUTTON = 1 THEN
    --1表示调试开关为打开，需要计入日志
   --V_SQL :='ANALYZE TABLE '||TAB_OWNER||'.'||TAB_NAME||' COMPUTE STATISTICS';
   --V_SQL :='EXEC DBMS_STATS.GATHER_TABLE_STATS( '''||TAB_OWNER||''','''||TAB_NAME||''',DBMS_STATS.AUTO_SAMPLE_SIZE,TRUE,''FOR ALL COLUMNS SIZE AUTO''';
  --EXECUTE IMMEDIATE  V_SQL;
   DBMS_STATS.GATHER_TABLE_STATS( ownname => TAB_OWNER,TABNAME => TAB_NAME,ESTIMATE_PERCENT => DBMS_STATS.AUTO_SAMPLE_SIZE,CASCADE => TRUE,METHOD_OPT=>'FOR ALL COLUMNS SIZE AUTO');

   COMMIT;
  END IF;
  --PROCEDURE END!
END;
/

