  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AB05';

  INSERT INTO MTS.MTS_CUST_LABEL_AB05
    (AA01, AB05, DATA_DATE)
  
    SELECT T.ECIF_CUST_NO, --ECIF客户号CASE
           CASE
             WHEN LENGTH(T.CERT_NO) = 18 THEN
              TRUNC(MONTHS_BETWEEN(TO_DATE(V_SYSDAT, 'YYYYMMDD'),TO_DATE(SUBSTR(T.CERT_NO, 7, 8),'YYYYMMDD')) / 12)
             WHEN LENGTH(T.CERT_NO) = 15 THEN
              TRUNC(MONTHS_BETWEEN(TO_DATE(V_SYSDAT, 'YYYYMMDD'),TO_DATE('19' || SUBSTR(T.CERT_NO, 7, 6),'YYYYMMDD')) / 12)
             ELSE
              0
           END NL,
           V_SYSDAT
      FROM MTS.ECIF_T01_P_CUST_INFO T
     WHERE T.CERT_TYPE = '01'
       AND MTS.FUN_MTS_CHECKIDCARD(T.CERT_NO) = 1; --身份证校验 身份证校验成功1，其他证件或者身份证校验失败0
     COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AB05', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工年龄处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_AB06(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_AB06
  -- 报表编号：P_MTS_CUST_LABEL_AB06
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '生日到期天数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_AB06'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期加一，用于计算生日到期天数

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_SYSDAT2             := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') + 1,
                                   'yyyymmdd');

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AB06_TMP';

  INSERT INTO MTS.MTS_CUST_LABEL_AB06_TMP
    (ECIF_CUST_NO, SRMMDD)
    SELECT T.ECIF_CUST_NO, --ECIF客户号CASE
           CASE
             WHEN LENGTH(T.CERT_NO) = 18 THEN
              SUBSTR(T.CERT_NO, 11, 4)
             WHEN LENGTH(T.CERT_NO) = 15 THEN
              SUBSTR(T.CERT_NO, 9, 4)
             ELSE
              '9999'
           END SRMMDD
      FROM MTS.ECIF_T01_P_CUST_INFO T
     WHERE T.CERT_TYPE = '01'
       AND MTS.FUN_MTS_CHECKIDCARD(T.CERT_NO) = 1; --身份证校验 身份证校验成功1，其他证件或者身份证校验失败0
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AB06_TMP', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工生日年月数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AB06';

  INSERT INTO MTS.MTS_CUST_LABEL_AB06
    (AA01, AB06, DATA_DATE)
  
    SELECT WY.ECIF_CUST_NO, --ECIF客户号CASE
           CASE
             WHEN WY.SRMMDD IS NOT NULL AND
                  SUBSTR(V_SYSDAT2, 5, 4) <= WY.SRMMDD THEN
              TO_DATE(SUBSTR(V_SYSDAT2, 1, 4) || CASE
                        WHEN WY.SRMMDD = '0229' THEN
                         '0228'
                        ELSE
                         WY.SRMMDD
                      END,
                      'YYYYMMDD') - TO_DATE(V_SYSDAT2, 'YYYYMMDD') -- V_SYSDAT‘+1’ 是吧时间跑批时间向后调一天  计算实际日期距离生日还有多少条
             WHEN WY.SRMMDD IS NOT NULL AND
                  SUBSTR(V_SYSDAT2, 5, 4) > WY.SRMMDD THEN
              TO_DATE((TO_NUMBER(SUBSTR(V_SYSDAT2, 1, 4)) + 1) || CASE
                        WHEN WY.SRMMDD = '0229' THEN
                         '0228'
                        ELSE
                         WY.SRMMDD
                      END,
                      'YYYYMMDD') - TO_DATE(V_SYSDAT2, 'YYYYMMDD') -- V_SYSDAT‘+1’ 是吧时间跑批时间向后调一天  计算实际日期距离生日还有多少条
             ELSE
              9999
           END AB06,
           V_SYSDAT
      FROM MTS.MTS_CUST_LABEL_AB06_TMP WY;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AB06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工生日到期天数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

