CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_AD01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_AD01
  -- 报表编号：P_MTS_CUST_LABEL_AD01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '手机号'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_AD01'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AD01';

  INSERT INTO MTS.MTS_CUST_LABEL_AD01
    (AA01, AD01, DATA_DATE)
  
    SELECT P.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           P.PHONE_NO     AD01, --描述修改有‘手机号(联系电话)’ 修改为 手机号，存放非手机号会影响短信发送 2020年07月17日修改
           V_SYSDAT       DATA_DATE --数据日期 --数据日期
      FROM (SELECT C.ECIF_CUST_NO,
                   B.PHONE_NO,
                   ROW_NUMBER() OVER(PARTITION BY A.PARTY_ID ORDER BY A.LAST_UPDATED_TS DESC) ROWNUM_
              FROM ECIF_T01_P_CUST_INFO C
              LEFT JOIN ECIF_T02_A_CUST_TELE_REL A
                ON C.PARTY_ID = A.PARTY_ID
              LEFT JOIN ECIF_T03_A_TELE_INFO B
                ON A.TELE_ID = B.TELE_ID
             WHERE A.TELE_TYPE = '102' --移动电话
               AND B.PHONE_NO LIKE '1%'
               AND LENGTH(PHONE_NO) = 11) P
     WHERE ROWNUM_ = 1;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AD01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工手机号处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

