    (AA01, AD02, DATA_DATE)
  
    SELECT P.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           T.ADDR_LINE    AD02, --身份证地址
           V_SYSDAT       DATA_DATE --数据日期 --数据日期
      FROM ECIF_T01_P_CUST_INFO P
      LEFT JOIN ECIF_T02_A_CUST_ADDR_REL R
        ON P.PARTY_ID = R.PARTY_ID
       AND R.ADDR_TYPE = '107' --C023 107 户籍地址 联系地址类型
       AND R.UPDATED_TS =
           TO_TIMESTAMP('99991231 00:00:00', 'YYYYMMDD HH24:MI:SS')
      LEFT JOIN ECIF_T03_A_ADDR_INFO T
        ON R.ADDR_ID = T.ADDR_ID
