                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AF04';

  INSERT INTO MTS.MTS_CUST_LABEL_AF04
    (AA01, AF04, DATA_DATE)
  
    SELECT E.ECIF_CUST_NO, '1', V_SYSDAT
      FROM ECIF_T01_C_REL_PSN_INFO   A,
           ECIF_T02_C_PAR_TO_PAR_REL B,
           ECIF_T01_C_CUST_INFO      C,
           CBS_KDPA_ZHXINX           D,
           ECIF_T01_P_CUST_INFO      E
     WHERE A.RELATION_ID = B.RELATION_ID
       AND B.RELATION_TYPE = '4101'
       AND B.PARTY_ID = C.PARTY_ID
       AND C.ECIF_CUST_NO = D.KEHUHAOO
       AND B.REL_CERT_NO = E.CERT_NO
       AND D.ZHUFLDM2 = '109'
     GROUP BY E.ECIF_CUST_NO;
