  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AF05';

  INSERT INTO MTS.MTS_CUST_LABEL_AF05
    (AA01, AF05, DATA_DATE)
  
    SELECT P.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           CASE
             WHEN ZH.ECIFID IS NOT NULL THEN
              1
             ELSE
              0
           END AF05, --是否小微企业主
           V_SYSDAT DATA_DATE --数据日期
      FROM ECIF_T01_P_CUST_INFO P
      LEFT JOIN (SELECT DISTINCT ECIFID
                   FROM CMS_ENT_INFO EI
                  INNER JOIN CMS_CUSTOMER_RELATIVE CR
                     ON EI.CUSTOMERID = CR.CUSTOMERID
                    AND CR.RELATIONSHIP = '0100'
                  WHERE EI.SCOPE IN ('4', '5')) ZH
        ON ZH.ECIFID = P.PARTY_ID;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AF05', '1');

