CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_AG06(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_AG06
  -- 报表编号：P_MTS_CUST_LABEL_AG06
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '纯新户开户标志'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_AG06'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_AG06';

 EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06_TMP01';
  INSERT INTO MTS_CUST_LABEL_AG06_TMP01
    (KEHUHAOO, FXH_MIN_KHRQ)
    SELECT KEHUHAOO, MIN(ZX.KAIHRIQI)
      FROM CBS_KDPA_ZHXINX ZX
     WHERE ZX.ZHHUZTAI <> 'C'
     GROUP BY KEHUHAOO; --非销户账户最小开户日期
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_AG06_TMP01数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签MTS_CUST_LABEL_AG06_TMP02数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06_TMP02';
  INSERT INTO MTS_CUST_LABEL_AG06_TMP02
    (KEHUHAOO, XH_MAX_XHRQ)
    SELECT KEHUHAOO, MAX(ZX.XIOHRIQI)
      FROM CBS_KDPA_ZHXINX ZX
     WHERE ZX.ZHHUZTAI = 'C'
     GROUP BY KEHUHAOO; --销户账户最大销户日期;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_AG06_TMP02数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签MTS_CUST_LABEL_AG06_TMP03数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06_TMP03';
  INSERT INTO MTS_CUST_LABEL_AG06_TMP03
    (KEHUHAOO,
     SFQBUXHU --客户名下账户是否全部销户  1-是 0-否
     )
    SELECT KEHUHAOO,
           CASE
             WHEN SUM(CASE
                        WHEN ZX.ZHHUZTAI = 'C' THEN
                         0
                        ELSE
                         1
                      END) = 0 THEN
              1
             ELSE
              0
           END SFQBUXHU --客户名下账户是否全部销户  1-是 0-否
      FROM CBS_KDPA_ZHXINX ZX
     GROUP BY KEHUHAOO;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_AG06_TMP03数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签MTS_CUST_LABEL_AG06_TMP04数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06_TMP04';
  INSERT INTO MTS_CUST_LABEL_AG06_TMP04
    (ECIF_CUST_NO, OPEN_DATE, FXH_MIN_KHRQ, XH_MAX_XHRQ, SFQBUXHU)
    SELECT P.ECIF_CUST_NO, --ECIF客户号
           TO_CHAR(P.OPEN_DATE, 'YYYYMMDD'), --开户开户日期
           T01.FXH_MIN_KHRQ, --非销户账户最小开户日期
           T02.XH_MAX_XHRQ, --销户账户最大销户日期
           T03.SFQBUXHU --客户名下账户是否全部销户  1-是 0-否
      FROM ECIF_T01_P_CUST_INFO P
      LEFT JOIN MTS_CUST_LABEL_AG06_TMP01 T01
        ON T01.KEHUHAOO = P.ECIF_CUST_NO
      LEFT JOIN MTS_CUST_LABEL_AG06_TMP02 T02
        ON T02.KEHUHAOO = P.ECIF_CUST_NO
      LEFT JOIN MTS_CUST_LABEL_AG06_TMP03 T03
        ON T03.KEHUHAOO = P.ECIF_CUST_NO
     WHERE OWN_ORG < '120000';
  COMMIT;

 --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_AG06_TMP04数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签MTS_CUST_LABEL_AG06_TMP05数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06_TMP05';
  INSERT INTO MTS_CUST_LABEL_AG06_TMP05
    (ECIF_CUST_NO)
    SELECT ECIF_CUST_NO
      FROM MTS_CUST_LABEL_AG06_TMP04 S
     WHERE TO_DATE(V_SYSDAT, 'YYYYMMDD') - TO_DATE(OPEN_DATE, 'YYYYMMDD') < 180
       AND SFQBUXHU = '0'
       AND NOT EXISTS
     (SELECT 1
              FROM MTS_CUST_LABEL_AG06_TMP04 K
             WHERE S.ECIF_CUST_NO = K.ECIF_CUST_NO
               AND TO_DATE(V_SYSDAT, 'yyyymmdd') -
                   TO_DATE(XH_MAX_XHRQ, 'yyyymmdd') < 180);
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_AG06_TMP05数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签MTS_CUST_LABEL_AG06数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS_CUST_LABEL_AG06';
  INSERT INTO MTS_CUST_LABEL_AG06
    (AA01, --客户ID(ECIF客户号)
     AG06, --纯新户开户标志
     DATA_DATE --数据日期
     )
    SELECT P.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           CASE
             WHEN T05.ECIF_CUST_NO IS NULL THEN
              0
             ELSE
              1
           END AG06, --纯新户开户标志
           V_SYSDAT DATA_DATE --数据日期
      FROM ECIF_T01_P_CUST_INFO P
      LEFT JOIN MTS_CUST_LABEL_AG06_TMP05 T05

        ON T05.ECIF_CUST_NO = P.ECIF_CUST_NO
     WHERE P.OWN_ORG < '120000';
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_AG06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工纯新户开户标志处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
