  --身份证校验 通过身份证校验函数校验合规的身份证并打上标记
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_APPACTION';
INSERT /*+append*/
INTO MTS.MTS_CUST_LABEL_APPACTION
  (AA01, --客户id(ecif客户号)
   EA01, --手机银行是否下载登录
   EA02, --是否手机银行活跃客户
   EA03, --手机银行柜面签约时间
   EA04, --距首次登陆天数
   EA05 --距最近一次登陆天数
   )
  SELECT T_01.AA01, T_02.EA01, T_03.EA02, T_04.EA03, T_05.EA04, T_06.EA05
    FROM MTS_CUST_LABEL_AA01 T_01
    LEFT JOIN MTS_CUST_LABEL_EA01 T_02
      ON T_01.AA01 = T_02.AA01
    LEFT JOIN MTS_CUST_LABEL_EA02 T_03
      ON T_01.AA01 = T_03.AA01
    LEFT JOIN MTS_CUST_LABEL_EA03 T_04
      ON T_01.AA01 = T_04.AA01
    LEFT JOIN MTS_CUST_LABEL_EA04 T_05
      ON T_01.AA01 = T_05.AA01
    LEFT JOIN MTS_CUST_LABEL_EA05 T_06
      ON T_01.AA01 = T_06.AA01;

COMMIT;

    --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01对身份证校验打标记数据处理完成'||SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(    V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);

   --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

