  INSERT INTO MTS.MTS_CUST_LABEL_BA01
    (AA01, BA01, DATA_DATE)
  
    SELECT A.AA01, NVL(B.CA02, 0) + NVL(C.CC08, 0) AUM_YRJ, V_SYSDAT
      FROM MTS_CUST_LABEL_AA01 A --ECIF客户号
      LEFT JOIN MTS_CUST_LABEL_CA02 B --存款月日均
        ON A.AA01 = B.AA01
      LEFT JOIN MTS_CUST_LABEL_CC08 C --  理财月日均
        ON A.AA01 = C.AA01;
