  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');



  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BA05';

  INSERT INTO MTS.MTS_CUST_LABEL_BA05
    (AA01, BA05, DATA_DATE)
 
 SELECT T.AA01,
        SUM(T.BA01 * SUBSTR(TO_CHAR(T.DATA_DATE, 'YYYYMMDD'), 7, 2)) /
        SUM(SUBSTR(TO_CHAR(DATA_DATE, 'YYYYMMDD'), 7, 2)) BA05 ,V_SYSDAT
   FROM (SELECT T.AA01, T.BA01, T.DATA_DATE
           FROM MTS_CUST_LABEL_HIS T
          WHERE T.DATA_DATE > TRUNC(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 'Q')
            AND T.DATA_DATE < TO_DATE(V_SYSDAT, 'YYYYMMDD')  --获取本季度，除当月外的数据
         UNION ALL
         SELECT T.AA01, T.BA01, TO_DATE(V_SYSDAT, 'YYYYMMDD') --获取本季度，当月数据
           FROM MTS_CUST_LABEL_BA01 T) T
  GROUP BY T.AA01;
 COMMIT;

