  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BA06';
  --客户的理财，普通存款（活期，定期），智能存款（乐惠存、智慧存），大额存单等余额汇总
  INSERT INTO MTS.MTS_CUST_LABEL_BA06
    (AA01, BA06, DATA_DATE)
    SELECT A.AA01, NVL(B.CA01, 0) + NVL(C.CC07, 0) AUM_YRJ, V_SYSDAT
      FROM MTS_CUST_LABEL_AA01 A --ECIF客户号
      LEFT JOIN MTS_CUST_LABEL_CA01 B --存款余额
        ON A.AA01 = B.AA01
      LEFT JOIN MTS_CUST_LABEL_CC07 C --  理财余额
        ON A.AA01 = C.AA01;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_BA06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工AUM余额数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

