CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_BA12(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_BA12
  -- 报表编号：P_MTS_CUST_LABEL_BA12
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '综合客户星级'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_BA12'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BA12';

INSERT INTO MTS.MTS_CUST_LABEL_BA12
  (AA01, BA12, DATA_DATE)

  WITH CL AS
   (
    
    SELECT A.AA01,
            NVL(F.CF01, 0) CF01,
            NVL(B.CA02, 0) * E.CX_RATE + NVL(C.CC08, 0) * E.LC_RATE +
            NVL(D.CD04, 0) * E.DK_RATE CL
      FROM MTS_CUST_LABEL_AA01 A --ecif 客户ID
      LEFT JOIN MTS_CUST_LABEL_CA02 B --存款月日均
        ON A.AA01 = B.AA01
      LEFT JOIN MTS_CUST_LABEL_CC08 C --理财月日均
        ON A.AA01 = C.AA01
      LEFT JOIN MTS_CUST_LABEL_CD04 D --贷款月日均
        ON A.AA01 = D.AA01
      LEFT JOIN MTS_CUST_LABEL_CF01 F --是否睡眠户
        ON A.AA01 = F.AA01
      LEFT JOIN (SELECT CX_RATE, LC_RATE, DK_RATE
                   FROM (SELECT S.CX_RATE,
                                S.LC_RATE,
                                S.DK_RATE,
                                ROW_NUMBER() OVER(ORDER BY S.D_DATE DESC) AS RN
                           FROM MTS_PROFIT_RATE S) --创利表，数据由前台页面添加
                  WHERE RN = 1) E
        ON 1 = 1)
  
  SELECT A.AA01,
         CASE
           WHEN A.CF01 = '1' THEN
            '0'
           WHEN A.CF01 = '0' AND A.CL >= 0 AND A.CL < 500 THEN
            '1'
           WHEN A.CF01 = '0' AND A.CL >= 500 AND A.CL < 2000 THEN
            '2'
           WHEN A.CF01 = '0' AND A.CL >= 2000 AND A.CL < 5000 THEN
            '3'
           WHEN A.CF01 = '0' AND A.CL >= 5000 AND A.CL < 10000 THEN
            '4'
           WHEN A.CF01 = '0' AND A.CL >= 10000 AND A.CL < 50000 THEN
            '5'
           WHEN A.CF01 = '0' AND A.CL >= 50000 THEN
            '6'
         END ZHXJ,
         V_SYSDAT
    FROM CL A;
COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_BA12', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工综合客户星级处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

