CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_BB02(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_BB02
  -- 报表编号：P_MTS_CUST_LABEL_BB02
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1. ----生命周期初始化 一年内开户为新增。一年以上的，星级为0则为衰退 大于0小于4的为发展客户 4星及4星以上为成熟
  /* 3、处理逻辑： 01 新增、02发展、03成熟、04衰退、05流失。
  上个月无星级（每个月计算一次），则为新增；
  如果当月计算星级比上个月计算星级高并且比上两个月的星级高则为发展客户；
  如果上个月为发展客户，并且联系三个月的计算星级相同，则为成熟客户；
  如果上个月为成熟客户，并且连续两个月发生星级下降，则为衰退客户；
  如过连续三个月计算星级为0则为流失客户；
  其他情况保持上个月的状态不变。*/
  --***************************************
  V_RPTNAME VARCHAR2(100) := '发展阶段'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_BB02'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL        VARCHAR2(4000);
  V_ERRORTEXT  VARCHAR2(4000);
  V_START_DT   DATE;
  V_LOGSEC     NUMBER(10);
  NUM          NUMBER;
  V_LAST_MONTH VARCHAR2(8);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;
  V_LAST_MONTH          := TO_CHAR(LAST_DAY(TO_DATE(V_SYSDAT, 'yyyymmdd')),
                                   'yyyymmdd');

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  SELECT COUNT(1) INTO NUM FROM MTS_CUST_LABEL_BB02 WHERE ROWNUM = 1;
  IF (NUM = 0) THEN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BB02';
    INSERT INTO MTS.MTS_CUST_LABEL_BB02
      (AA01, BB02, DATA_DATE)
      SELECT A.AA01,
             CASE
               WHEN A.BB01 <= 365 THEN
                '01'
               WHEN A.BB01 > 365 AND B.BA12 = 0 THEN
                '04'
               WHEN A.BB01 > 365 AND B.BA12 >= 1 AND B.BA12 < 4 THEN
                '02'
               WHEN A.BB01 > 365 AND B.BA12 >= 4 THEN
                '03'
             END BB02,
             V_SYSDAT
        FROM MTS_CUST_LABEL_BB01 A, MTS_CUST_LABEL_BA12 B
       WHERE A.AA01 = B.AA01;
    COMMIT;
  ELSIF (V_LAST_MONTH = V_SYSDAT) THEN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BB02';
    INSERT INTO MTS.MTS_CUST_LABEL_BB02
      (AA01, BB02, DATA_DATE)
      SELECT A.AA01,
             CASE
               WHEN B.BA12 IS NULL THEN
                '01'
               WHEN A.BA12 > B.BA12 AND A.BA12 > C.BA12 AND A.BA12 > D.BA12 THEN
                '02'
               WHEN B.BB02 = '02' AND A.BA12 = B.BA12 AND A.BA12 = C.BA12 THEN
                '03'
               WHEN C.BB02 = '03' AND C.BA12 > B.BA12 AND C.BA12 > A.BA12 THEN
                '04'
               WHEN A.BA12 = B.BA12 AND A.BA12 = C.BA12 AND A.BA12 = 0 THEN
                '05'
               ELSE
                B.BB02
             END,
             V_SYSDAT
        FROM MTS_CUST_LABEL_BA12 A
        LEFT JOIN MTS_CUST_LABEL_HIS B
          ON A.AA01 = B.AA01
         AND B.DATA_DATE =
             TRUNC(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 0), 'MM') - 1 --上月末
        LEFT JOIN MTS_CUST_LABEL_HIS C
          ON A.AA01 = C.AA01
         AND C.DATA_DATE =
             TRUNC(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -1), 'MM') - 1 --上上月尛
        LEFT JOIN MTS_CUST_LABEL_HIS D
          ON A.AA01 = D.AA01
         AND D.DATA_DATE =
             TRUNC(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -2), 'MM') - 1; --上上月末
    COMMIT;
  ELSE
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BB02 WHERE DATA_DATE=V_SYSDAT';
    INSERT INTO MTS.MTS_CUST_LABEL_BB02
      (AA01, BB02, DATA_DATE)
      SELECT T.ECIF_CUST_NO, '01', V_SYSDAT
        FROM MTS.ECIF_T01_P_CUST_INFO T
       WHERE T.OPEN_DATE = TO_DATE(V_SYSDAT, 'YYYYMMDD');
    COMMIT;
  END IF;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_BB02', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工发展阶段处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_BB03(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_BB03
  -- 报表编号：P_MTS_CUST_LABEL_BB03
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '忠诚度分值'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_BB03'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  --分步得分 1 基础资料得分
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BB03_TMP';

  INSERT INTO MTS_CUST_LABEL_BB03_TMP
    (AA01, BB03_TMP, DATA_TYPE)
    SELECT A.AA01,
           CASE
             WHEN DECODE(C.AB01, NULL, 0, 1) + DECODE(D.AB02, NULL, 0, 1) +
                  DECODE(E.AD01, NULL, 0, 1) + DECODE(F.AB04, NULL, 0, 1) = 4 THEN
              10
             ELSE
              10 -
              2 *
              (4 - (DECODE(C.AB01, NULL, 0, 1) + DECODE(D.AB02, NULL, 0, 1) +
              DECODE(E.AD01, NULL, 0, 1) + DECODE(F.AB04, NULL, 0, 1)))
           END + --四要素
           2 * (DECODE(G.NAT_CODE, NULL, 0, 1) +
           DECODE(G.CERT_DUE_DATE, NULL, 0, 1) +
           DECODE(H.AF02, NULL, 0, 1) +
           DECODE(NVL(I.AD03, J.AD04), NULL, 0, 1) +
           DECODE(K.AB03, NULL, 0, 1)), --四要素+五要素
           '1' --基础资料得分
      FROM MTS_CUST_LABEL_AA01 A
      LEFT JOIN MTS_CUST_LABEL_AB01 C --姓名
        ON A.AA01 = C.AA01
      LEFT JOIN MTS_CUST_LABEL_AB02 D --身份证号
        ON A.AA01 = D.AA01
      LEFT JOIN MTS_CUST_LABEL_AD01 E --手机号
        ON A.AA01 = E.AA01
      LEFT JOIN MTS_CUST_LABEL_AB04 F --性别
        ON A.AA01 = F.AA01
      LEFT JOIN ECIF_T01_P_CUST_INFO G --国籍 --证件有效期
        ON A.AA01 = G.ECIF_CUST_NO
      LEFT JOIN MTS_CUST_LABEL_AF02 H --职业
        ON A.AA01 = H.AA01
      LEFT JOIN MTS_CUST_LABEL_AD03 I --家庭地址
        ON A.AA01 = I.AA01
      LEFT JOIN MTS_CUST_LABEL_AD04 J --单位地址
        ON A.AA01 = J.AA01
      LEFT JOIN MTS_CUST_LABEL_AB03 K --证件类型
        ON A.AA01 = K.AA01;
  COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '加工基础资料分值处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --分步得分 2交易笔数

  INSERT INTO MTS_CUST_LABEL_BB03_TMP
    (AA01, BB03_TMP, DATA_TYPE)
    SELECT A.KEHUHAOO,
           CASE
             WHEN A.JYBS >= 10 THEN
              20
             WHEN A.JYBS >= 7 AND A.JYBS <= 9 THEN
              17
             WHEN A.JYBS >= 5 AND A.JYBS <= 6 THEN
              15
             WHEN A.JYBS >= 3 AND A.JYBS <= 4 THEN
              13
             WHEN A.JYBS = 2 THEN
              10
             WHEN A.JYBS = 1 THEN
              6
             ELSE
              2
           END,
           '2' --交易笔数得分
      FROM (SELECT XX.KEHUHAOO, COUNT(*) JYBS
              FROM CBS_KDPL_ZHMINX MX
              LEFT JOIN CBS_KDPA_ZHXINX XX
                ON MX.ZHANGHAO = XX.ZHANGHAO
             WHERE MX.JIAOYIRQ >=
                   TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -3),
                           'YYYYMMDD') --近三个月
               AND MX.JIAOYIRQ <= V_SYSDAT
               AND MX.XIANZZBZ = '1' --1 代表转账 
               AND MX.QDAOLEIX <> '990' --交易渠道不等‘990’
               AND NVL(XX.KEHUHAOO, 'ISNULL') <> 'ISNULL'
               AND MX.CHONGZBZ = '0' --要未冲正的数据
             GROUP BY XX.KEHUHAOO) A;
  COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '加工交易笔数分值处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --分步得分 3 产品覆盖 

  INSERT INTO MTS_CUST_LABEL_BB03_TMP
    (AA01, BB03_TMP, DATA_TYPE)
    SELECT A.AA01, NVL(B.CG01, 0) * 30 / 4 CPFGDF, '3' --产品覆盖得分
      FROM MTS_CUST_LABEL_AA01 A
      LEFT JOIN MTS_CUST_LABEL_CG01 B --产品持有
        ON A.AA01 = B.AA01;
  COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '加工产品覆盖分值处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --分步得分  4 签约得分

  INSERT INTO MTS_CUST_LABEL_BB03_TMP
    (AA01, BB03_TMP, DATA_TYPE)
    SELECT A.AA01, NVL(C.CG02, 0) * 30 / 12 QYDF, '4' --签约得分
      FROM MTS_CUST_LABEL_AA01 A
      LEFT JOIN MTS_CUST_LABEL_CG02 C --渠道签约
        ON A.AA01 = C.AA01;
  COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '加工渠道签约分值处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_BB03';

  INSERT INTO MTS.MTS_CUST_LABEL_BB03
    (AA01, BB03, DATA_DATE)
  
    SELECT T.AA01, SUM(T.BB03_TMP), V_SYSDAT
      FROM MTS_CUST_LABEL_BB03_TMP T
     GROUP BY T.AA01;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_BB03', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工忠诚度分值处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_BB04(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_BB04
  -- 报表编号：P_MTS_CUST_LABEL_BB04
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '忠诚度'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_BB04'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
