  INSERT INTO MTS.MTS_CUST_LABEL_CA18
    (AA01, CA18, DATA_DATE)

    SELECT T.AA01, SUM(CA16*SUBSTR(TO_CHAR(DATA_DATE,'YYYYMMDD'),7,2))/SUM(SUBSTR(TO_CHAR(DATA_DATE,'YYYYMMDD'),7,2))  BA02,V_SYSDAT
      FROM MTS_CUST_LABEL_HIS T
