  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CA20';

  INSERT INTO MTS.MTS_CUST_LABEL_CA20
    (AA01, CA20, DATA_DATE)

     SELECT T.AA01, SUM(CA16*SUBSTR(TO_CHAR(DATA_DATE,'YYYYMMDD'),7,2))/SUM(SUBSTR(TO_CHAR(DATA_DATE,'YYYYMMDD'),7,2))  BA02,V_SYSDAT
      FROM MTS_CUST_LABEL_HIS T
     WHERE T.DATA_DATE >
           TO_DATE(SUBSTR(TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'),-12),'YYYYMMDD'),1,6) || '01','YYYYMMDD')
       AND T.DATA_DATE <
           TO_DATE(SUBSTR(V_SYSDAT, 1, 6) || '01', 'YYYYMMDD')
     GROUP BY T.AA01;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CA20', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工上12个月定期存款月日均处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

