CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CA27(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CA27
  -- 报表编号：P_MTS_CUST_LABEL_CA27
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '乐惠存产品月日均余额'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CA27'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  V_DAYS                NUMBER;

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  V_DAYS                := SUBSTR(V_SYSDAT, 7, 2);

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CA27';

  INSERT INTO MTS.MTS_CUST_LABEL_CA27
    (AA01, CA27, DATA_DATE)
  
    SELECT A.ECIF_CUST_NO, ROUND(SUM(A.BZ_02) / V_DAYS, 2), V_SYSDAT
      FROM MTS_CUST_OWER_PROD A
     WHERE A.PROD_B_TYPE = '03' --乐惠存产品
     GROUP BY A.ECIF_CUST_NO;
