CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CA38(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CA38
  -- 报表编号：P_MTS_CUST_LABEL_CA38
  -- 处理周期：日
