  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '最近一笔大额存单到期天数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CA38'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CA38';

  INSERT INTO MTS.MTS_CUST_LABEL_CA38
    (AA01, CA38, DATA_DATE)
  
    SELECT A.ECIF_CUST_NO,
           MIN(TO_NUMBER(TO_DATE(A.END_DATE, 'YYYY-MM-DD') -
                         TO_DATE(V_SYSDAT, 'YYYY-MM-DD'))) DQTS, --最近一笔大额存单产品到期天数
           V_SYSDAT
      FROM MTS_CUST_OWER_PROD A
     WHERE A.PROD_B_TYPE = '05' --大额存单
       AND A.DAOQI_FLAG = '1' --未到期
       AND A.JINE > 0
     GROUP BY A.ECIF_CUST_NO;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CA38', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工最近一笔大额存单到期天数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CB01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CB01
  -- 报表编号：P_MTS_CUST_LABEL_CB01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '最近一笔大额存单到期金额'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CB01'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CB01';

  INSERT INTO MTS.MTS_CUST_LABEL_CB01
    (AA01, CB01, DATA_DATE)
  
    WITH LHCDQTS AS
     (SELECT A.ECIF_CUST_NO, MIN(A.END_DATE) DOQIRIQI --最近一笔大额存单产品到期日期
        FROM MTS_CUST_OWER_PROD A
       WHERE A.PROD_B_TYPE = '05'
         AND A.DAOQI_FLAG = '1' --大额存单 未到期
       GROUP BY A.ECIF_CUST_NO)
    SELECT LHCDQTS.ECIF_CUST_NO AA01, --ECIF客户号
           SUM(NVL(B.JINE, 0)) CB01, --最近一笔大额存单产品到期金额
           V_SYSDAT
      FROM MTS_CUST_OWER_PROD B
     INNER JOIN LHCDQTS
        ON B.ECIF_CUST_NO = LHCDQTS.ECIF_CUST_NO
       AND B.END_DATE = LHCDQTS.DOQIRIQI
     WHERE B.PROD_B_TYPE = '05'
       AND B.DAOQI_FLAG = '1' --大额存单 未到期
     GROUP BY LHCDQTS.ECIF_CUST_NO;
  
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CB01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工最近一笔大额存单到期金额处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CC01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CC01
  -- 报表编号：P_MTS_CUST_LABEL_CC01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '是否持有第三方存管'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CC01'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CC01';
  
  INSERT INTO MTS.MTS_CUST_LABEL_CC01
    (AA01, CC01, DATA_DATE)
  
    SELECT ECIF_CUST_NO, '1', V_SYSDAT
      FROM (SELECT I.ECIF_CUST_NO, --ECIF客户号
                   SUM(CASE
                         WHEN S.SIGN_TYPE = '311' AND S.SIGN_STATE = '1' THEN
                          1
                         ELSE
                          0
                       END) COUNT_SJ --三方存管签约次数
              FROM MTS.ECIF_T01_P_CUST_INFO I
              LEFT JOIN MTS.ECIF_T02_A_CUST_SIGN_REL S
                ON S.PARTY_ID = I.PARTY_ID
               AND S.SIGN_STATE <> '2'
             GROUP BY I.ECIF_CUST_NO)
     WHERE COUNT_SJ > 0;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CC01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否持有第三方存管处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

