BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CC06';

  INSERT INTO MTS.MTS_CUST_LABEL_CC06
    (AA01, CC06, DATA_DATE)
    SELECT A.ECIF_CUST_NO, A.JINE, V_SYSDAT
      FROM (SELECT T.ECIF_CUST_NO,
                   T.END_DATE,
                   SUM(T.JINE) JINE,
                   ROW_NUMBER() OVER(PARTITION BY T.ECIF_CUST_NO ORDER BY T.END_DATE ASC) ROW_NUMBER
              FROM MTS_CUST_OWER_PROD T
             WHERE T.PROD_B_TYPE IN ('06', '07') -- 理财
               AND T.DAOQI_FLAG = '1' --未到期
               AND T.END_DATE >= V_SYSDAT
             GROUP BY T.ECIF_CUST_NO, T.END_DATE) A
     WHERE ROW_NUMBER = 1;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CC06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工最近一笔理财到期金额处理完成' || SUBSTR(SQLERRM, 1, 1000);
