  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工天添宝开放式理财产品余额处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
