  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '封闭式理财产品月日均余额'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CC18'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  V_DAYS                NUMBER;


BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  V_DAYS                := SUBSTR(V_SYSDAT, 7, 2);


  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CC18';

  INSERT INTO MTS.MTS_CUST_LABEL_CC18
    (AA01, CC18, DATA_DATE)
  
    SELECT A.ECIF_CUST_NO, ROUND(SUM(A.BZ_02) / V_DAYS, 2), V_SYSDAT
      FROM MTS_CUST_OWER_PROD A
     WHERE A.PROD_B_TYPE = '06' --封闭式理财产品
     GROUP BY A.ECIF_CUST_NO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CC18', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工封闭式理财产品月日均余额数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

