   SELECT HOST_CUST_NO, CUST_RISK_LEVEL ,V_SYSDAT
     FROM (SELECT F2.HOST_CUST_NO, --ECIF客户号
                  F1.CUST_RISK_LEVEL,
                  ROW_NUMBER() OVER(PARTITION BY F2.HOST_CUST_NO ORDER BY F1.ASSESS_DATE DESC) ROW_NUMBER
             FROM FMS_T4_CUST_RISK_ASSESS_INFO F1
             JOIN FMS_T1_CUST_INFO F2
               ON F1.CUST_NO = F2.CUST_NO)
