  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_LOG_BUTTON          VARCHAR2(2);


BEGIN

 V_START_DT := SYSDATE;
   --调试日志打开
 V_LOG_BUTTON := 1;
  --日志打印
  
  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
 


  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD05';

  INSERT INTO MTS.MTS_CUST_LABEL_CD05
    (AA01, CD05, DATA_DATE)
  
 SELECT T.AA01,
        SUM(T.CD04 * SUBSTR(TO_CHAR(T.DATA_DATE, 'YYYYMMDD'), 7, 2)) /
        SUM(SUBSTR(TO_CHAR(DATA_DATE, 'YYYYMMDD'), 7, 2)) CD04 ,V_SYSDAT
   FROM (SELECT T.AA01, T.CD04, T.DATA_DATE
           FROM MTS_CUST_LABEL_HIS T
          WHERE T.DATA_DATE > TRUNC(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 'Q')
            AND T.DATA_DATE < TO_DATE(V_SYSDAT, 'YYYYMMDD')  --获取本季度，除当月外的数据
         UNION ALL
         SELECT T.AA01, T.CD04, TO_DATE(V_SYSDAT, 'YYYYMMDD') --获取本季度，当月数据
           FROM MTS_CUST_LABEL_CD04 T) T
  GROUP BY T.AA01;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD05', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工贷款余额季日均处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CD06(V_SYSDAT IN VARCHAR2,
