BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 'Y'),'YYYYMMDD'); --年初
  P_INTERVAL_END_DATE   := V_SYSDAT;
  DATE_DT :=(TO_DATE(V_SYSDAT, 'YYYYMMDD') + 1) - TRUNC(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 'Y');

  --调试日志打开
