        SUM(SUBSTR(TO_CHAR(DATA_DATE, 'YYYYMMDD'), 7, 2)) CD04,
        V_SYSDAT
   FROM (SELECT T.AA01, T.CD04, T.DATA_DATE
           FROM MTS_CUST_LABEL_HIS T
          WHERE T.DATA_DATE > TRUNC(TO_DATE(V_SYSDAT, 'YYYYMMDD'), 'Y')
            AND T.DATA_DATE < TO_DATE(V_SYSDAT, 'YYYYMMDD') --获取年初，除当月外的数据
         UNION ALL
         SELECT T.AA01, T.CD04, TO_DATE(V_SYSDAT, 'YYYYMMDD') --获取，当月数据
           FROM MTS_CUST_LABEL_CD04 T) T
  GROUP BY T.AA01;
 COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工贷款余额年日均处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
