CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CD10(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CD10
  -- 报表编号：P_MTS_CUST_LABEL_CD10
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '是否历史住房按揭贷已结清客户'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CD10'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD10';

  INSERT INTO MTS.MTS_CUST_LABEL_CD10
    (AA01, CD10, DATA_DATE)
    SELECT MFCUSTOMERID, '1', V_SYSDAT
      FROM (SELECT B.MFCUSTOMERID,
                   SUM(NVL(A.NORMALBALANCE, 0) + NVL(A.OVERDUEBALANCE, 0)) JINE
              FROM CMS_ACCT_LOAN A, CMS_CUSTOMER_INFO B
             WHERE A.CUSTOMERID = B.CUSTOMERID
               AND A.BUSINESSTYPE IN ('LI1120020',
                                      'LI1120021',
                                      'LI1120025',
                                      'LI1120026',
                                      'LI1120028')
               AND A.FINISHDATE IS NOT NULL
               AND B.MFCUSTOMERID IS NOT NULL
             GROUP BY MFCUSTOMERID)
     WHERE JINE = 0;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD10', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否历史住房按揭贷已结清客户处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

