  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD14';
  
  INSERT INTO MTS.MTS_CUST_LABEL_CD14
    (AA01, CD14, DATA_DATE)
  
    SELECT C.MFCUSTOMERID, --核心客户号
           B.BUSINESSSUM - B.BALANCE KYED, --白领贷可用额度金额
           V_SYSDAT
      FROM CMS_CUSTOMER_INFO C,
           (SELECT CL.CUSTOMERID,
                   SUM(CL.BUSINESSSUM) BUSINESSSUM,
                   SUM(NVL(CL.NORMALBALANCE + CL.OVERDUEBALANCE, 0)) BALANCE,
                   COUNT(1) SERIALNO
              FROM CMS_ACCT_LOAN CL
             WHERE CL.BUSINESSTYPE = 'LI1120010'
               AND (CL.FINISHDATE IS NULL OR CL.FINISHDATE = '')
             GROUP BY CL.CUSTOMERID) B
     WHERE C.CUSTOMERID = B.CUSTOMERID
       AND NVL(C.MFCUSTOMERID, 'ISNULL') <> 'ISNULL';
  COMMIT;

  --统计信息收集
