  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '房产抵押贷款中最高房产抵押率'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CD22'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD22';

  INSERT INTO MTS.MTS_CUST_LABEL_CD22
    (AA01, CD22, DATA_DATE)
  
    SELECT E.MFCUSTOMERID, MAX(A.GUARANTYRATE), V_SYSDAT
      FROM CMS_GUARANTY_INFO     A,
           CMS_GUARANTY_RELATIVE B,
           CMS_CONTRACT_RELATIVE C,
           CMS_ACCT_LOAN         D,
           CMS_CUSTOMER_INFO     E
     WHERE A.GUARANTYTYPE LIKE '01001%'
       AND B.OBJECTTYPE = 'BusinessContract'
       AND A.GUARANTYID = B.GUARANTYID
       AND B.OBJECTNO = C.SERIALNO
       AND C.SERIALNO = D.CONTRACTSERIALNO
       AND C.OBJECTTYPE = 'GuarantyContract'
       AND D.CUSTOMERID = E.CUSTOMERID
       AND A.GUARANTYSTATUS <> '04'
       AND E.MFCUSTOMERID IS NOT NULL
     GROUP BY E.MFCUSTOMERID;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD22', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工房产抵押贷款中最高房产抵押率处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
