  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD24';

  INSERT INTO MTS.MTS_CUST_LABEL_CD24
    (AA01, CD24, DATA_DATE)
