  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD25';

  INSERT INTO MTS.MTS_CUST_LABEL_CD25
    (AA01, CD25, DATA_DATE)
    SELECT C3.MFCUSTOMERID, --核心客户号
           SUM(C1.ACTUALPAYPRINCIPALAMT + C1.ACTUALPAYINTERESTAMT) CD25, --房贷月还款金额（本行）
           V_SYSDAT
      FROM CMS_ACCT_PAYMENT_SCHEDULE C1
      JOIN CMS_ACCT_LOAN C2
        ON C1.OBJECTNO = C2.SERIALNO
      JOIN CMS_CUSTOMER_INFO C3
        ON C2.CUSTOMERID = C3.CUSTOMERID
     WHERE C2.BUSINESSTYPE IN
           ('LI1120020', 'LI1120021', 'LI1120025', 'LI1120026', 'LI1120028')
       AND SUBSTR(C1.PAYDATE, 1, 4) || SUBSTR(C1.PAYDATE, 6, 2) =
           SUBSTR(V_SYSDAT, 1, 6)
       AND C3.MFCUSTOMERID IS NOT NULL
     GROUP BY C3.MFCUSTOMERID;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD25', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工房贷月还款金额（本行）处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CD26(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CD26
  -- 报表编号：P_MTS_CUST_LABEL_CD26
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '房贷连续还款月数（本行）'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_CD26'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  --房贷连续还款月数（一个客户可能有多笔记录）
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD26_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_CD26_TMP01
    (MFCUSTOMERID, --核心客户号
     CD26 --房贷连续还款月数（一个客户可能有多笔记录）
     )
    WITH ZJYQQC AS
     (SELECT C1.OBJECTNO, --借据号
             C2.CUSTOMERID, --客户编号
             MAX(C1.PERIODNO) ZJYQ_PERIODNO --最近一次逾期期次
        FROM CMS_ACCT_PAYMENT_SCHEDULE C1
        JOIN CMS_ACCT_LOAN C2
          ON C1.OBJECTNO = C2.SERIALNO
       WHERE TO_DATE(C1.PAYDATE, 'YYYY-MM-DD') <=
             TO_DATE(V_SYSDAT, 'YYYY-MM-DD')
         AND C1.FINISHDATE IS NULL
         AND C1.OBJECTTYPE = 'jbo.acct.ACCT_LOAN'
         AND C2.BUSINESSTYPE IN ('LI1120020',
                                 'LI1120021',
                                 'LI1120025',
                                 'LI1120026',
                                 'LI1120028')
       GROUP BY C1.OBJECTNO, C2.CUSTOMERID),
    DQQC AS
     (SELECT C1.OBJECTNO, --借据号
             C2.CUSTOMERID, --客户编号
             C1.PERIODNO --当前期次
        FROM CMS_ACCT_PAYMENT_SCHEDULE C1
        JOIN CMS_ACCT_LOAN C2
          ON C1.OBJECTNO = C2.SERIALNO
       WHERE SUBSTR(C1.PAYDATE, 1, 4) || SUBSTR(C1.PAYDATE, 6, 2) =
             SUBSTR(V_SYSDAT, 1, 6)
         AND C2.BUSINESSTYPE IN ('LI1120020',
                                 'LI1120021',
                                 'LI1120025',
                                 'LI1120026',
                                 'LI1120028'))
    SELECT CMS.MFCUSTOMERID, --核心客户号
           (CASE
             WHEN ZJYQQC.ZJYQ_PERIODNO IS NOT NULL THEN
              DQQC.PERIODNO - ZJYQQC.ZJYQ_PERIODNO
             ELSE
              DQQC.PERIODNO
           END) CD26 --房贷连续还款月数（一个客户可能有多笔记录）
      FROM CMS_CUSTOMER_INFO CMS
     INNER JOIN DQQC
        ON CMS.CUSTOMERID = DQQC.CUSTOMERID
      LEFT JOIN ZJYQQC
        ON ZJYQQC.OBJECTNO = DQQC.OBJECTNO
     WHERE NVL(CMS.CUSTOMERID, 'XDHWK') != 'XDHWK'
       AND NVL(CMS.MFCUSTOMERID, 'HXKHHWK') != 'HXKHHWK';
  COMMIT;
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CD26';

  INSERT INTO MTS.MTS_CUST_LABEL_CD26
    (AA01, CD26, DATA_DATE)
    SELECT ECIF.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           (CASE
             WHEN MAX(CD26) IS NOT NULL THEN
              MAX(CD26)
             ELSE
              0
           END) CD26, --房贷连续还款月数（本行）
           V_SYSDAT --数据日期
      FROM ECIF_T01_P_CUST_INFO ECIF
      LEFT JOIN MTS_CUST_LABEL_CD26_TMP01 MTS
        ON ECIF.ECIF_CUST_NO = MTS.MFCUSTOMERID
     GROUP BY ECIF.ECIF_CUST_NO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CD26', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工房贷连续还款月数（本行）处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

