CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CE01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 是否代发户
  -- 报表编号：MTS_CUST_LABEL_CE01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '是否代发户'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_CE01'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_LAST_MONTH VARCHAR2(8);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT   := SYSDATE;
  V_LAST_MONTH := FUN_LAST_DATE(V_SYSDAT, 2);
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE01';

  INSERT INTO MTS.MTS_CUST_LABEL_CE01
    (AA01, CE01, DATA_DATE)
    SELECT M.ECIF_CUST_NO AA01,
           CASE
             WHEN N.ECIF_CUST_NO IS NOT NULL THEN
              '1'
             ELSE
              '0'
           END CE01,
           V_SYSDAT
      FROM ECIF_T01_P_CUST_INFO M
      LEFT JOIN (
                 ------------------通过客户号关联- 代发工资
                 SELECT A.AA01 ECIF_CUST_NO
                   FROM MTS_CUST_LABEL_CE02 A
                  WHERE CE02 = '1' --代发工资
                 
                 ------------------通过证件号关联- 社保-惠民-省社保
                 UNION
                 SELECT M.ECIF_CUST_NO AA01
                   FROM ECIF_T01_P_CUST_INFO M
                  INNER JOIN (SELECT T.PAYEE_ID, T.PAYEE_NAME, T.COLL_ACCOUNT
                                FROM IBP_CZDF_BAT_DETAIL T,
                                     IBP_CZDF_BAT_INFO   A
                               WHERE A.BATCH_NO = T.BATCH_NO
                                 AND A.CREATE_TIME >=
                                     SUBSTR(V_LAST_MONTH, 1, 6) || '01'
                                 AND A.CREATE_TIME <= V_LAST_MONTH
                                 AND T.STATUS = '2'
                               GROUP BY T.BANK_NAME,
                                        T.PAYEE_ID,
                                        T.PAYEE_NAME,
                                        T.COLL_ACCOUNT -- 惠民惠农成功数据
                              UNION
                              SELECT T.IDNO    PAYEE_ID,
                                     T.NAME    PAYEE_NAME,
                                     T.ACCT_NO COLL_ACCOUNT
                                FROM IBP_LSSB_TRANS_DETAIL T,
                                     IBP_LSSB_BAT_INFO     A
                               WHERE A.BATCH_NO = T.BATCH_NO
                                 AND T.STATUS = '2'
                                 AND A.BUILD_TIME >=
                                     SUBSTR(V_LAST_MONTH, 1, 6) || '01'
                                 AND A.BUILD_TIME <= V_LAST_MONTH
                               GROUP BY T.IDNO, T.NAME, T.ACCT_NO -- 市社保成功数据
                              UNION
                              SELECT T.ID_NO PAYEE_ID,
                                     T.NAME  PAYEE_NAME,
                                     T.ACCT  COLL_ACCOUNT
                                FROM IBP_SCSB_BAT_DETAIL T,
                                     IBP_SCSB_BAT_INFO   A
                               WHERE A.BAT_NO = T.BAT_NO
                                 AND T.STATUS = '2'
                               GROUP BY T.ID_NO, T.NAME, T.ACCT -- 省保成功数据
                              
                              ) N
                     ON M.CERT_NO = N.PAYEE_ID
                 
                 ) N
        ON M.ECIF_CUST_NO = N.ECIF_CUST_NO;

  COMMIT;
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CE01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否代发户数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

