  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE05';

  INSERT INTO MTS.MTS_CUST_LABEL_CE05
    (AA01, CE05, DATA_DATE)
    SELECT A.KEHUHAOO, SUM(A.ZHUANZJE), V_SYSDAT
      FROM (SELECT B.KEHUZHAO, B.ZHUANZJE, B.KEHUHAOO
              FROM (SELECT B.KEHUZHAO,
                           A.JIAOYIRQ,
                           B.ZHUANZJE,
                           C.KEHUHAOO,
                           ROW_NUMBER() OVER(PARTITION BY C.KEHUHAOO ORDER BY A.JIAOYIRQ DESC) ROW_NUMBER
                      FROM CBS_KIBB_PLDLMX B
                      LEFT JOIN CBS_KIBB_PLDLYW A
                        ON A.WEITUOHO = B.WEITUOHO
                      LEFT JOIN CBS_KDPA_KEHUZH C
                        ON B.KEHUZHAO = C.KEHUZHAO
                     WHERE A.JIAOYIMA = '1600'
                       AND A.XITONGBS IN ('1001', '2002', '3001')
                       AND NVL(C.KEHUZHAO, 'SINULL') <> 'SINULL') B
             WHERE ROW_NUMBER = 1) A
     GROUP BY A.KEHUHAOO;

  COMMIT;
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CE05', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '最近一次代发工资金额' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

