CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CE07(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 是否代发户
  -- 报表编号：MTS_CUST_LABEL_CE07
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '连续稳定代发工资月数'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_CE07'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_OUTCDE    NUMBER; --日期判断返回码
  V_RSTCDE    NUMBER; --日期判断返回码
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_COUNT      NUMBER;
  V_MINDATE    VARCHAR2(8);
  V_NEXTDATE   VARCHAR2(8);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  V_COUNT      := 0;
  --条件为变量的SQL处理
  SELECT COUNT(1) INTO V_COUNT FROM MTS_CUST_LABEL_CE07_TMP_02;
  --初始化数据
  --循环所有代发日期
  IF (V_COUNT = 0) THEN
    SELECT MIN(A.JIAOYIRQ)
      INTO V_MINDATE
      FROM CBS_KIBB_PLDLYW A
     WHERE A.JIAOYIMA = '1600'
       AND A.XITONGBS IN ('1001', '2002', '3001');
    V_NEXTDATE := TO_CHAR(ADD_MONTHS(TO_DATE(V_MINDATE, 'YYYYMMDD'), -1),
                          'YYYYMMDD');
    --V_MINDATE 20200904 CYC 获取代发工资最小月份-1 ，方便后边后边根据最大未代发计算连续代发
    WHILE (V_NEXTDATE <= V_SYSDAT) LOOP
      INSERT INTO MTS_CUST_LABEL_CE07_TMP_02 VALUES (V_NEXTDATE);
      COMMIT;
      V_NEXTDATE := TO_CHAR(TO_DATE(V_NEXTDATE, 'YYYYMMDD') + 1, 'YYYYMMDD');
    END LOOP;
    --保存所有代发月份
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE07_TMP_03';
    INSERT INTO MTS_CUST_LABEL_CE07_TMP_03
      SELECT SUBSTR(A.D_DATE, 1, 6)
        FROM MTS_CUST_LABEL_CE07_TMP_02 A
       GROUP BY SUBSTR(A.D_DATE, 1, 6);
    COMMIT;
    --初始化所有代发客户月份
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE07_TMP_01';
    INSERT INTO MTS_CUST_LABEL_CE07_TMP_01
      SELECT C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6) NY
        FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
       WHERE A.WEITUOHO = B.WEITUOHO
         AND B.KEHUZHAO = C.KEHUZHAO
         AND A.JIAOYIMA = '1600'
         AND A.XITONGBS IN ('1001', '2002', '3001')
       GROUP BY C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6);
    COMMIT;
    
  OUTCDE      := 0;
  V_ERRORTEXT := '初始化数据' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
    
    ELSE
    DELETE FROM MTS_CUST_LABEL_CE07_TMP_03 A
     WHERE A.D_DATE = SUBSTR(V_SYSDAT, 1, 6);
    COMMIT;
    INSERT INTO MTS_CUST_LABEL_CE07_TMP_03 VALUES (SUBSTR(V_SYSDAT, 1, 6));
    COMMIT;
    DELETE FROM MTS_CUST_LABEL_CE07_TMP_01
     WHERE NY = SUBSTR(V_SYSDAT, 1, 6);
    COMMIT;
    INSERT INTO MTS_CUST_LABEL_CE07_TMP_01
      SELECT C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6) NY
        FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
       WHERE A.WEITUOHO = B.WEITUOHO
         AND B.KEHUZHAO = C.KEHUZHAO
         AND A.JIAOYIMA = '1600'
         AND A.XITONGBS IN ('1001', '2002', '3001')
         AND A.JIAOYIRQ >= SUBSTR(V_SYSDAT, 1, 6) || '01'
         AND A.JIAOYIRQ <= V_SYSDAT
       GROUP BY C.KEHUHAOO, SUBSTR(A.JIAOYIRQ, 1, 6);
    COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '当月数据' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);   
  END IF;

  
    --求最大未发代发月份
   EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE07_04';
    INSERT INTO MTS_CUST_LABEL_CE07_04
      SELECT KEHUHAOO, MAX(D_DATE) D_DATE
        FROM (SELECT D_DATE, B.KEHUHAOO
                FROM  MTS_CUST_LABEL_CE07_TMP_03 A
               LEFT JOIN (SELECT  KEHUHAOO
                            FROM MTS_CUST_LABEL_CE07_TMP_01 M GROUP BY KEHUHAOO) B
                  ON 1 = 1
                LEFT JOIN MTS_CUST_LABEL_CE07_TMP_01 C
                  ON B.KEHUHAOO || A.D_DATE = C.KEHUHAOO || C.NY
               WHERE C.NY IS NULL)
       GROUP BY KEHUHAOO;
       
  OUTCDE      := 0;
  V_ERRORTEXT := '最大未代发月份' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);         
   EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CE07';
   
    INSERT INTO MTS_CUST_LABEL_CE07
      (AA01, CE07, DATA_DATE)
      SELECT B.KEHUHAOO,
             MONTHS_BETWEEN(TO_DATE(SUBSTR(V_SYSDAT, 1, 6) || '01',
                                    'YYYYMMDD'),
                            TO_DATE(B.D_DATE || '01', 'YYYYMMDD')) LXDFYS,
             V_SYSDAT
        FROM MTS_CUST_LABEL_CE07_04 B;
    COMMIT;
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CE07', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '连续稳定代发工资月数完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CF01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CF01
  -- 报表编号：P_MTS_CUST_LABEL_CF01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '是否睡眠户'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_CF01'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_LASTYEAR  VARCHAR2(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN
  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  V_LASTYEAR := TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -12),
                        'YYYYMMDD');
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  -----睡眠户 客户名下的所有账户余额汇总低于100元，一年内无主动动账交易
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CF01';
  INSERT INTO MTS_CUST_LABEL_CF01
    SELECT A.KEHUHAOO, '1', V_SYSDAT
      FROM CBS_KDPA_ZHXINX A
     WHERE A.KAIHRIQI < V_LASTYEAR
       AND A.SCYWRIQI < V_LASTYEAR
       AND A.ZHHUYUEE < 100
       AND NOT EXISTS (SELECT 1
              FROM MTS_CUST_LABEL_CD03 D
             WHERE A.KEHUHAOO = D.AA01
               AND D.CD03 > 0)
     GROUP BY A.KEHUHAOO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CF01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否睡眠户处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CF02(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_CF02
  -- 报表编号：P_MTS_CUST_LABEL_CF02
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '借记卡级别'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CF02'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CF02';

  INSERT INTO MTS.MTS_CUST_LABEL_CF02
    (AA01, CF02, DATA_DATE)
  
    WITH JJKJB AS
     (SELECT ECIF.ECIF_CUST_NO AA01, MAX(CBS.VIPPTKBZ) JB
        FROM ECIF_T01_P_CUST_INFO ECIF
        LEFT JOIN CBS_KCDA_PZJCXX CBS
          ON ECIF.ECIF_CUST_NO = CBS.KEHUHAOO
       GROUP BY ECIF.ECIF_CUST_NO)
    SELECT AA01,
           (CASE
             WHEN JB = '0' OR JB = '1' THEN
              '02'
             WHEN JB = '2' THEN
              '03'
             WHEN JB = '6' THEN
              '04'
             WHEN JB = '8' THEN
              '05'
             ELSE
              '99'
           END) CF02,
           V_SYSDAT
      FROM JJKJB;
      
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CF02', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工借记卡级别处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

