      FROM (SELECT AA01, CH01
              FROM MTS_CUST_LABEL_CH01
            UNION ALL
            SELECT AA01, CH02
              FROM MTS_CUST_LABEL_CH02
            UNION ALL
            SELECT AA01, CH03
              FROM MTS_CUST_LABEL_CH03
            UNION ALL
            SELECT AA01, CH04
              FROM MTS_CUST_LABEL_CH04
            UNION ALL
            SELECT AA01, CH05
              FROM MTS_CUST_LABEL_CH05
            UNION ALL
            SELECT AA01, CH06
              FROM MTS_CUST_LABEL_CH06
            UNION ALL
            SELECT AA01, CH07
              FROM MTS_CUST_LABEL_CH07
            UNION ALL
            SELECT AA01, CH08
              FROM MTS_CUST_LABEL_CH08
            UNION ALL
            SELECT AA01, CH09
              FROM MTS_CUST_LABEL_CH09
            UNION ALL
            SELECT AA01, CH10
              FROM MTS_CUST_LABEL_CH10
            UNION ALL
            SELECT AA01, CH11
              FROM MTS_CUST_LABEL_CH11
            UNION ALL
            SELECT AA01, CH12 FROM MTS_CUST_LABEL_CH12)
     GROUP BY AA01;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CG02', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工渠道签约数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
