  -- 报表编号：MTS_CUST_LABEL_CH06
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '是否签约云闪付'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CH06'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := SUBSTR(TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -7),
                              'YYYYMMDD'),
                      1,
                      6) || '01';

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CH06';

  INSERT INTO MTS.MTS_CUST_LABEL_CH06
    (AA01, CH06, DATA_DATE)
    SELECT B.KEHUHAOO, '1', V_SYSDAT
      FROM NIPP_YW_CUPS_YWLS T
     INNER JOIN CBS_KDPA_KEHUZH B
        ON T.YHZH = B.KEHUZHAO
     WHERE YWRQ >= V_SYSDAT2
       AND JYDM = '802183'--
       AND ORESPCODE = '00'
       AND SHLX = '6400'
       AND SUBSTR(FSJGBS, 1, 4) = '0004'
     GROUP BY B.KEHUHAOO;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CH06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否签约云闪付数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

