    (AA01, CH11, DATA_DATE)
  
    WITH ZZZC AS
     (SELECT DISTINCT CUST_CORE_NO --移动银行客户号
        FROM MBS_CUST_INFO
       WHERE CUST_CAP_LVL IN ('02')
         AND CUST_STATUS != '0'
         AND TO_NUMBER(TO_DATE(V_SYSDAT, 'YYYY-MM-DD') -
                       TO_DATE(CUST_OPEN_DATE, 'YYYY-MM-DD')) >= 1)
    SELECT ECIF_CUST_NO AA01, --ECIF客户号
           (CASE
             WHEN ZZZC.CUST_CORE_NO IS NOT NULL THEN
              1
             ELSE
              0
           END) CH11, --是否自助注册手机银行
           V_SYSDAT
      FROM ECIF_T01_P_CUST_INFO ECIF
      LEFT JOIN ZZZC
        ON ECIF.ECIF_CUST_NO = ZZZC.CUST_CORE_NO;
  COMMIT;

  --统计信息收集
