  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CH12';

  INSERT INTO MTS.MTS_CUST_LABEL_CH12
    (AA01, CH12, DATA_DATE)
  
    WITH GMQY AS
     (SELECT DISTINCT CUST_CORE_NO --移动银行客户号
        FROM MBS_CUST_INFO A
       WHERE A.CUST_STATUS != '0'
         AND CUST_CAP_LVL IN ('03'))
    SELECT ECIF_CUST_NO AA01, --ECIF客户号
           (CASE
             WHEN GMQY.CUST_CORE_NO IS NOT NULL THEN
              1
             ELSE
              0
           END) CH12, --是否柜面签约手机银行
           V_SYSDAT
      FROM ECIF_T01_P_CUST_INFO ECIF
      LEFT JOIN GMQY
        ON ECIF.ECIF_CUST_NO = GMQY.CUST_CORE_NO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_CH12', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工是否柜面签约手机银行处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

