CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_CUSTVALUE(V_SYSDAT IN VARCHAR2,
                                                       OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户价值加工
  -- 报表编号：P_MTS_CUST_LABEL_CUSTVALUE
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户价值加工'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_CUSTVALUE'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;

  --身份证校验 通过身份证校验函数校验合规的身份证并打上标记
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_CUSTVALUE';
  INSERT /*+append*/
  INTO MTS.MTS_CUST_LABEL_CUSTVALUE
    (AA01, --客户id(ecif客户号)
     BA01, --aum月日均
     BA02, --近3月aum日均
     BA03, --近6月aum日均
     BA04, --近12月aum日均
     BA05, --资产余额季日均
     BA06, --aum余额
     BA07, --近3月aum余额_min
     BA08, --近3月aum余额_max
     BA09, --较上日aum变动
     BA10, --较年初aum变动
     CF01, --是否睡眠户
     BA11, --crm客户等级
     BA12, --综合客户星级
     BB01, --开户天数
     BB02, --发展阶段
     BB03, --忠诚度分值
     BB04 --忠诚度
     )
    SELECT T_01.AA01,
           T_02.BA01,
           T_03.BA02,
           T_04.BA03,
           T_05.BA04,
           T_06.BA05,
           T_07.BA06,
           T_08.BA07,
           T_09.BA08,
           T_10.BA09,
           T_11.BA10,
           T_12.CF01,
           T_13.BA11,
           T_14.BA12,
           T_15.BB01,
           T_16.BB02,
           T_17.BB03,
           T_18.BB04
      FROM MTS_CUST_LABEL_AA01 T_01
      LEFT JOIN MTS_CUST_LABEL_BA01 T_02
        ON T_01.AA01 = T_02.AA01
      LEFT JOIN MTS_CUST_LABEL_BA02 T_03
        ON T_01.AA01 = T_03.AA01
      LEFT JOIN MTS_CUST_LABEL_BA03 T_04
        ON T_01.AA01 = T_04.AA01
      LEFT JOIN MTS_CUST_LABEL_BA04 T_05
        ON T_01.AA01 = T_05.AA01
      LEFT JOIN MTS_CUST_LABEL_BA05 T_06
        ON T_01.AA01 = T_06.AA01
      LEFT JOIN MTS_CUST_LABEL_BA06 T_07
        ON T_01.AA01 = T_07.AA01
      LEFT JOIN MTS_CUST_LABEL_BA07 T_08
        ON T_01.AA01 = T_08.AA01
      LEFT JOIN MTS_CUST_LABEL_BA08 T_09
        ON T_01.AA01 = T_09.AA01
      LEFT JOIN MTS_CUST_LABEL_BA09 T_10
        ON T_01.AA01 = T_10.AA01
      LEFT JOIN MTS_CUST_LABEL_BA10 T_11
        ON T_01.AA01 = T_11.AA01
      LEFT JOIN MTS_CUST_LABEL_CF01 T_12
        ON T_01.AA01 = T_12.AA01
      LEFT JOIN MTS_CUST_LABEL_BA11 T_13
        ON T_01.AA01 = T_13.AA01
      LEFT JOIN MTS_CUST_LABEL_BA12 T_14
        ON T_01.AA01 = T_14.AA01
      LEFT JOIN MTS_CUST_LABEL_BB01 T_15
        ON T_01.AA01 = T_15.AA01
      LEFT JOIN MTS_CUST_LABEL_BB02 T_16
        ON T_01.AA01 = T_16.AA01
      LEFT JOIN MTS_CUST_LABEL_BB03 T_17
        ON T_01.AA01 = T_17.AA01
      LEFT JOIN MTS_CUST_LABEL_BB04 T_18
        ON T_01.AA01 = T_18.AA01;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01对身份证校验打标记数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DA01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DA01
  -- 报表编号：P_MTS_CUST_LABEL_DA01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '近1月累计交易笔数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DA01'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DA01';

  INSERT INTO MTS.MTS_CUST_LABEL_DA01
    (AA01, DA01, DATA_DATE)
  
    SELECT XX.KEHUHAOO, COUNT(*), V_SYSDAT
      FROM CBS_KDPL_ZHMINX MX
      LEFT JOIN CBS_KDPA_ZHXINX XX
        ON MX.ZHANGHAO = XX.ZHANGHAO
     WHERE MX.JIAOYIRQ >=
           TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -1),
                   'YYYYMMDD') --近一个月
       AND MX.JIAOYIRQ <= V_SYSDAT
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.QDAOLEIX <> '990' --交易渠道不等‘990’
       AND NVL(XX.KEHUHAOO, 'ISNULL') <> 'ISNULL'
       AND MX.CHONGZBZ = '0' --要未冲正的数据
     GROUP BY XX.KEHUHAOO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工近1月累计交易笔数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

