CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DA04(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DA04
  -- 报表编号：P_MTS_CUST_LABEL_DA04
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '近1月手机银行累计交易金额'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DA04'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DA04';

  INSERT INTO MTS.MTS_CUST_LABEL_DA04
    (AA01, DA04, DATA_DATE)
  
    SELECT ZHXX.KEHUHAOO KEHUHAOO, --客户号
           --COUNT(1) JIOYBS, --交易笔数
           SUM(MX.JIAOYIJE) JIOYJE, --交易金额
           V_SYSDAT DATA_DATE --数据日期
      FROM CBS_KDPA_ZHXINX ZHXX
     INNER JOIN CBS_KDPL_ZHMINX MX
        ON MX.ZHANGHAO = ZHXX.ZHANGHAO
       AND MX.JIAOYIRQ >=
           TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -1),
                   'YYYYMMDD') --近一个月
       AND MX.JIAOYIRQ <= V_SYSDAT
       AND MX.QDAOLEIX = '3031' --手机银行
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.CHONGZBZ = '0' --要未冲正的数据
     GROUP BY ZHXX.KEHUHAOO;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA04', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工近1月手机银行累计交易金额处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DA05(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DA05
  -- 报表编号：P_MTS_CUST_LABEL_DA05
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '签约当日手机银行交易笔数'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_DA05'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_NUM        NUMBER;
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  V_NUM      := 0;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  SELECT COUNT(1) INTO V_NUM FROM MTS_CUST_LABEL_DA05 WHERE ROWNUM = 1;
  IF (V_NUM = 0) THEN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DA05';
    INSERT INTO MTS.MTS_CUST_LABEL_DA05
      (AA01, DA05, DATA_DATE)
      SELECT B.CUST_CORE_NO,
             CASE
               WHEN COUNT(1) > 4 THEN
                4
               ELSE
                COUNT(1)
             END DA06, --交易笔数   交易日期等于签约日期 大于4笔 按4笔计算
             V_SYSDAT DATA_DATE --数据日期
        FROM MBS_CUST_LOG_SIGN A
        LEFT JOIN MBS_CUST_INFO B
          ON A.CUST_NO = B.CUST_NO
        LEFT JOIN CBS_KDPA_ZHXINX C
          ON B.CUST_CORE_NO = C.KEHUHAOO
        LEFT JOIN CBS_KDPL_ZHMINX D
          ON C.ZHANGHAO = D.ZHANGHAO
         AND D.QDAOLEIX = '3031'
         AND D.CHONGZBZ = '0' --要未冲正的数据
         AND REPLACE(A.TRAN_DATE, '-', '') = D.JIAOYIRQ
       WHERE A.LOG_STATUS = '1'
         AND A.ACT_TYPE <> '0' ----签约状态成功 且 没有解约
         AND NVL(B.CUST_CORE_NO, 'ISNULL') <> 'ISNULL'
         AND D.JIAOYIRQ >= '20200107'
       GROUP BY B.CUST_CORE_NO;
    COMMIT;
  ELSE
    DELETE FROM MTS_CUST_LABEL_DA05 A WHERE A.DATA_DATE = V_SYSDAT;
    COMMIT;
    INSERT INTO MTS.MTS_CUST_LABEL_DA05
      (AA01, DA05, DATA_DATE)
      SELECT B.CUST_CORE_NO,
             CASE
               WHEN COUNT(1) > 4 THEN
                4
               ELSE
                COUNT(1)
             END DA06, --交易笔数   交易日期等于签约日期 大于4笔 按4笔计算
             V_SYSDAT DATA_DATE --数据日期
        FROM MBS_CUST_LOG_SIGN A
        LEFT JOIN MBS_CUST_INFO B
          ON A.CUST_NO = B.CUST_NO
        LEFT JOIN CBS_KDPA_ZHXINX C
          ON B.CUST_CORE_NO = C.KEHUHAOO
        LEFT JOIN CBS_KDPL_ZHMINX D
          ON C.ZHANGHAO = D.ZHANGHAO
         AND D.QDAOLEIX = '3031'
         AND REPLACE(A.TRAN_DATE, '-', '') = V_SYSDAT
         AND D.CHONGZBZ = '0' --要未冲正的数据
       WHERE A.LOG_STATUS = '1'
         AND A.TRAN_DATE = V_SYSDAT
         AND A.ACT_TYPE <> '0' ----签约状态成功 且 没有解约
         AND NVL(B.CUST_CORE_NO, 'ISNULL') <> 'ISNULL'
         AND NOT EXISTS (SELECT 1
                FROM MTS_CUST_LABEL_DA05 DA
               WHERE B.CUST_CORE_NO = DA.AA01)
         AND D.JIAOYIRQ >= '20200107' --个金部（王晓洁）、刘淳宇、梁磊
       GROUP BY B.CUST_CORE_NO;
    COMMIT;
  END IF;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA05', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工签约当日手机银行交易笔数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DA06(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DA06
  -- 报表编号：P_MTS_CUST_LABEL_DA06
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '本年度至今手机银行累计交易笔数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DA06'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := SUBSTR(V_SYSDAT, 1, 4) || '0101';
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  OUTCDE      := 0;
  V_ERRORTEXT := '打印P_INTERVAL_START_DATE' || P_INTERVAL_START_DATE ||
                 'P_INTERVAL_END_DATE' || P_INTERVAL_END_DATE ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DA06';

  INSERT INTO MTS.MTS_CUST_LABEL_DA06
    (AA01, DA06, DATA_DATE)
    SELECT JYMX.CUST_CORE_NO,
           SUM(JYBS) DA06, --交易笔数   交易日期等于签约日期 大于4笔 按4笔计算
           V_SYSDAT DATA_DATE --数据日期
      FROM (SELECT B.CUST_CORE_NO,
                   D.JIAOYIRQ,
                   A.TRAN_DATE,
                   CASE
                     WHEN REPLACE(A.TRAN_DATE, '-', '') = D.JIAOYIRQ AND
                          COUNT(1) > 4 THEN
                      4
                     ELSE
                      COUNT(1)
                   END JYBS --交易笔数   交易日期等于签约日期 大于4笔 按4笔计算
              FROM CBS_KDPL_ZHMINX D
              LEFT JOIN CBS_KDPA_ZHXINX C
                ON D.ZHANGHAO = C.ZHANGHAO
              LEFT JOIN MBS_CUST_INFO B
                ON C.KEHUHAOO = B.CUST_CORE_NO
              LEFT JOIN MBS_CUST_LOG_SIGN A
                ON B.CUST_NO = A.CUST_NO
               AND LOG_STATUS = '1'
               AND ACT_TYPE <> 0
               AND D.JIAOYIRQ = REPLACE(A.TRAN_DATE, '-', '')
             WHERE NVL(B.CUST_CORE_NO, 'ISNULL') <> 'ISNULL'
               AND D.QDAOLEIX = '3031'
               AND D.JIAOYIRQ >= '20200107' --个金部（王晓洁）、刘淳宇、梁磊
               AND D.JIAOYIRQ >= SUBSTR(V_SYSDAT, 1, 4) || '0101' --本年度 
               AND D.CHONGZBZ = '0' --要未冲正的数据
             GROUP BY B.CUST_CORE_NO, D.JIAOYIRQ, A.TRAN_DATE) JYMX
     GROUP BY CUST_CORE_NO;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA06', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工本年度至今手机银行累计交易笔数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

