       AND MX.JIAOYIRQ <= V_SYSDAT
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.JIEDAIBZ = '1' --转入
       AND MX.QDAOLEIX IN ('3201', '3028', '3029', '3030', '3004', '3026')
       AND NVL(XX.KEHUHAOO, 'ISNULL') <> 'ISNULL'
       AND MX.CHONGZBZ = '0' --要未冲正的数据
     GROUP BY XX.KEHUHAOO;

  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA14', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工近1月第三方支付累计转入金额处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

