CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DA20(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DA20
  -- 报表编号：P_MTS_CUST_LABEL_DA20
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '本年度至今第三方交易渠道交易笔数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DA20'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DA20';

  INSERT INTO MTS.MTS_CUST_LABEL_DA20
    (AA01, DA20, DATA_DATE)
  
    SELECT XX.KEHUHAOO, COUNT(1), V_SYSDAT
      FROM CBS_KDPL_ZHMINX MX
      LEFT JOIN CBS_KDPA_ZHXINX XX
        ON MX.ZHANGHAO = XX.ZHANGHAO
     WHERE MX.JIAOYIRQ >= SUBSTR(V_SYSDAT, 1, 4) || '0101' --年初日期 
       AND MX.JIAOYIRQ <= V_SYSDAT
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.QDAOLEIX IN ('3201', '3028', '3029', '3030', '3004', '3026')
       AND NVL(XX.KEHUHAOO, 'ISNULL') <> 'ISNULL'
       AND MX.CHONGZBZ = '0' --要未冲正的数据
     GROUP BY XX.KEHUHAOO;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DA20', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工本年度至今第三方交易渠道交易笔数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

