     WHERE MX.JIAOYIRQ >= SUBSTR(V_SYSDAT, 1, 4) || '0101' --年初日期 
       AND MX.JIAOYIRQ <= V_SYSDAT
       AND MX.XIANZZBZ = '1' --1 代表转账 
       AND MX.QDAOLEIX IN ('3201', '3028', '3029', '3030', '3004', '3026')
       AND NVL(XX.KEHUHAOO, 'ISNULL') <> 'ISNULL'
       AND MX.CHONGZBZ = '0' --要原始数据
     GROUP BY XX.KEHUHAOO;
  COMMIT;

  --统计信息收集
