                GROUP BY T.IDNO, T.NAME, T.ACCT_NO -- 市社保成功数据
               UNION
               SELECT T.ID_NO PAYEE_ID, COUNT(1) SUMCOUNT
               
                 FROM IBP_SCSB_BAT_DETAIL T, IBP_SCSB_BAT_INFO A
                WHERE A.BAT_NO = T.BAT_NO
                  AND T.STATUS = '2'
                  AND SUBSTR(T.BAT_NO, 1, 6) >= SUBSTR(V_SYSDAT,1,4)||'01'--'202001' 获取本年度数据
                GROUP BY T.ID_NO, T.NAME, T.ACCT -- 省保成功数据
               
