  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON     VARCHAR2(2);
  V_M_FIRSTD       VARCHAR2(8); --当前跑批日期，月初第一天，用于分区表获取分区名称
  V_PARTITION_NAME VARCHAR2(40); --存放返回分区名称

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2  := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  V_M_FIRSTD := TO_CHAR(LAST_DAY(TO_DATE('20200601', 'YYYYMMDD')) + 1,
                        'YYYYMMDD'); --当前月份下一个月的第一天

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DB07';
  OUTCDE      := SQLCODE;
  V_ERRORTEXT := '清空表MTS_CUST_LABEL_DB07 hight_value' || V_M_FIRSTD ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  MTS.SYS_GET_PARTITION_NAME('MTS',
                             'MTS_CUST_LABEL_HIS',
                             V_M_FIRSTD,
                             V_PARTITION_NAME,
                             OUTCDE);
  IF V_PARTITION_NAME IS NULL THEN
  
    --OUTCDE      := 0;
    V_ERRORTEXT := '返回MTS_CUST_LABEL_HIS的分区名称' || V_PARTITION_NAME ||
                   SUBSTR(SQLERRM, 1, 1000);
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
    V_SQL       := '
INSERT INTO MTS.MTS_CUST_LABEL_DB07 (aa01,DB07,data_date)
SELECT A.AA01,
       CASE WHEN NVL(A.BA01,0)*100/decode(NVL(B.DB04,0),0,1,b.db04) <10 THEN ''1'' ELSE ''0'' END DB07,
       ''' || V_SYSDAT || ''' data_date
  FROM MTS.MTS_CUST_LABEL_BA01 A
  LEFT JOIN MTS.MTS_CUST_LABEL_DB04 B
    ON A.AA01 = B.AA01 ';
    OUTCDE      := 0;
    V_ERRORTEXT := '可执行动态sql：' || V_SQL;
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
  
    EXECUTE IMMEDIATE V_SQL;
    COMMIT;
  ELSE
    --OUTCDE      := 0;
    V_ERRORTEXT := '返回MTS_CUST_LABEL_HIS的分区名称' || V_PARTITION_NAME ||
                   SUBSTR(SQLERRM, 1, 1000);
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
    V_SQL := '
INSERT INTO MTS.MTS_CUST_LABEL_DB07 (aa01,DB07,data_date)
SELECT A.AA01,
       CASE WHEN NVL(C.BA01, A.BA01)*100/DECODE(NVL(C.DB04, B.DB04),0,1,NVL(C.DB04, B.DB04)) <10 THEN ''1'' ELSE ''0'' END DB07,
       ''' || V_SYSDAT ||
             ''' data_date
  FROM MTS.MTS_CUST_LABEL_BA01 A
  LEFT JOIN MTS.MTS_CUST_LABEL_DB04 B
    ON A.AA01 = B.AA01
  LEFT JOIN MTS.MTS_CUST_LABEL_HIS PARTITION(' ||
             V_PARTITION_NAME || ') C
    ON A.AA01 = C.AA01';
  
    OUTCDE      := 0;
    V_ERRORTEXT := '可执行动态sql：' || V_SQL;
    V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
    MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                          V_PRCNAME,
                          V_RPTNAME,
                          V_ERRORTEXT,
                          V_LOGSEC,
                          V_LOG_BUTTON);
  
    EXECUTE IMMEDIATE V_SQL;
    COMMIT;
  END IF;
  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '是否我行资金过路户数据加工完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DB07', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '收集表MTS_CUST_LABEL_DB07的统计信息' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DB08(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DB08
  -- 报表编号：P_MTS_CUST_LABEL_DB08
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-02
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户基础标签处理_DB08'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DB08'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  --调试日志打开
  V_LOG_BUTTON := 1;

  --是否向他行同名户规律转出
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DB08_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_DB08_TMP01
    (KEHUHAOO, --核心客户号
     DB08 --是否向他行同名户规律转出
     )
    WITH ZCJYRQ AS
     (SELECT C2.KEHUHAOO, --核心客户号
             SUBSTR(C1.JIAOYIRQ, 1, 6) JYRQ --向他行同名户转出日期
        FROM CBS_KDPL_ZHMINX C1
        JOIN CBS_KDPA_ZHXINX C2
          ON C1.KEHUZHAO = C2.KEHUZHAO
       WHERE C1.JIEDAIBZ = '1'
         AND C1.DUIFMINC = C2.ZHHUZWMC
         AND TO_DATE(C1.JIAOYIRQ, 'YYYY-MM-DD') BETWEEN
             ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYY-MM-DD'), -6) AND
             TO_DATE(V_SYSDAT, 'YYYY-MM-DD')
         AND (C1.DUIFJGMC NOT LIKE '%乐山%' OR C1.DUIFJGMC IS NULL)
         AND C1.CHONGZBZ = '0' --要原始数据
       GROUP BY C2.KEHUHAOO, SUBSTR(C1.JIAOYIRQ, 1, 6))
    SELECT KEHUHAOO, --核心客户号
           (CASE
             WHEN COUNT(1) = 6 THEN
              1
             ELSE
              0
           END) DB08 --是否向他行同名户规律转出
      FROM (SELECT KEHUHAOO, --核心客户号
                   JYRQ --向他行同名户转出日期
              FROM ZCJYRQ
             GROUP BY KEHUHAOO, JYRQ)
     GROUP BY KEHUHAOO;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签CUST_LABEL_DB08数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DB08';
  INSERT INTO MTS.MTS_CUST_LABEL_DB08
    (AA01, --客户ID(ECIF客户号)
     DB08, --是否向他行同名户规律转出
     DATA_DATE --数据日期
     )
    SELECT ECIF.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           (CASE
             WHEN MTS.DB08 IS NOT NULL THEN
              MTS.DB08
             ELSE
              '0'
           END) DB08, --是否向他行同名户规律转出
           V_SYSDAT --数据日期
      FROM ECIF_T01_P_CUST_INFO ECIF
      LEFT JOIN MTS_CUST_LABEL_DB08_TMP01 MTS
        ON ECIF.ECIF_CUST_NO = MTS.KEHUHAOO;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签CUST_LABEL_DB08数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DC01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DC01
  -- 报表编号：P_MTS_CUST_LABEL_DC01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '客户基础标签处理_DC01'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_LABEL_DC01'; --存储过程名
  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_LIKE      VARCHAR2(20); --模糊匹配参数定义
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_NUM        NUMBER;
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;
  SELECT COUNT(1)
    INTO V_NUM
    FROM MTS_CUST_LABEL_DC01_TMP01
   WHERE ROWNUM = 1;
  IF (V_NUM = 0) THEN
    V_LIKE := '''' || SUBSTR(V_SYSDAT, 1, 4) || '%''';
  ELSE
    --年度数据匹配参数赋值(跑批时间的上一年)
    V_LIKE := '''' ||
              SUBSTR(TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'YYYYMMDD'), -12),
                             'YYYYMMDD'),
                     1,
                     4) || '%''';
  END IF;
  --交易笔数最多的交易渠道
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC01_TMP01';

  V_SQL := '
INSERT INTO MTS.MTS_CUST_LABEL_DC01_TMP01
  (KEHUHAOO, --核心客户号
   QDAOLEIX --交易笔数最多的交易渠道
   )
  WITH QDJYBS AS
   (SELECT C2.KEHUHAOO, --核心客户号
           (CASE WHEN C1.QDAOLEIX IN (''3014'',''3015'',''3017'',''3106'',''3107'',''3108'',''3113'') 
             THEN ''01''
               WHEN C1.QDAOLEIX IN (''3001'',''3009'',''3008'')
                 THEN ''02''
                 WHEN C1.QDAOLEIX in(''3002'',''3031'')
                    THEN ''03''
                      WHEN C1.QDAOLEIX IN(''3016'',''3018'',''3109'',''3110'',''3111'',''3114'',''3115'')
                    THEN ''04''
                      WHEN C1.QDAOLEIX in(''1001'',''1002'',''1003'',''1004'',''1008'',''1024'',''1025'',''3022'')
                    THEN ''05''
                      WHEN C1.QDAOLEIX in(''3028'',''3201'')
                        THEN ''06''
                          WHEN C1.QDAOLEIX in(''3004'')
                        THEN ''07''
                      ELSE ''99''
                        END) QDAOLEIX, --交易渠道
           COUNT(C1.JIAOYIRQ) JYBS, --每个客户每个交易渠道的交易笔数
           SUM(JIAOYIJE * C3.HL) JINE
      FROM CBS_KDPL_ZHMINX C1
      LEFT JOIN CBS_KDPA_ZHXINX C2
        ON C1.KEHUZHAO = C2.KEHUZHAO
      LEFT JOIN MTS_SYS_XTHLCS C3
        ON C2.HUOBDAIH = C3.HUOBDAIH
     WHERE C1.JIAOYIRQ LIKE ' || V_LIKE ||
           ' AND c1.qdaoleix<>''990'' 
           AND NVL(C2.KEHUHAOO,''ISNULL'') <> ''ISNULL''
     GROUP BY C2.KEHUHAOO, C1.QDAOLEIX)
  
  SELECT KEHUHAOO, QDAOLEIX
    FROM (SELECT KEHUHAOO,
                 QDAOLEIX,
                 ROW_NUMBER() OVER(PARTITION BY KEHUHAOO ORDER BY JYBS DESC,JINE DESC ) ROW_NUMBER
            FROM QDJYBS)
   WHERE ROW_NUMBER = 1';

  OUTCDE      := 0;
  V_ERRORTEXT := '可执行动态sql：' || V_SQL;
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  EXECUTE IMMEDIATE V_SQL;

  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签CUST_LABEL_DC01数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC01';
  INSERT INTO MTS.MTS_CUST_LABEL_DC01
    (AA01, --客户ID(ECIF客户号)
     DC01, --渠道偏好
     DATA_DATE --数据日期
     )
    SELECT ECIF.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           QDAOLEIX          DC01, --渠道偏好
           V_SYSDAT --数据日期
      FROM ECIF_T01_P_CUST_INFO ECIF
     INNER JOIN MTS_CUST_LABEL_DC01_TMP01 MTS
        ON ECIF.ECIF_CUST_NO = MTS.KEHUHAOO;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工渠道偏好数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DC02(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DC02
  -- 报表编号：P_MTS_CUST_LABEL_DC02
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '储蓄产品偏好'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DC02'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);
  V_LASTYEAR            VARCHAR2(8);
  V_DAYS                NUMBER;
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  P_INTERVAL_START_DATE := TO_CHAR(TRUNC(ADD_MONTHS(TO_DATE(V_SYSDAT,
                                                            'yyyy-mm-dd'),
                                                    -12),
                                         'yyyy'),
                                   'YYYYMMDD');
  P_INTERVAL_END_DATE   := TO_CHAR(TRUNC(TO_DATE(V_SYSDAT, 'YYYY-MM-DD'),
                                         'yyyy') - 1,
                                   'YYYYMMDD');
  V_LASTYEAR            := FUN_LAST_DATE(V_SYSDAT, 5);
  SELECT TO_DATE(V_LASTYEAR, 'YYYYMMDD') -
         TO_DATE(SUBSTR(V_LASTYEAR, 1, 4) || '0101', 'YYYYMMDD') + 1
    INTO V_DAYS
    FROM DUAL;
  --调试日志打开
  V_LOG_BUTTON := 1;

  --智惠存账户
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC02_TMP02';
  INSERT INTO MTS.MTS_CUST_LABEL_DC02_TMP02
    SELECT CBS.KEHUHAOO ECIF_CUST_NO, ECIF.SIGN_ACC_NO
      FROM ECIF_T02_A_CUST_SIGN_REL ECIF
     INNER JOIN CBS_KDPA_ZHXINX CBS
        ON ECIF.SIGN_ACC_NO = CBS.KEHUZHAO
     WHERE ECIF.SIGN_TYPE = '217' --签约类型为智惠存
       AND CBS.ZHHUZTAI = 'A' --账户状态为正常
       AND CBS.FZCPLEIX = '0' --负债产品类型为活期产品
       AND ECIF.SIGN_STATE = '1' --签约状态为签约
     GROUP BY CBS.KEHUHAOO, ECIF.SIGN_ACC_NO;
  COMMIT;
  ------各个产品上年日均
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC02_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_DC02_TMP01
    (ECIF_CUST_NO, --ECIF客户号
     CXCP, --储蓄产品    
     SNRJ --上一年的日均(除智惠存)
     )
    SELECT B.KEHUHAOO,
           CASE
             WHEN B.CUNKZLEI = '00' THEN
              '01'
             WHEN B.CUNKZLEI IN ('01', '02', '03', '04', '05', '06', '07') THEN
              '02'
             WHEN B.CUNKZLEI = '29' THEN
              '03'
             WHEN B.CUNKZLEI = '26' THEN
              '05'
           END CPLX,
           ROUND(SUM(JALJISHU + FEBJISHU + MARJISHU + APRJISHU + MAYJISHU +
                     JUNJISHU + JULJISHU + AUGJISHU + SEPJISHU + OCTJISHU +
                     NOVJISHU + DECJISHU) / V_DAYS,
                 2) NRJ
      FROM CBS_KDPB_YUPJYE A, CBS_KDPA_ZHXINX B
     WHERE A.KEHUZHAO = B.KEHUZHAO
       AND A.NIANNNNN = SUBSTR(V_LASTYEAR, 1, 4)
       AND NOT EXISTS (SELECT 1
              FROM MTS_CUST_LABEL_DC02_TMP02 C
             WHERE A.KEHUZHAO = C.SIGN_ACC_NO)
     GROUP BY B.KEHUHAOO,
              CASE
                WHEN B.CUNKZLEI = '00' THEN
                 '01'
                WHEN B.CUNKZLEI IN
                     ('01', '02', '03', '04', '05', '06', '07') THEN
                 '02'
                WHEN B.CUNKZLEI = '29' THEN
                 '03'
                WHEN B.CUNKZLEI = '26' THEN
                 '05'
              END;
  COMMIT;
  INSERT INTO MTS.MTS_CUST_LABEL_DC02_TMP01
    (ECIF_CUST_NO, --ECIF客户号
     CXCP, --储蓄产品    
     SNRJ --上一年的日均(智惠存)
     )
    SELECT B.KEHUHAOO,
           '04' CPLX,
           ROUND(SUM(JALJISHU + FEBJISHU + MARJISHU + APRJISHU + MAYJISHU +
                     JUNJISHU + JULJISHU + AUGJISHU + SEPJISHU + OCTJISHU +
                     NOVJISHU + DECJISHU) / V_DAYS,
                 2)
      FROM CBS_KDPB_YUPJYE           A,
           CBS_KDPA_ZHXINX           B,
           MTS_CUST_LABEL_DC02_TMP02 C
     WHERE A.KEHUZHAO = B.KEHUZHAO
       AND A.KEHUZHAO = C.SIGN_ACC_NO
       AND A.NIANNNNN = SUBSTR(V_LASTYEAR, 1, 4)
     GROUP BY B.KEHUHAOO;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC02';

  INSERT INTO MTS.MTS_CUST_LABEL_DC02
    (AA01, DC02, DATA_DATE)
    SELECT A.ECIF_CUST_NO, A.CXCP, V_SYSDAT DATA_DATE
      FROM (SELECT A.ECIF_CUST_NO,
                   A.CXCP,
                   ROW_NUMBER() OVER(PARTITION BY A.ECIF_CUST_NO ORDER BY A.SNRJ DESC) ROWNUM_
              FROM MTS_CUST_LABEL_DC02_TMP01 A) A
     WHERE ROWNUM_ = 1;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_DC02', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工储蓄产品偏好数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DC03(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DC03
  -- 报表编号：P_MTS_CUST_LABEL_DC03
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户基础标签处理_DC03'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DC03'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_LASTYEAR   VARCHAR2(8);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2  := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');
  V_LASTYEAR := FUN_LAST_DATE(V_SYSDAT, 5);
  --调试日志打开
  V_LOG_BUTTON := 1;

  --用户持有的不同期限乐惠存的数目
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC03_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_DC03_TMP01
    (KEHUHAOO, --核心客户号
     QX, --期限
     LHCCYS, --用户持有的不同期限乐惠存的数目
     JYJE)
    SELECT C.HOST_CUST_NO,
           CASE
             WHEN TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) <= 1 THEN
              '01'
             WHEN TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) < 4 AND
                  TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) > 1 THEN
              '02'
             ELSE
              '03'
           END INC_DUE,
           COUNT(1),
           SUM(A.TRANS_AMT) JYJE
      FROM CDS_TB_CUST_TRANS_LOG_H A,
           CDS_TB_PROD_PUB_INFO    B,
           CDS_T1_CUST_INFO        C
     WHERE A.PROD_CODE = B.PROD_CODE
       AND A.CUST_NO = C.CUST_NO
       AND A.TRANS_DATE >= SUBSTR(V_LASTYEAR, 1, 4) || '0101'
       AND A.TRANS_DATE <= V_LASTYEAR
       AND A.TRANS_TYPE = '02' --购买
       AND A.TRANS_STATUS = '02' 
       AND B.PROD_SUBCLASS ='3' --乐慧存
     GROUP BY C.HOST_CUST_NO,
              CASE
                WHEN TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) <= 1 THEN
                 '01'
                WHEN TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) < 4 AND
                     TO_NUMBER(SUBSTR(B.INC_DUE, 2) / 12) > 1 THEN
                 '02'
                ELSE
                 '03'
              END;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
                        
                        
                                              
  --加工标签CUST_LABEL_DC03数据
 EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC03';
 INSERT INTO MTS.MTS_CUST_LABEL_DC03
   (AA01, --客户ID(ECIF客户号)
    DC03, --乐惠存期限偏好
    DATA_DATE --数据日期
    )
   SELECT KEHUHAOO, QX, V_SYSDAT
     FROM (SELECT T.KEHUHAOO,
                  T.QX,
                  ROW_NUMBER() OVER(PARTITION BY T.KEHUHAOO ORDER BY T.LHCCYS DESC, JYJE DESC) ROW_NUMBER
             FROM MTS_CUST_LABEL_DC03_TMP01 T) T1
    WHERE T1.ROW_NUMBER = 1;
 COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签CUST_LABEL_DC03数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DC04(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DC04
  -- 报表编号：P_MTS_CUST_LABEL_DC04
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-03
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户基础标签处理_DC04'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DC04'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;

  --用户持有的不同期限储蓄产品数目
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC04_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_DC04_TMP01
    (ECIF_CUST_NO, --核心客户号
     QX, --交易笔数最多的交易渠道
     CXCPCYS, --用户持有的不同期限储蓄产品数目
     JINE)
    WITH CXQX AS
     (SELECT T.ECIF_CUST_NO, --核心客户号
             (CASE
               WHEN T.QINXIAN IN ('5Y', '6Y') THEN
                '03'
               WHEN T.QINXIAN IN ('2Y', '3Y') THEN
                '02'
               ELSE
                '01'
             END) QX, -- 普通活期、普通定期、乐惠存、大额存单的签约期限
             T.JINE
        FROM MTS_CUST_OWER_PROD T
       WHERE (T.ZHANGHAO_TYPE IN
             ('01', '02', '03', '04', '05', '06', '07', '26', '29') OR
             T.PROD_B_TYPE = '04')
         AND SUBSTR(T.BEGIN_DATE, 1, 4) = SUBSTR(V_SYSDAT, 1, 4) - 1)
    SELECT ECIF_CUST_NO, --核心客户号
           QX, ---- 储蓄期限
           COUNT(*) CXCPCYS, --用户持有的不同期限储蓄产品数目
           SUM(JINE)
      FROM CXQX
     GROUP BY ECIF_CUST_NO, QX;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);


  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP02数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签CUST_LABEL_DC04数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC04';
  INSERT INTO MTS.MTS_CUST_LABEL_DC04
    (AA01, --客户ID(ECIF客户号)
     DC04, --储蓄期限偏好
     DATA_DATE --数据日期
     )
    SELECT ECIF_CUST_NO, QX, V_SYSDAT
      FROM (SELECT T.ECIF_CUST_NO,
                   QX,
                   ROW_NUMBER() OVER(PARTITION BY T.ECIF_CUST_NO ORDER BY T.CXCPCYS DESC, JINE DESC) ROW_NUMBER
              FROM MTS_CUST_LABEL_DC04_TMP01 T) T1
     WHERE T1.ROW_NUMBER = 1;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签CUST_LABEL_DC04数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_DC05(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_DC05
  -- 报表编号：P_MTS_CUST_LABEL_DC05
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-02
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户基础标签处理_DC05'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_DC05'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  --调试日志打开
  V_LOG_BUTTON := 1;

  --理财签约期限
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC05_TMP01';
  INSERT INTO MTS.MTS_CUST_LABEL_DC05_TMP01
    (ECIF_CUST_NO, --理财客户号
     QX, --理财签约期限
     JINE
     )
    SELECT T.ECIF_CUST_NO, --理财客户号
           (CASE
             WHEN T.QINXIAN <= 365 THEN
              '01'
             WHEN 365 < T.QINXIAN AND T.QINXIAN < 1095 THEN
              '02'
             ELSE
              '03'
           END) QX, -- 理财签约期限
           T.JINE
      FROM MTS_CUST_OWER_PROD T
     WHERE T.PROD_B_TYPE IN ('06', '07') --06 封闭理财  07 开放式理财
       AND T.BEGIN_DATE <= V_SYSDAT;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --用户持有的不同期限理财的数目
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC05_TMP02';
  INSERT INTO MTS.MTS_CUST_LABEL_DC05_TMP02
    (ECIF_CUST_NO, --理财客户号
     QX, --理财签约期限
     LCCYS ,--用户持有的不同期限理财的数目
     JINE
     )
    SELECT ECIF_CUST_NO, --理财客户号
           QX, ---- 理财签约期限
           COUNT(*) LCCYS, --用户持有的不同期限理财的数目
           SUM(JINE)
      FROM MTS_CUST_LABEL_DC05_TMP01
     GROUP BY ECIF_CUST_NO, QX;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP02数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --加工标签CUST_LABEL_DC05数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_DC05';
  INSERT INTO MTS.MTS_CUST_LABEL_DC05
    (AA01, --客户ID(ECIF客户号)
     DC05, --理财产品期限偏好
     DATA_DATE --数据日期
     )
    SELECT ECIF_CUST_NO, QX, V_SYSDAT
      FROM (SELECT T.ECIF_CUST_NO,
                   QX,
                   ROW_NUMBER() OVER(PARTITION BY T.ECIF_CUST_NO ORDER BY T.LCCYS DESC,JINE DESC) ROW_NUMBER
              FROM MTS_CUST_LABEL_DC05_TMP02 T) T1
     WHERE T1.ROW_NUMBER = 1;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签CUST_LABEL_DC05数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_EA01(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_EA01
  -- 报表编号：P_MTS_CUST_LABEL_EA01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '手机银行是否下载登录'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_EA01'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_EA01';

  INSERT INTO MTS.MTS_CUST_LABEL_EA01
    (AA01, EA01, DATA_DATE)
    SELECT B.CUST_CORE_NO AA01, --客户ID(ECIF客户号)
           CASE
             WHEN C.FIRST_LGN_DATE IS NOT NULL THEN
              1
             ELSE
              0
           END,
           V_SYSDAT
      FROM MBS_CUST_INFO B
     INNER JOIN MBS_CUST_LOGIN_AUTH C
        ON B.CUST_NO = C.CUST_NO
     WHERE B.CUST_STATUS != '0'
       AND C.FIRST_LGN_FLAG = 'Y'
       AND B.CUST_CORE_NO IS NOT NULL;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_EA01', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工手机银行是否下载登录处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

