  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  /*
       v_sql :='
           ';
       execute immediate v_sql;
       commit;
  */

  /*  标签说明
  AA01     --客户ID(ECIF客户号)
  EA02     --是否手机银行活跃客户
    */

  --加工标签EA02数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_EA02';
  INSERT INTO MTS.MTS_CUST_LABEL_EA02
    (AA01, --客户ID(ECIF客户号)
     EA02, --是否手机银行活跃客户
     DATA_DATE --数据日期
     )
    SELECT A.AA01, --客户ID(ECIF客户号)
           (CASE
             WHEN A.DA06 >= 6 THEN
              1
             ELSE
              0
           END) EA02, --是否手机银行活跃客户
           V_SYSDAT DATA_DATE --数据日期
      FROM MTS.MTS_CUST_LABEL_DA06 A;

    --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_EA02数据处理完成'||SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(    V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);

   --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
