CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_EA04(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_EA04
  -- 报表编号：P_MTS_CUST_LABEL_EA04
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '距首次登陆天数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_EA04'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_EA04';

  INSERT INTO MTS.MTS_CUST_LABEL_EA04
    (AA01, EA04, DATA_DATE)
    SELECT B.CUST_CORE_NO AA01, --客户ID(ECIF客户号)
           TO_NUMBER(TO_DATE(V_SYSDAT, 'yyyy-mm-dd') -
                     TO_DATE(C.FIRST_LGN_DATE, 'yyyy-mm-dd')) EA04,
           V_SYSDAT
      FROM MBS_CUST_INFO B
     INNER JOIN MBS_CUST_LOGIN_AUTH C
        ON B.CUST_NO = C.CUST_NO
     WHERE B.CUST_STATUS != '0'
       AND C.FIRST_LGN_FLAG = 'Y'
       AND B.CUST_CORE_NO IS NOT NULL;
  COMMIT;

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_LABEL_EA04', '1');

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工距首次登陆天数处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_EA05(V_SYSDAT IN VARCHAR2,
                                                  OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_EA05
  -- 报表编号：P_MTS_CUST_LABEL_EA05
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  ZJ
  -- date   ： 2020-06-19
  ------------------------------------------------------------------
  --***************************************

  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户基础标签处理_EA05'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_EA05'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  /*
       v_sql :='
           ';
       execute immediate v_sql;
       commit;
  */

  /*  标签说明
  AA01     --客户ID(ECIF客户号)
  EA05     --距最近一次登陆天数
    */

  --加工标签EA05数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_EA05';
  INSERT INTO MTS.MTS_CUST_LABEL_EA05
    (AA01, --客户ID(ECIF客户号)
     EA05, --距最近一次登陆天数
     DATA_DATE --数据日期
     )
    SELECT A.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           TO_NUMBER(TO_DATE(V_SYSDAT, 'yyyy-mm-dd') - E.DT) EA05, --距最近一次登陆天数
           V_SYSDAT DATA_DATE --数据日期
      FROM ECIF_T01_P_CUST_INFO A
      LEFT JOIN (SELECT D.CUST_CORE_NO,
                        MAX(TO_DATE(D.LGN_DATE, 'yyyy-mm-dd')) DT
                   FROM (SELECT B.CUST_CORE_NO, C.LGN_DATE
                           FROM MBS_CUST_INFO B
                           LEFT JOIN MBS_CUST_LOG_LOGIN C
                             ON B.CUST_NO = C.CUST_NO
                          WHERE C.LGN_STATUS = '1'
                            AND B.CUST_CORE_NO IS NOT NULL
                            AND B.CUST_STATUS != '0') D
                  GROUP BY D.CUST_CORE_NO) E
        ON A.ECIF_CUST_NO = E.CUST_CORE_NO;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签距最近一次登陆天数数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

