  INSERT INTO MTS_CUST_LABEL_FA02_TMP01
    SELECT A.OBJECTNO, PAYDATE, OBJECTTYPE
      FROM CMS_ACCT_PAYMENT_SCHEDULE A
     WHERE NVL(ACTUALPAYPRINCIPALPENALTYAMT, 0) +
           NVL(ACTUALPAYINTERESTPENALTYAMT, 0) > 0;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_FA02';
  INSERT INTO MTS.MTS_CUST_LABEL_FA02
    (AA01, --客户ID(ECIF客户号)
     FA02, --近24月内是否存在逾期
     DATA_DATE --数据日期
     )
    SELECT C.MFCUSTOMERID, '1', V_SYSDAT
      FROM MTS_CUST_LABEL_FA02_TMP01 A,
           CMS_ACCT_LOAN             B,
           CMS_CUSTOMER_INFO         C
     WHERE A.OBJECTNO = B.ACCOUNTNO
       AND B.CUSTOMERID = C.CUSTOMERID
       AND TO_CHAR(ADD_MONTHS(TO_DATE(V_SYSDAT, 'yyyy-MM-dd'), -24),
                   'yyyy/MM/dd') < PAYDATE
       AND OBJECTTYPE = 'jbo.acct.ACCT_LOAN'
       AND MFCUSTOMERID IS NOT NULL
     GROUP BY C.MFCUSTOMERID;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签近24月内是否存在逾期数据处理完成' ||
                 SUBSTR(SQLERRM, 1, 1000);
