  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理
  /*
       v_sql :='
           ';
       execute immediate v_sql;
       commit;
  */

  /*  标签说明
  AA01     --客户ID(ECIF客户号)
  FA04     --征信是否存在不良贷款记录
    */

  --加工标签FA04数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_FA04';
  INSERT INTO MTS.MTS_CUST_LABEL_FA04
    (AA01, --客户ID(ECIF客户号)
     FA04, --征信是否存在不良贷款记录
     DATA_DATE --数据日期
     )
    SELECT C.ECIF_CUST_NO AA01, --客户ID(ECIF客户号)
           CASE
             WHEN COUNT(A.PD01E_J01) > 0 THEN
              '1'
             ELSE
              '0'
           END FA04, --征信是否存在不良贷款记录
           V_SYSDAT DATA_DATE --数据日期
      FROM CPP_OR31_RPT_PA_01_B B,
           CPP_OR31_RPT_PD_01_E A,
           ECIF_T01_P_CUST_INFO C
     WHERE B.RPT_ID = A.RPT_ID
       AND B.PA01B_I01 = C.CERT_NO
       AND A.PD01E_J01 > '0'
     GROUP BY C.ECIF_CUST_NO;
  COMMIT;

    --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_FA04数据处理完成'||SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(    V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);

   --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;

END;
/

