CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_POPULATION(V_SYSDAT IN VARCHAR2,
                                                        OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 社会属性数据加工
  -- 报表编号：P_MTS_CUST_LABEL_POPULATION
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '社会属性数据加工'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_POPULATION'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  --调试日志打开
  V_LOG_BUTTON := 1;

  --身份证校验 通过身份证校验函数校验合规的身份证并打上标记
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_POPULATION';
  INSERT /*+append*/
  INTO MTS.MTS_CUST_LABEL_POPULATION
    (AA01, --客户id(ecif客户号)
     AB01, --客户名称
     AB02, --证件号码
     AB03, --证件类型
     AB04, --性别
     AB05, --年龄
     AB06, --生日到期天数
     AB07, --民族
     AC01, --婚姻状况
     AD01, --手机号
     AD02, --身份证地址
     AD03, -- 家庭地址
     AD04, --单位地址
     AE01, --最高学历
     AF01, --所属行业
     AF02, --职业
     AF03, --单位性质
     AF04, --是否个体工商户
     AF05, --是否小微企业主
     AF06, --是否企事业单位高管
     AF07, --是否企业法人代表
     AF08, --工作年限
     AF09, --本单位工作年限
     AF10, --工作单位名称
     AF11, --近半年月均收入
     AF12, --个人年收入
     AF13, --公积金缴存基数
     AF14, --社保缴存基数
     AF15, --我行连续代发工资月数
     AG01, --最早开户机构名称
     AG02, --管户机构编号
     AG03, --资产最大机构
     AG04, --手机银行营销机构
     AG05, --管户客户经理编号
     AG06, --纯新户开户标志
     AG07, --在我行开户年限
     AG08, --是否黑名单客户
     AG09, --是否白名单客户
     AG10, --是否本行员工
     AG11, --是否关联交易人
     ORGPATH, --机构层级
     AG12 --客户经理名称
     )
    SELECT T_01.AA01,
           T_02.AB01,
           T_03.AB02,
           T_04.AB03,
           T_05.AB04,
           T_06.AB05,
           T_07.AB06,
           T_08.AB07,
           T_09.AC01,
           T_10.AD01,
           T_11.AD02,
           T_12.AD03,
           T_13.AD04,
           T_14.AE01,
           T_15.AF01,
           T_16.AF02,
           T_17.AF03,
           T_18.AF04,
           T_19.AF05,
           T_20.AF06,
           T_21.AF07,
           T_22.AF08,
           T_23.AF09,
           T_24.AF10,
           T_25.AF11,
           T_26.AF12,
           T_27.AF13,
           T_28.AF14,
           T_29.AF15,
           T_30.AG01,
           NVL(T_31.AG02, T_30.AG01) AG02, --管户机构编号 如果管户机构编码为空取最早开户机构编码  
           T_32.AG03,
           T_33.AG04,
           T_34.AG05,
           T_35.AG06,
           T_36.AG07,
           T_37.AG08,
           T_38.AG09,
           T_39.AG10,
           T_40.AG11,
           L.PATH ORGPATH, --机构全路径                                                           
           T_41.AG12
    
      FROM MTS_CUST_LABEL_AA01 T_01
      LEFT JOIN MTS_CUST_LABEL_AB01 T_02
        ON T_01.AA01 = T_02.AA01
      LEFT JOIN MTS_CUST_LABEL_AB02 T_03
        ON T_01.AA01 = T_03.AA01
      LEFT JOIN MTS_CUST_LABEL_AB03 T_04
        ON T_01.AA01 = T_04.AA01
      LEFT JOIN MTS_CUST_LABEL_AB04 T_05
        ON T_01.AA01 = T_05.AA01
      LEFT JOIN MTS_CUST_LABEL_AB05 T_06
        ON T_01.AA01 = T_06.AA01
      LEFT JOIN MTS_CUST_LABEL_AB06 T_07
        ON T_01.AA01 = T_07.AA01
      LEFT JOIN MTS_CUST_LABEL_AB07 T_08
        ON T_01.AA01 = T_08.AA01
      LEFT JOIN MTS_CUST_LABEL_AC01 T_09
        ON T_01.AA01 = T_09.AA01
      LEFT JOIN MTS_CUST_LABEL_AD01 T_10
        ON T_01.AA01 = T_10.AA01
      LEFT JOIN MTS_CUST_LABEL_AD02 T_11
        ON T_01.AA01 = T_11.AA01
      LEFT JOIN MTS_CUST_LABEL_AD03 T_12
        ON T_01.AA01 = T_12.AA01
      LEFT JOIN MTS_CUST_LABEL_AD04 T_13
        ON T_01.AA01 = T_13.AA01
      LEFT JOIN MTS_CUST_LABEL_AE01 T_14
        ON T_01.AA01 = T_14.AA01
      LEFT JOIN MTS_CUST_LABEL_AF01 T_15
        ON T_01.AA01 = T_15.AA01
      LEFT JOIN MTS_CUST_LABEL_AF02 T_16
        ON T_01.AA01 = T_16.AA01
      LEFT JOIN MTS_CUST_LABEL_AF03 T_17
        ON T_01.AA01 = T_17.AA01
      LEFT JOIN MTS_CUST_LABEL_AF04 T_18
        ON T_01.AA01 = T_18.AA01
      LEFT JOIN MTS_CUST_LABEL_AF05 T_19
        ON T_01.AA01 = T_19.AA01
      LEFT JOIN MTS_CUST_LABEL_AF06 T_20
        ON T_01.AA01 = T_20.AA01
      LEFT JOIN MTS_CUST_LABEL_AF07 T_21
        ON T_01.AA01 = T_21.AA01
      LEFT JOIN MTS_CUST_LABEL_AF08 T_22
        ON T_01.AA01 = T_22.AA01
      LEFT JOIN MTS_CUST_LABEL_AF09 T_23
        ON T_01.AA01 = T_23.AA01
      LEFT JOIN MTS_CUST_LABEL_AF10 T_24
        ON T_01.AA01 = T_24.AA01
      LEFT JOIN MTS_CUST_LABEL_AF11 T_25
        ON T_01.AA01 = T_25.AA01
      LEFT JOIN MTS_CUST_LABEL_AF12 T_26
        ON T_01.AA01 = T_26.AA01
      LEFT JOIN MTS_CUST_LABEL_AF13 T_27
        ON T_01.AA01 = T_27.AA01
      LEFT JOIN MTS_CUST_LABEL_AF14 T_28
        ON T_01.AA01 = T_28.AA01
      LEFT JOIN MTS_CUST_LABEL_AF15 T_29
        ON T_01.AA01 = T_29.AA01
      LEFT JOIN MTS_CUST_LABEL_AG01 T_30
        ON T_01.AA01 = T_30.AA01
      LEFT JOIN MTS_CUST_LABEL_AG02 T_31
        ON T_01.AA01 = T_31.AA01
      LEFT JOIN MTS_CUST_LABEL_AG03 T_32
        ON T_01.AA01 = T_32.AA01
      LEFT JOIN MTS_CUST_LABEL_AG04 T_33
        ON T_01.AA01 = T_33.AA01
      LEFT JOIN MTS_CUST_LABEL_AG05 T_34
        ON T_01.AA01 = T_34.AA01
      LEFT JOIN MTS_CUST_LABEL_AG06 T_35
        ON T_01.AA01 = T_35.AA01
      LEFT JOIN MTS_CUST_LABEL_AG07 T_36
        ON T_01.AA01 = T_36.AA01
      LEFT JOIN MTS_CUST_LABEL_AG08 T_37
        ON T_01.AA01 = T_37.AA01
      LEFT JOIN MTS_CUST_LABEL_AG09 T_38
        ON T_01.AA01 = T_38.AA01
      LEFT JOIN MTS_CUST_LABEL_AG10 T_39
        ON T_01.AA01 = T_39.AA01
      LEFT JOIN MTS_CUST_LABEL_AG11 T_40
        ON T_01.AA01 = T_40.AA01
      LEFT JOIN MTS_CUST_LABEL_AG12 T_41
        ON T_01.AA01 = T_41.AA01
      LEFT JOIN MTS.MTS_ORGINFO L --如果管户机构编码为空取最早开户机构编码关联机构表，获取机构全路径
        ON NVL(T_31.AG02, T_30.AG01) = L.ID_
       AND L.ORGTYPE_ID = '01'; --ORGTYPE_ID 机构编码类型
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '社会属性数据加工数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

