                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_LABEL_TRANSACTION(V_SYSDAT IN VARCHAR2,
                                                         OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户行为特征
  -- 报表编号：P_MTS_CUST_LABEL_TRANSACTION
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '客户行为特征'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_LABEL_TRANSACTION'; --存储过程名

  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SRTDAT    DATE DEFAULT SYSDATE; --记录过程开始时间
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  --调试日志打开
  V_LOG_BUTTON := 1;

  --身份证校验 通过身份证校验函数校验合规的身份证并打上标记
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_LABEL_TRANSACTION';
  INSERT /*+append*/
  INTO MTS.MTS_CUST_LABEL_TRANSACTION
    (AA01, --客户id(ecif客户号)
     DA01, --近1月累计交易笔数
     DA02, --近1月累计交易金额
     DA03, --近1月手机银行累计交易笔数
     DA04, --近1月手机银行累计交易金额
     DA05, --签约当日手机银行交易笔数
     DA06, --本年度至今手机银行累计交易笔数
     DA07, --本年度至今网银转出笔数
     DA08, --本年度至今网银转出金额
     DA09, --本年度至今网银转入笔数
     DA10, --本年度至今网银转入金额
     DA11, --近1月第三方支付累计转出笔数
     DA12, --近1月第三方支付累计转出金额
     DA13, --近1月第三方支付累计转入笔数
     DA14, --近1月第三方支付累计转入金额
     DA15, --收单系统上三月收费笔数
     DA16, --收单系统上三月收费金额
     DA17, --最近一次交易时间
     DA18, --最近一次交易天数
     DA19, --最近一次交易金额
     DA20, --本年度至今第三方交易渠道交易笔数
     DA21, --本年度至今第三方交易渠道交易金额
     DA22, --本年度至今水、电、气费缴费笔数
     DA23, --本年度至今银联pos机消费笔数
     DA24, --本年度至今银联pos机消费金额
     DA25, --本年度至今社保缴费笔数
     DA26, --本年度至今海棠通缴费笔数
     DB01, --近1月累计转入金额
     DB02, --近1月累计转入笔数
     DB03, --近1月转入单笔最大金额
     DB04, --近1月累计转出金额
     DB05, --近1月累计转出笔数
     DB06, --近1月转出单笔最大金额
     DB07, --是否我行资金过路户
     DB08, --是否向他行同名户规律转出
     DC01, --渠道偏好
     DC02, --储蓄产品偏好
     DC03, --乐惠存期限偏好
     DC04, --储蓄期限偏好
     DC05 --理财产品期限偏好
     )
    SELECT T_01.AA01,
           T_02.DA01,
           T_03.DA02,
           T_04.DA03,
           T_05.DA04,
           T_06.DA05,
           T_07.DA06,
           T_08.DA07,
           T_09.DA08,
           T_10.DA09,
           T_11.DA10,
           T_12.DA11,
           T_13.DA12,
           T_14.DA13,
           T_15.DA14,
           T_16.DA15,
           T_17.DA16,
           T_18.DA17,
           T_19.DA18,
           T_20.DA19,
           T_21.DA20,
           T_22.DA21,
           T_23.DA22,
           T_24.DA23,
           T_25.DA24,
           T_26.DA25,
           T_27.DA26,
           T_28.DB01,
           T_29.DB02,
           T_30.DB03,
           T_31.DB04,
           T_32.DB05,
           T_33.DB06,
           T_34.DB07,
           T_35.DB08,
           T_36.DC01,
           T_37.DC02,
           T_38.DC03,
           T_39.DC04,
           T_40.DC05
      FROM MTS_CUST_LABEL_AA01 T_01
      LEFT JOIN MTS_CUST_LABEL_DA01 T_02
        ON T_01.AA01 = T_02.AA01
      LEFT JOIN MTS_CUST_LABEL_DA02 T_03
        ON T_01.AA01 = T_03.AA01
      LEFT JOIN MTS_CUST_LABEL_DA03 T_04
        ON T_01.AA01 = T_04.AA01
      LEFT JOIN MTS_CUST_LABEL_DA04 T_05
        ON T_01.AA01 = T_05.AA01
      LEFT JOIN MTS_CUST_LABEL_DA05 T_06
        ON T_01.AA01 = T_06.AA01
      LEFT JOIN MTS_CUST_LABEL_DA06 T_07
        ON T_01.AA01 = T_07.AA01
      LEFT JOIN MTS_CUST_LABEL_DA07 T_08
        ON T_01.AA01 = T_08.AA01
      LEFT JOIN MTS_CUST_LABEL_DA08 T_09
        ON T_01.AA01 = T_09.AA01
      LEFT JOIN MTS_CUST_LABEL_DA09 T_10
        ON T_01.AA01 = T_10.AA01
      LEFT JOIN MTS_CUST_LABEL_DA10 T_11
        ON T_01.AA01 = T_11.AA01
      LEFT JOIN MTS_CUST_LABEL_DA11 T_12
        ON T_01.AA01 = T_12.AA01
      LEFT JOIN MTS_CUST_LABEL_DA12 T_13
        ON T_01.AA01 = T_13.AA01
      LEFT JOIN MTS_CUST_LABEL_DA13 T_14
        ON T_01.AA01 = T_14.AA01
      LEFT JOIN MTS_CUST_LABEL_DA14 T_15
        ON T_01.AA01 = T_15.AA01
      LEFT JOIN MTS_CUST_LABEL_DA15 T_16
        ON T_01.AA01 = T_16.AA01
      LEFT JOIN MTS_CUST_LABEL_DA16 T_17
        ON T_01.AA01 = T_17.AA01
      LEFT JOIN MTS_CUST_LABEL_DA17 T_18
        ON T_01.AA01 = T_18.AA01
      LEFT JOIN MTS_CUST_LABEL_DA18 T_19
        ON T_01.AA01 = T_19.AA01
      LEFT JOIN MTS_CUST_LABEL_DA19 T_20
        ON T_01.AA01 = T_20.AA01
      LEFT JOIN MTS_CUST_LABEL_DA20 T_21
        ON T_01.AA01 = T_21.AA01
      LEFT JOIN MTS_CUST_LABEL_DA21 T_22
        ON T_01.AA01 = T_22.AA01
      LEFT JOIN MTS_CUST_LABEL_DA22 T_23
        ON T_01.AA01 = T_23.AA01
      LEFT JOIN MTS_CUST_LABEL_DA23 T_24
        ON T_01.AA01 = T_24.AA01
      LEFT JOIN MTS_CUST_LABEL_DA24 T_25
        ON T_01.AA01 = T_25.AA01
      LEFT JOIN MTS_CUST_LABEL_DA25 T_26
        ON T_01.AA01 = T_26.AA01
      LEFT JOIN MTS_CUST_LABEL_DA26 T_27
        ON T_01.AA01 = T_27.AA01
      LEFT JOIN MTS_CUST_LABEL_DB01 T_28
        ON T_01.AA01 = T_28.AA01
      LEFT JOIN MTS_CUST_LABEL_DB02 T_29
        ON T_01.AA01 = T_29.AA01
      LEFT JOIN MTS_CUST_LABEL_DB03 T_30
        ON T_01.AA01 = T_30.AA01
      LEFT JOIN MTS_CUST_LABEL_DB04 T_31
        ON T_01.AA01 = T_31.AA01
      LEFT JOIN MTS_CUST_LABEL_DB05 T_32
        ON T_01.AA01 = T_32.AA01
      LEFT JOIN MTS_CUST_LABEL_DB06 T_33
        ON T_01.AA01 = T_33.AA01
      LEFT JOIN MTS_CUST_LABEL_DB07 T_34
        ON T_01.AA01 = T_34.AA01
      LEFT JOIN MTS_CUST_LABEL_DB08 T_35
        ON T_01.AA01 = T_35.AA01
      LEFT JOIN MTS_CUST_LABEL_DC01 T_36
        ON T_01.AA01 = T_36.AA01
      LEFT JOIN MTS_CUST_LABEL_DC02 T_37
        ON T_01.AA01 = T_37.AA01
      LEFT JOIN MTS_CUST_LABEL_DC03 T_38
        ON T_01.AA01 = T_38.AA01
      LEFT JOIN MTS_CUST_LABEL_DC04 T_39
        ON T_01.AA01 = T_39.AA01
      LEFT JOIN MTS_CUST_LABEL_DC05 T_40
        ON T_01.AA01 = T_40.AA01;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '临时表TEMP01对身份证校验打标记数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_OWER_PROD(V_SYSDAT IN VARCHAR2,
                                                 OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户产品持有信息
  -- 报表编号：P_MTS_CUST_OWER_PROD
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  LKL
  -- date   ： 2020-07-03
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '客户基础标签处理_OWER_PROD'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_CUST_OWER_PROD'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  V_SQL       VARCHAR2(4000);
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_NIAN       VARCHAR2(4);
  V_MONTH      VARCHAR2(2);
  V_DAYS       NUMBER;
  V_CLOMN      VARCHAR2(10);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  V_NIAN       := SUBSTR(V_SYSDAT, 1, 4);
  V_MONTH      := SUBSTR(V_SYSDAT, 5, 2);
  V_DAYS       := SUBSTR(V_SYSDAT, 7, 2);
  IF (V_MONTH = '01') THEN
    V_CLOMN := 'JALJISHU';
  ELSIF (V_MONTH = '02') THEN
    V_CLOMN := 'FEBJISHU';
  ELSIF (V_MONTH = '03') THEN
    V_CLOMN := 'MARJISHU';
  ELSIF (V_MONTH = '04') THEN
    V_CLOMN := 'APRJISHU';
  ELSIF (V_MONTH = '05') THEN
    V_CLOMN := 'MAYJISHU';
  ELSIF (V_MONTH = '06') THEN
    V_CLOMN := 'JUNJISHU';
  ELSIF (V_MONTH = '07') THEN
    V_CLOMN := 'JULJISHU';
  ELSIF (V_MONTH = '08') THEN
    V_CLOMN := 'AUGJISHU';
  ELSIF (V_MONTH = '09') THEN
    V_CLOMN := 'SEPJISHU';
  ELSIF (V_MONTH = '10') THEN
    V_CLOMN := 'OCTJISHU';
  ELSIF (V_MONTH = '11') THEN
    V_CLOMN := 'NOVJISHU';
  ELSE
    V_CLOMN := 'DECJISHU';
  END IF;

  --加工标签CUST_OWER_PROD数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_OWER_PROD';
  IF (V_DAYS = '01') THEN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_OWER_PROD_TMP';
  END IF;
  --插入01活期(含智慧存)、02定期、03乐慧存、05大额存单的数据
  V_SQL := 'INSERT INTO MTS.MTS_CUST_OWER_PROD
  (ECIF_CUST_NO, --ECIF客户号
   ZHANGHAO, --账号
   ZHANGHAO_TYPE, --账号类型
   PROD_B_TYPE, --产品大类
   PROD_S_CODE, --产品编码
   BEGIN_DATE, --开始日期
   END_DATE, --结束日期
   JINE, --金额
   QINXIAN, --期限
   DAOQI_FLAG, --是否到期标志
   DATA_DATE, --数据日期
   BZ_01, --备注1
   BZ_02, --备注2
   ORG_ID --账户机构
   )
  SELECT KEHUHAOO ECIF_CUST_NO, --ECIF客户号
         A.ZHANGHAO, --账号
         A.CUNKZLEI ZHANGHAO_TYPE, --账号类型 存款账户
         (CASE
           WHEN CUNKZLEI = ''00'' THEN
            ''01''
           WHEN CUNKZLEI IN (''01'',
                             ''02'',
                             ''03'',
                             ''04'',
                             ''05'',
                             ''06'',
                             ''07'',
                             ''12'',
                             ''13'',
                             ''15'',
                             ''19'',
                             ''24'',
                             ''25'') THEN
            ''02''
           WHEN CUNKZLEI = ''26'' THEN
            ''05''
           WHEN CUNKZLEI = ''29'' THEN
            ''03''
         END) PROD_B_TYPE, --产品大类
         CHAPBHAO PROD_S_CODE, --产品编码
         (CASE
           WHEN CUNKZLEI = ''00'' THEN
            KAIHRIQI
           ELSE
            CSQIXIRQ
         END) BEGIN_DATE, --开始日期
         NVL(CASE WHEN CUNKZLEI IN (''26'', ''29'') THEN D.EXPIRE_DATE ELSE  DOQIRIQI END , ''99991231'')  END_DATE, --结束日期
         A.ZHHUYUEE * HL.HL JINE, --金额 (汇率未做转换)
         CASE  WHEN CUNKZLEI = ''00'' THEN  NULL  WHEN CUNKZLEI IN (''26'', ''29'') THEN E.INC_DUE ELSE CUNQIIII  END QINXIAN, --期限(年、月)
         (CASE  WHEN (CASE WHEN CUNKZLEI IN (''26'', ''29'') THEN D.EXPIRE_DATE ELSE  DOQIRIQI END ) < ' ||
           V_SYSDAT || ' OR  A.ZHHUYUEE = 0 THEN  ''0''  ELSE ''1''  END) DAOQI_FLAG, --是否到期标志
         ' || V_SYSDAT || ' DATA_DATE, --数据日期
         NULL BZ_01, --备注1
         nvl(' || V_CLOMN ||
           ',0) * HL.HL BZ_02, --备注2
         A.ZHUJIGOH
    FROM CBS_KDPA_ZHXINX A
    LEFT JOIN CBS_KDPA_ZHDUIZ C
      ON A.ZHANGHAO = C.ZHANGHAO
     AND A.KEHUZHAO = C.KEHUZHAO
    LEFT JOIN CBS_KDPB_YUPJYE B
      ON C.KEHUZHAO || C.ZHHAOXUH = B.KEHUZHAO||B.ZHHAOXUH  AND B.NIANNNNN = ' ||
           V_NIAN || '
    LEFT JOIN V_CDS_TB_CASH_ACCT_INFO D
      ON C.KEHUZHAO || C.ZHHAOXUH = D.TERM_ACCT_NO || D.TERM_SERIAL_NO AND  D.STATUS = ''0'' --状态为正常
    LEFT JOIN CDS_TB_PROD_PUB_INFO E
      ON D.PROD_CODE = E.PROD_CODE
    LEFT JOIN MTS_SYS_XTHLCS HL
      ON A.HUOBDAIH = HL.HUOBDAIH
   WHERE A.CUNKZLEI IN (''00'',
                        ''01'',
                        ''02'',
                        ''03'',
                        ''04'',
                        ''05'',
                        ''06'',
                        ''07'',
                        ''12'',
                        ''13'',
                        ''15'',
                        ''19'',
                        ''24'',
                        ''25'',
                        ''26'',
                        ''29'') --定存包含乐慧存、大额订单等';

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := V_SQL;
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  EXECUTE IMMEDIATE V_SQL;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签 1 数据处理完成' || V_SQL || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  ------------------------------------智慧存产品更新--------------------------------------

  MERGE INTO MTS_CUST_OWER_PROD_TMP A
  USING (SELECT CBS.KEHUHAOO ECIF_CUST_NO, --ECIF客户号
                CBS.ZHANGHAO, --账号
                0 ZHANGHAO_TYPE, --账号类型 存款账户
                '04' PROD_B_TYPE, --产品大类
                CBS.CHAPBHAO PROD_S_CODE, --产品编码
                CBS.CSQIXIRQ BEGIN_DATE, --开始日期
                '99991231' END_DATE, --结束日期
                CBS.ZHHUYUEE JINE, --金额 (汇率未做转换)
                CUNQIIII QINXIAN, --期限
                CASE
                  WHEN CBS.ZHHUYUEE <> 0 THEN
                   '1'
                  ELSE
                   '0'
                END DAOQI_FLAG, --是否到期标志
                V_SYSDAT DATA_DATE, --数据日期
                NULL BZ_01, --备注1
                NVL(CBS.ZHHUYUEE, 0) * HL.HL + NVL(GOUGOU.BZ_02, 0) BZ_02, --备注2
                CBS.ZHUJIGOH ORG_ID --账户机构
           FROM ECIF_T02_A_CUST_SIGN_REL ECIF
           LEFT JOIN CBS_KDPA_ZHXINX CBS
             ON ECIF.SIGN_ACC_NO = CBS.KEHUZHAO
           LEFT JOIN MTS_CUST_OWER_PROD_TMP GOUGOU
             ON CBS.KEHUHAOO = GOUGOU.ECIF_CUST_NO
            AND CBS.ZHANGHAO = GOUGOU.ZHANGHAO
            AND CBS.CHAPBHAO = GOUGOU.PROD_S_CODE
            AND GOUGOU.PROD_B_TYPE = '04'
           LEFT JOIN MTS_SYS_XTHLCS HL
             ON CBS.HUOBDAIH = HL.HUOBDAIH
          WHERE ECIF.SIGN_TYPE = '217' --签约类型为智惠存
            AND CBS.ZHHUZTAI = 'A' --账户状态为正常
            AND CBS.FZCPLEIX = '0' --负债产品类型为活期产品
            AND ECIF.SIGN_STATE = '1' --签约状态为签约
         ) B
  ON (A.ECIF_CUST_NO || A.ZHANGHAO || A.PROD_S_CODE || A.PROD_B_TYPE || A.ZHANGHAO_TYPE = B.ECIF_CUST_NO || B.ZHANGHAO || B.PROD_S_CODE || B.PROD_B_TYPE || B.ZHANGHAO_TYPE)
  WHEN MATCHED THEN
    UPDATE
       SET A.BZ_02      = B.BZ_02,
           A.END_DATE   = B.END_DATE,
           A.JINE       = B.JINE,
           A.DAOQI_FLAG = B.DAOQI_FLAG
  WHEN NOT MATCHED THEN
    INSERT
      (A.ECIF_CUST_NO,
       A.ZHANGHAO,
       A.ZHANGHAO_TYPE,
       A.PROD_B_TYPE,
       A.PROD_S_CODE,
       A.BEGIN_DATE,
       A.END_DATE,
       A.JINE,
       A.QINXIAN,
       A.DAOQI_FLAG,
       A.DATA_DATE,
       A.BZ_01,
       A.BZ_02,
       A.ORG_ID)
    VALUES
      (B.ECIF_CUST_NO,
       B.ZHANGHAO,
       B.ZHANGHAO_TYPE,
       B.PROD_B_TYPE,
       B.PROD_S_CODE,
       B.BEGIN_DATE,
       B.END_DATE,
       B.JINE,
       B.QINXIAN,
       B.DAOQI_FLAG,
       B.DATA_DATE,
       B.BZ_01,
       B.BZ_02,
       B.ORG_ID);
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签 2 数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  ------------------------------------理财存产品更新--------------------------------------
  MERGE INTO MTS_CUST_OWER_PROD_TMP A
  USING (SELECT F3.HOST_CUST_NO ECIF_CUST_NO, --ECIF客户号
                F1.FNC_TRANS_ACCT_NO ZHANGHAO, --账号
                1 ZHANGHAO_TYPE, --账号类型 理财账户
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   '07'
                  ELSE
                   '06'
                END) PROD_B_TYPE, --产品大类
                F1.PROD_CODE PROD_S_CODE, --产品编码
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   F2.OPEN_BEGIN_DATE
                  ELSE
                   F2.VALUE_DATE
                END) BEGIN_DATE, --开始日期
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   F2.OPEN_END_DATE
                  ELSE
                   F2.WINDING_DATE
                END) END_DATE, --结束日期
                F1.TOTAL_VOL JINE, --金额
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   TO_NUMBER(TO_DATE(F2.OPEN_END_DATE, 'YYYY-MM-DD') -
                             TO_DATE(F2.OPEN_BEGIN_DATE, 'YYYY-MM-DD'))
                  ELSE
                   TO_NUMBER(TO_DATE(F2.WINDING_DATE, 'YYYY-MM-DD') -
                             TO_DATE(F2.VALUE_DATE, 'YYYY-MM-DD'))
                END) QINXIAN, --期限(天数)
                CASE
                  WHEN F1.TOTAL_VOL = 0 THEN
                   '0'
                  ELSE
                   '1'
                END DAOQI_FLAG, --是否到期标志  1 未到期
                V_SYSDAT DATA_DATE, --数据日期
                '' BZ_01, --备注1
                NVL(F1.TOTAL_VOL, 0) + NVL(GOUGOU.BZ_02, 0) BZ_02, --备注2
                F3.SUB_BRANCH_CODE ORG_ID
           FROM FMS_T5_CUST_VOL F1
           LEFT JOIN FMS_T5_PROD_INFO F2
             ON F1.PROD_CODE = F2.PROD_CODE
           LEFT JOIN FMS_T1_CUST_INFO F3
             ON F1.CUST_NO = F3.CUST_NO
           LEFT JOIN MTS_CUST_OWER_PROD_TMP GOUGOU
             ON F3.HOST_CUST_NO = GOUGOU.ECIF_CUST_NO
            AND F1.FNC_TRANS_ACCT_NO = GOUGOU.ZHANGHAO
            AND F2.PROD_CODE = GOUGOU.PROD_S_CODE
            AND DECODE(F2.PERIOD_TYPE, '0', '07', '06') = GOUGOU.PROD_B_TYPE
          WHERE NVL(F3.HOST_CUST_NO, 'ISNULL') != 'ISNULL'
         UNION ALL
         ---------------------------------到期理财数据--------------------------------------
         
         SELECT F3.HOST_CUST_NO ECIF_CUST_NO, --ECIF客户号
                F1.FNC_TRANS_ACCT_NO ZHANGHAO, --账号
                1 ZHANGHAO_TYPE, --账号类型 理财账户
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   '07'
                  ELSE
                   '06'
                END) PROD_B_TYPE, --产品大类
                F1.PROD_CODE PROD_S_CODE, --产品编码
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   F2.OPEN_BEGIN_DATE
                  ELSE
                   F2.VALUE_DATE
                END) BEGIN_DATE, --开始日期
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   F2.OPEN_END_DATE
                  ELSE
                   F2.WINDING_DATE
                END) END_DATE, --结束日期
                0 JINE, --金额
                (CASE
                  WHEN F2.PERIOD_TYPE = '0' THEN
                   TO_NUMBER(TO_DATE(F2.OPEN_END_DATE, 'YYYY-MM-DD') -
                             TO_DATE(F2.OPEN_BEGIN_DATE, 'YYYY-MM-DD'))
                  ELSE
                   TO_NUMBER(TO_DATE(F2.WINDING_DATE, 'YYYY-MM-DD') -
                             TO_DATE(F2.VALUE_DATE, 'YYYY-MM-DD'))
                END) QINXIAN, --期限(天数)
                '0' DAOQI_FLAG, --是否到期标志  0 到期
                V_SYSDAT DATA_DATE, --数据日期
                '' BZ_01, --备注1
                0 + NVL(GOUGOU.BZ_02, 0) BZ_02, --备注2    
                F3.SUB_BRANCH_CODE ORG_ID
           FROM FMS_T5_CUST_TRANS_LOG_H F1
           LEFT JOIN FMS_T5_PROD_INFO F2
             ON F1.PROD_CODE = F2.PROD_CODE
           LEFT JOIN FMS_T1_CUST_INFO F3
             ON F1.CUST_NO = F3.CUST_NO
           LEFT JOIN MTS_CUST_OWER_PROD_TMP GOUGOU
             ON F3.HOST_CUST_NO = GOUGOU.ECIF_CUST_NO
            AND F1.FNC_TRANS_ACCT_NO = GOUGOU.ZHANGHAO
            AND F2.PROD_CODE = GOUGOU.PROD_S_CODE
            AND DECODE(F2.PERIOD_TYPE, '0', '07', '06') = GOUGOU.PROD_B_TYPE
          WHERE F1.BUSI_CODE = '150'
            AND NVL(F3.HOST_CUST_NO, 'ISNULL') != 'ISNULL'
         
         ) B
  ON (A.ECIF_CUST_NO || A.ZHANGHAO || A.PROD_S_CODE || A.PROD_B_TYPE || A.ZHANGHAO_TYPE = B.ECIF_CUST_NO || B.ZHANGHAO || B.PROD_S_CODE || B.PROD_B_TYPE || B.ZHANGHAO_TYPE)
  WHEN MATCHED THEN
    UPDATE
       SET A.BZ_02      = B.BZ_02,
           A.END_DATE   = B.END_DATE,
           A.JINE       = B.JINE,
           A.DAOQI_FLAG = B.DAOQI_FLAG
  WHEN NOT MATCHED THEN
    INSERT
      (A.ECIF_CUST_NO,
       A.ZHANGHAO,
       A.ZHANGHAO_TYPE,
       A.PROD_B_TYPE,
       A.PROD_S_CODE,
       A.BEGIN_DATE,
       A.END_DATE,
       A.JINE,
       A.QINXIAN,
       A.DAOQI_FLAG,
       A.DATA_DATE,
       A.BZ_01,
       A.BZ_02,
       A.ORG_ID)
    
    VALUES
      (B.ECIF_CUST_NO,
       B.ZHANGHAO,
       B.ZHANGHAO_TYPE,
       B.PROD_B_TYPE,
       B.PROD_S_CODE,
       B.BEGIN_DATE,
       B.END_DATE,
       B.JINE,
       B.QINXIAN,
       B.DAOQI_FLAG,
       B.DATA_DATE,
       B.BZ_01,
       B.BZ_02,
       B.ORG_ID);
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签 3 数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  ------------------------------------贷款数据跟新--------------------------------------
  MERGE INTO MTS_CUST_OWER_PROD_TMP A
  USING (SELECT C.MFCUSTOMERID ECIF_CUST_NO, --ECIF客户号
                A.SERIALNO ZHANGHAO,
                2 ZHANGHAO_TYPE, --账号类型 贷款账户
                '11' PROD_B_TYPE, --产品大类
                A.BUSINESSTYPE PROD_S_CODE, --产品编码
                REPLACE(A.PUTOUTDATE, '/', '') BEGIN_DATE, --发放日期
                REPLACE(NVL(A.ORIGINALMATURITYDATE, A.MATURITYDATE), '/', '') END_DATE, --到期日期
                (NVL(A.NORMALBALANCE, 0) + NVL(A.OVERDUEBALANCE, 0)) * HL.HL JINE, --金额(未转换汇率)
                TO_NUMBER(TO_DATE(NVL(A.ORIGINALMATURITYDATE, A.MATURITYDATE),
                                  'YYYY-MM-DD') -
                          TO_DATE(A.PUTOUTDATE, 'YYYY-MM-DD')) QINXIAN, --期限(天数)
                (CASE
                  WHEN A.FINISHDATE IS NULL THEN
                   1
                  ELSE
                   0
                END) DAOQI_FLAG, --是否到期标志
                V_SYSDAT DATA_DATE, --数据日期  
                REPLACE(A.MATURITYDATE, '/', '') BZ_01, --备注1
                (NVL(A.NORMALBALANCE, 0) + NVL(A.OVERDUEBALANCE, 0)) * HL.HL +
                NVL(GOUGOU.BZ_02, 0) BZ_02, --备注2
                D.MAINFRAMEORGID ORG_ID
           FROM CMS_ACCT_LOAN A
           LEFT JOIN CMS_BUSINESS_CONTRACT B
             ON A.CONTRACTSERIALNO = B.SERIALNO
           LEFT JOIN CMS_CUSTOMER_INFO C
             ON A.CUSTOMERID = C.CUSTOMERID
           LEFT JOIN MTS_CUST_OWER_PROD_TMP GOUGOU
             ON C.MFCUSTOMERID = GOUGOU.ECIF_CUST_NO
            AND A.SERIALNO = GOUGOU.ZHANGHAO
            AND NVL(A.BUSINESSTYPE, 0) = NVL(GOUGOU.PROD_S_CODE, 0) --空空不相等
            AND GOUGOU.PROD_B_TYPE = '11'
           LEFT JOIN MTS_SYS_XTHLCS HL
             ON A.CURRENCY = HL.HUOBDAIH
           LEFT JOIN CMS_ORG_INFO D
             ON A.ACCOUNTINGORGID = D.ORGID
          WHERE NVL(C.MFCUSTOMERID, 'ISNULL') <> 'ISNULL') B
  ON (A.ECIF_CUST_NO || A.ZHANGHAO || A.PROD_S_CODE || A.PROD_B_TYPE || A.ZHANGHAO_TYPE = B.ECIF_CUST_NO || B.ZHANGHAO || B.PROD_S_CODE || B.PROD_B_TYPE || B.ZHANGHAO_TYPE)
  WHEN MATCHED THEN
    UPDATE
       SET A.BZ_02      = B.BZ_02,
           A.END_DATE   = B.END_DATE,
           A.JINE       = B.JINE,
           A.DAOQI_FLAG = B.DAOQI_FLAG
  WHEN NOT MATCHED THEN
    INSERT
      (A.ECIF_CUST_NO,
       A.ZHANGHAO,
       A.ZHANGHAO_TYPE,
       A.PROD_B_TYPE,
       A.PROD_S_CODE,
       A.BEGIN_DATE,
       A.END_DATE,
       A.JINE,
       A.QINXIAN,
       A.DAOQI_FLAG,
       A.DATA_DATE,
       A.BZ_01,
       A.BZ_02,
       A.ORG_ID)
    
    VALUES
      (B.ECIF_CUST_NO,
       B.ZHANGHAO,
       B.ZHANGHAO_TYPE,
       B.PROD_B_TYPE,
       B.PROD_S_CODE,
       B.BEGIN_DATE,
       B.END_DATE,
       B.JINE,
       B.QINXIAN,
       B.DAOQI_FLAG,
       B.DATA_DATE,
       B.BZ_01,
       B.BZ_02,
       B.ORG_ID);
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签 4 数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  INSERT INTO MTS.MTS_CUST_OWER_PROD
    (ECIF_CUST_NO, --ECIF客户号
     ZHANGHAO, --账号
     ZHANGHAO_TYPE, --账号类型
     PROD_B_TYPE, --产品大类
     PROD_S_CODE, --产品编码
     BEGIN_DATE, --开始日期
     END_DATE, --结束日期
     JINE, --金额
     QINXIAN, --期限
     DAOQI_FLAG, --是否到期标志
     DATA_DATE, --数据日期
     BZ_01, --备注1
     BZ_02, --备注2
     ORG_ID)
    SELECT ECIF_CUST_NO, --ECIF客户号
           ZHANGHAO, --账号
           ZHANGHAO_TYPE, --账号类型
           PROD_B_TYPE, --产品大类
           PROD_S_CODE, --产品编码
           BEGIN_DATE, --开始日期
           END_DATE, --结束日期
           JINE, --金额
           QINXIAN, --期限
           DAOQI_FLAG, --是否到期标志
           DATA_DATE, --数据日期
           BZ_01, --备注1
           BZ_02, --备注2
           ORG_ID
      FROM MTS.MTS_CUST_OWER_PROD_TMP;
  COMMIT;
  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签CUST_OWER_PROD数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_CUST_ZH_JYMX_LAST(V_SYSDAT IN VARCHAR2,
                                                    OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 最后一日交易明细
  -- 报表编号：MTS_ZH_JYMX_LAST
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '最后一次交易明细'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_CUST_ZH_JYMX_LAST'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
  V_DATA_COUNT NUMBER(30);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_ZH_JYMX_LAST_TMP'; --存放上次数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_ZH_JYMX_LAST_TMP1'; --存放本次跑批数据

  INSERT INTO MTS_CUST_ZH_JYMX_LAST_TMP
    (ECIF_CUST_NO,
     ZHANGHAO, --负债账号
     JIEDAIBZ, --借贷标志
     JIAOYBIZ, --币种
     JIAOYIRQ, --交易日期
     JIAOYIJE --交易金额
     )
    SELECT ECIF_CUST_NO,
           ZHANGHAO, --负债账号
           JIEDAIBZ, --借贷标志
           JIAOYBIZ, --币种
           JIAOYIRQ, --交易日期
           JIAOYIJE --交易金额
      FROM MTS_CUST_ZH_JYMX_LAST;
  COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '上次获取到的最后一次交易数据存放临时表' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_ZH_JYMX_LAST_TMP', '1');

  --统计最后一次交易数据存储表中是否有数据，用来判断是否首次跑批
  SELECT COUNT(1) INTO V_DATA_COUNT FROM MTS_CUST_ZH_JYMX_LAST;

  IF V_DATA_COUNT = 0 THEN
    --如果首次跑批获取所数据
  
    INSERT INTO MTS_CUST_ZH_JYMX_LAST_TMP1
      (ECIF_CUST_NO,
       ZHANGHAO,
       JIEDAIBZ,
       JIAOYBIZ,
       JIAOYIRQ,
       JIAOYIJE
       
       )
      SELECT ECIF_CUST_NO,
             ZHANGHAO, --负债账号
             JIEDAIBZ, --借贷标志
             JIAOYBIZ, --币种
             JIAOYIRQ, --交易日期
             JIAOYIJE --交易金额
        FROM (SELECT MX.ZHANGHAO, --负债账号
                     MX.JIEDAIBZ, --借贷标志
                     MX.JIAOYBIZ, --币种
                     MX.JIAOYIRQ, --交易日期
                     MX.JIAOYIJE, --交易金额
                     CI.ECIF_CUST_NO, --客户号
                     ROW_NUMBER() OVER(PARTITION BY CI.ECIF_CUST_NO ORDER BY MX.JIAOYIRQ, MX.JIAOYISJ DESC) ROW_NUMBER
                FROM CBS_KDPA_ZHXINX XX
               INNER JOIN CBS_KDPL_ZHMINX MX
                  ON MX.ZHANGHAO = XX.ZHANGHAO
                 AND MX.NBJOYIMA <> 'dps101'
                LEFT JOIN ECIF_T01_P_CUST_INFO CI
                  ON CI.ECIF_CUST_NO = XX.KEHUHAOO
               WHERE CI.OWN_ORG < '120000')
       WHERE ROW_NUMBER = 1;
    COMMIT;
  ELSE
    --如果非首次跑批获本批次交易明细数据
    INSERT INTO MTS_CUST_ZH_JYMX_LAST_TMP1
      (ECIF_CUST_NO,
       ZHANGHAO,
       JIEDAIBZ,
       JIAOYBIZ,
       JIAOYIRQ,
       JIAOYIJE
       
       )
      SELECT ECIF_CUST_NO,
             ZHANGHAO, --负债账号
             JIEDAIBZ, --借贷标志
             JIAOYBIZ, --币种
             JIAOYIRQ, --交易日期
             JIAOYIJE --交易金额
        FROM (SELECT MX.ZHANGHAO, --负债账号
                     MX.JIEDAIBZ, --借贷标志
                     MX.JIAOYBIZ, --币种
                     MX.JIAOYIRQ, --交易日期
                     MX.JIAOYIJE, --交易金额
                     CI.ECIF_CUST_NO, --客户号
                     ROW_NUMBER() OVER(PARTITION BY CI.ECIF_CUST_NO ORDER BY MX.JIAOYIRQ, MX.JIAOYISJ DESC) ROW_NUMBER
                FROM CBS_KDPA_ZHXINX XX
               INNER JOIN CBS_KDPL_ZHMINX MX --测试条件
                  ON MX.ZHANGHAO = XX.ZHANGHAO
                 AND MX.NBJOYIMA <> 'dps101'
                 AND JIAOYIRQ = V_SYSDAT --取当天最后一期交易记录
                LEFT JOIN ECIF_T01_P_CUST_INFO CI
                  ON CI.ECIF_CUST_NO = XX.KEHUHAOO
               WHERE CI.OWN_ORG < '120000')
       WHERE ROW_NUMBER = 1;
  
    COMMIT;
  END IF;

  OUTCDE      := 0;
  V_ERRORTEXT := '加工本次跑批最后一日交易明细数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_ZH_JYMX_LAST_TMP1', '1');

  --  清空MTS.MTS_ZH_JYMX_LAST数据
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_CUST_ZH_JYMX_LAST'; --存放上次数据

  --合并两个跑批数据
  INSERT INTO MTS_CUST_ZH_JYMX_LAST
    (ECIF_CUST_NO,
     ZHANGHAO, --负债账号
     JIEDAIBZ, --借贷标志
     JIAOYBIZ, --币种
     JIAOYIRQ, --交易日期
     JIAOYIJE --交易金额
     )
    SELECT ECIF_CUST_NO, ZHANGHAO, JIEDAIBZ, JIAOYBIZ, JIAOYIRQ, JIAOYIJE　
      FROM MTS_CUST_ZH_JYMX_LAST_TMP T
     WHERE NOT EXISTS
     (SELECT ECIF_CUST_NO,
                   ZHANGHAO,
                   JIEDAIBZ,
                   JIAOYBIZ,
                   JIAOYIRQ,
                   JIAOYIJE　FROM MTS_CUST_ZH_JYMX_LAST_TMP1 T1 WHERE T.ECIF_CUST_NO = T1.ECIF_CUST_NO)
    UNION ALL
    SELECT ECIF_CUST_NO,
           ZHANGHAO,
           JIEDAIBZ,
           JIAOYBIZ,
           JIAOYIRQ,
           JIAOYIJE　FROM 　 MTS_CUST_ZH_JYMX_LAST_TMP1
           
           COMMIT;

  OUTCDE      := 0;
  V_ERRORTEXT := '合并两个跑批最后一日交易明细数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_CUST_ZH_JYMX_LAST', '1');

  --日志打印

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_ORGINFO(V_SYSDAT IN VARCHAR2,
                                          OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 机构数据生成
  -- 报表编号：MTS_ORGINFO
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  cyc
  -- date   ： 2020-07-13
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '机构数据生成'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_ORGINFO'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  --根据上游提供机构信息，对MTS_ORGINFO表中数据进行更新和修改
  DELETE FROM MTS_ORGINFO;
  COMMIT;
  INSERT INTO MTS_ORGINFO
    SELECT * FROM ORGINFO;
  COMMIT;
  /*MERGE INTO MTS.ORGINFO A
  USING (
    WITH LSCCB_ORG AS
     (SELECT A.SHNGJIJG, A.YEWUGXJG, A.JIGOUHAO, A.YEWUGXJB, B.JIGOUZWM
        FROM MTS.CBS_KBRB_JGXJII A, MTS.CBS_KBRP_JGCSHU B
       WHERE A.JIGOUHAO = B.JIGOUHAO
         AND A.YEWUGXZL = 'BAOBSJ' --机构类型
         AND A.SHNGJIJG = '000000'
       ORDER BY A.SHNGJIJG, A.YEWUGXJG, A.JIGOUHAO) --上游系统提供机构数据可以根据需求进行调整
    
    SELECT T.JIGOUHAO ID_, --机构编码
           T.JIGOUZWM ORG_NAME, --机构名称
           '01' ORGTYPE_ID, --机构类型
           DECODE(JIGOUHAO, '000000', '', T.YEWUGXJG) ORGINFO_ID, --父级机构, 如果顶级机构编码为‘000000’，则父级编码给空。影响前端机构树展示
           'tenant_system' TENANT_ID,
           SYS_CONNECT_BY_PATH(T.JIGOUHAO, '/') PATH, --机构全路径,和前端开发组约定路径编码机构编码之间使用‘/’分隔符
           --T.YEWUGXJB,
           SYSDATE CREATE_TIME, --创建时间
           'P_MTS_SYS_ORG' CREATE_USER, --创建人
           '1' STATUS_ --机构状态  1 有效
      FROM LSCCB_ORG T
     START WITH T.JIGOUHAO = '000000'
    CONNECT BY NOCYCLE PRIOR T.JIGOUHAO = T.YEWUGXJG
     ORDER BY T.YEWUGXJG) B --递归虚幻获取机构全路径，及相关内容赋值
        ON (A.ID_ = B.ID_ AND A.ORGTYPE_ID = B.ORGTYPE_ID) WHEN MATCHED THEN --满足条件对机构名称、机构类型、机构级别、机构全路径进行修改
      UPDATE
         SET A.ORG_NAME   = B.ORG_NAME, --机构名称
             A.ORGINFO_ID = B.ORGINFO_ID, --父级机构
             A.TENANT_ID  = B.TENANT_ID, --
             A.PATH       = B.PATH --机构全路径
      
    
    WHEN NOT MATCHED THEN --不满足条件新插入数据
      INSERT
        (A.ID_,
         A.ORG_NAME, --机构名称
         A.ORGTYPE_ID, --机构类型
         A.ORGINFO_ID, --父级机构
         A.TENANT_ID, --
         A.PATH, --机构全路径
         A.CREATE_TIME, --创建时间
         A.CREATE_USER, --创建人
         A.STATUS_)
      VALUES
        (B.ID_,
         B.ORG_NAME,
         B.ORGTYPE_ID, --机构类型
         B.ORGINFO_ID, --父级机构
         B.TENANT_ID, --
         B.PATH, --机构全路径
         B.CREATE_TIME, --创建时间
         B.CREATE_USER, --创建人
         B.STATUS_);
  
  COMMIT;
  DELETE FROM ORGINFO B
   WHERE (B.ORG_NAME LIKE '%清算中心%' OR B.ORG_NAME LIKE '%金融市场部%' OR
         B.ORG_NAME LIKE '%计划财务部%' OR B.ORG_NAME LIKE '%运营管理部%' OR
         B.ORG_NAME LIKE '%大合作银行部%' OR B.ORG_NAME LIKE '%小金融部%' OR
         B.ORG_NAME LIKE '%风险管理部%' OR B.ORG_NAME LIKE '%审计部%' OR
         B.ORG_NAME LIKE '%资源部%' OR B.ORG_NAME LIKE '%安保后勤部%' OR
         B.ORG_NAME LIKE '%行领导%' OR B.ORG_NAME LIKE '%董事办%' OR
         B.ORG_NAME LIKE '%监事办%' OR B.ORG_NAME LIKE '%合规部%' OR
         B.ORG_NAME LIKE '%办公室%' OR B.ORG_NAME LIKE '%工会%' OR
         B.ORG_NAME LIKE '%资产保全部%' OR B.ORG_NAME LIKE '%党群工作部%' OR
         B.ORG_NAME LIKE '%董事会战略委员会%' OR B.ORG_NAME LIKE '%机构发展部%' OR
         B.ORG_NAME LIKE '%地产金融部%');
  COMMIT;
  DELETE FROM MTS_ORGINFO;
  COMMIT;
  INSERT INTO MTS_ORGINFO
    SELECT * FROM ORGINFO;
  COMMIT;
  INSERT INTO MTS_CODE_STRING
    SELECT 'AG02', '机构信息', B.JIGOUHAO, B.JIGOUZWM, ROWNUM
      FROM CBS_KBRP_JGCSHU B
      LEFT JOIN MTS_CODE_STRING C
        ON B.JIGOUHAO = C.CODE_VALUE
       AND C.CODE_TYPE = 'AG02'
     WHERE B.JIGOLEIX = '2'
       AND C.CODE_TYPE IS NULL;
  COMMIT;*/

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '机构数据增新增、修改完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --统计信息收集
  MTS.SYS_EXC_ANALYZE(V_SYSDAT, 'MTS', 'MTS_ORGINFO', '1');

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_PROD_INFO(V_SYSDAT IN VARCHAR2,
                                            OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 产品中心产品信息处理
  -- 报表编号：P_MTS_PROD_INFO
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-01
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '产品中心产品信息处理'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_PROD_INFO'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;

  --核心产品
  INSERT INTO MTS.MTS_CBS_PROD_INFO
    SELECT A.CHAPBHAO,
           A.CHANPSHM,
           A.SHENXRIQ,
           A.SHIXRIQI,
           A.DINHUOBZ,
           A.SUOSHUDX,
           A.CHAPBIZH,
           A.CUNKZLEI,
           A.JILUZTAI
      FROM CBS_KDPF_CHPSHX A
      LEFT JOIN MTS_CBS_PROD_INFO B
        ON A.CHAPBHAO = B.PRODUCT_ID
     WHERE A.JILUZTAI = '0'
       AND B.PRODUCT_ID IS NULL;
  COMMIT;
  INSERT INTO MTS.MTS_CBS_PROD_INFO
    SELECT A.PROD_CODE,
           A.PROD_NAME,
           A.SALE_BEGIN_DATE,
           A.SALE_END_DATE,
           A.PROD_CLASS,
           '1',
           '01',
           CASE
             WHEN PROD_SUBCLASS = '3' THEN
              '29'
             WHEN PROD_SUBCLASS = '4' THEN
              '26'
           END,
           '0'
      FROM CDS_TB_PROD_PUB_INFO A
      LEFT JOIN MTS_CBS_PROD_INFO B
        ON A.PROD_CODE = B.PRODUCT_ID
     WHERE A.PROD_STATUS != '2'
       AND B.PRODUCT_ID IS NULL;
  COMMIT;
  ------------信贷产品
  INSERT INTO MTS_CMS_PROD_INFO
    SELECT A.TYPENO, A.TYPENAME, A.INPUTTIME
      FROM CMS_BUSINESS_TYPE A
      LEFT JOIN MTS_CMS_PROD_INFO B
        ON A.TYPENO = B.PRODUCT_ID
     WHERE A.TYPENO LIKE 'LI1%'
       AND B.PRODUCT_ID IS NULL;
  COMMIT;
  --------理财产品
  INSERT INTO MTS_FMS_PROD_INFO
    SELECT A.PROD_CODE,
           A.PROD_NAME,
           A.PROD_CHILD_NO,
           A.PROD_CURRENCY,
           A.ORGNO,
           A.PROFIT_TYPE,
           A.PERIOD_TYPE,
           A.PROC_MODE,
           A.PROD_RISK_LEVEL,
           A.ESTABLISH_DATE,
           A.VALUE_DATE,
           A.OPEN_BEGIN_DATE,
           A.OPEN_BEGIN_TIME,
           A.OPEN_END_DATE,
           A.TRANS_CLOSE_TIME,
           A.PROD_SALE_STATUS,
           A.WINDING_DATE
      FROM FMS_T5_PROD_INFO A
      LEFT JOIN MTS_FMS_PROD_INFO B
        ON A.PROD_CODE = B.PRODUCT_ID
     WHERE A.PROD_SALE_STATUS = '1'
       AND B.PRODUCT_ID IS NULL;
  COMMIT;
  --
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.PRODUCT_BASE_INFO';
  INSERT INTO PRODUCT_BASE_INFO
    SELECT B.PRODUCT_ID,
           B.CHANPSHM,
           V_SYSDAT,
           B.SHENXRIQ,
           B.SHIXRIQI,
           V_SYSDAT,
           ROWNUM,
           'tenant_system'
      FROM MTS_CBS_PROD_INFO B
     ORDER BY B.SHENXRIQ DESC;
  COMMIT;
  INSERT INTO PRODUCT_BASE_INFO
    SELECT A.PRODUCT_ID,
           A.PRODUCT_NAME,
           V_SYSDAT,
           '',
           '',
           V_SYSDAT,
           ROWNUM,
           'tenant_system'
      FROM MTS_CMS_PROD_INFO A
     ORDER BY A.PRODUCT_ID;
  COMMIT;
  INSERT INTO PRODUCT_BASE_INFO
    SELECT S.PRODUCT_ID,
           S.PROD_NAME,
           V_SYSDAT,
           S.OPEN_BEGIN_DATE,
           (CASE
             WHEN S.PERIOD_TYPE = '0' THEN
              S.OPEN_END_DATE
             ELSE
              S.WINDING_DATE
           END),
           V_SYSDAT,
           ROWNUM,
           'tenant_system'
      FROM MTS_FMS_PROD_INFO S
     ORDER BY S.OPEN_BEGIN_DATE DESC;
  COMMIT;
  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工标签MTS_CUST_LABEL_001数据处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_SYS_XTHLCS(V_SYSDAT IN VARCHAR2,
                                             OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 机构数据生成
  -- 报表编号：P_MTS_SYS_XTHLCS
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  cyc
  -- date   ： 2020-07-13
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME   VARCHAR2(100) := '系统汇率处理'; --过程中文名称
  V_PRCNAME   VARCHAR2(32) := 'P_MTS_SYS_XTHLCS'; --存储过程名
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON VARCHAR2(2);
BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;
  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  --根据上游提供汇率信息，对MTS_SYS_XTHLCS表中数据处理
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.MTS_SYS_XTHLCS';
  INSERT INTO MTS_SYS_XTHLCS
    SELECT P.HUOBDAIH,
           P.PJDANWEI,
           P.HUOBFHAO,
           P.ZHNGJJIA,
           P.ZHNGJJIA / P.PJDANWEI HL
      FROM (SELECT C.*,
                   ROW_NUMBER() OVER(PARTITION BY C.HUOBDAIH ORDER BY C.SHENXRIQ DESC, C.SHENXSHJ DESC) ROWNUM_
              FROM CBS_KFXP_XTHLCS C) P
     WHERE ROWNUM_ = 1;
  COMMIT;

  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '系统汇率处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);

  --统计信息收集
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.P_MTS_YWTS(V_SYSDAT IN VARCHAR2,
                                       OUTCDE   OUT NUMBER) AS
  ------------------------------------------------------------------
  -- 报表名称: 客户基础标签处理_AB01
  -- 报表编号：P_MTS_CUST_LABEL_AB01
  -- 处理周期：日
  -- 过程描述：
  ------------------------------------------------------------------
  -- author :  WY
  -- date   ： 2020-06-11
  ------------------------------------------------------------------
  --***************************************
  --1.自定义参数区
  --***************************************
  V_RPTNAME VARCHAR2(100) := '业务提数'; --过程中文名称
  V_PRCNAME VARCHAR2(32) := 'P_MTS_YWTS'; --存储过程名
  V_SYSDAT2 VARCHAR2(10); --批处理日期 yyyy-mm-dd

  V_SQL       VARCHAR2(4000);
  V_ERRORTEXT VARCHAR2(4000);
  V_START_DT  DATE;
  V_LOGSEC    NUMBER(10);
  --outcde返回码，0成功，其他失败
  --V_BBRQ   VARCHAR2(11); --报表日期
  V_LOG_BUTTON          VARCHAR2(2);
  P_INTERVAL_START_DATE VARCHAR2(8);
  P_INTERVAL_END_DATE   VARCHAR2(8);

BEGIN

  --***************************************
  --3.业务逻辑区
  --***************************************
  --执行周期：日
  --OUTCDE返回码，0成功 其他失败
  V_START_DT := SYSDATE;

  V_SYSDAT2 := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd'), 'yyyy-mm-dd');

  P_INTERVAL_START_DATE := TO_CHAR(TO_DATE(V_SYSDAT, 'yyyymmdd') - 30,
                                   'yyyymmdd');
  P_INTERVAL_END_DATE   := V_SYSDAT;

  --调试日志打开
  V_LOG_BUTTON := 1;
  --条件为变量的SQL处理

  --统计信息收集
  DELETE FROM TPM_CUST_DF;
  COMMIT;
  INSERT INTO TPM_CUST_DF
    SELECT C.KEHUHAOO
      FROM CBS_KIBB_PLDLYW A, CBS_KIBB_PLDLMX B, CBS_KDPA_KEHUZH C
     WHERE A.WEITUOHO = B.WEITUOHO
       AND B.KEHUZHAO = C.KEHUZHAO
       AND B.CHULRIQI >= '20200101'
       AND A.JIAOYIMA = '1600'
       AND A.XITONGBS IN ('1001', '2002', '3001')
     GROUP BY C.KEHUHAOO;
  DELETE FROM TMP_CUST_TEL_INFO;
  COMMIT;
  INSERT INTO TMP_CUST_TEL_INFO
    SELECT ECIF_CUST_NO, PHONE_NO
      FROM (SELECT C.ECIF_CUST_NO,
                   B.PHONE_NO,
                   ROW_NUMBER() OVER(PARTITION BY A.PARTY_ID ORDER BY A.LAST_UPDATED_TS DESC) ROWNUM_
              FROM ECIF_T01_P_CUST_INFO C
              LEFT JOIN ECIF_T02_A_CUST_TELE_REL A
                ON C.PARTY_ID = A.PARTY_ID
              LEFT JOIN ECIF_T03_A_TELE_INFO B
                ON A.TELE_ID = B.TELE_ID
             WHERE A.TELE_TYPE = '102') P
     WHERE ROWNUM_ = 1;
  DELETE FROM TMP_CUST_SIGN;
  COMMIT;
  INSERT INTO TMP_CUST_SIGN
    SELECT I.ECIF_CUST_NO, --ECIF客户号
           SUM(CASE
                 WHEN S.SIGN_TYPE = '124' THEN
                  1
                 ELSE
                  0
               END) QYSJ, --手机银行
           SUM(CASE
                 WHEN S.SIGN_TYPE = '212' THEN
                  1
                 ELSE
                  0
               END) QYLC, --理财签约
           SUM(CASE
                 WHEN S.SIGN_TYPE = '3435' THEN
                  1
                 ELSE
                  0
               END) QYYMF --一码付签约
      FROM MTS.ECIF_T01_P_CUST_INFO I
     INNER JOIN MTS.ECIF_T02_A_CUST_SIGN_REL S
        ON S.PARTY_ID = I.PARTY_ID
       AND S.SIGN_STATE <> '2'
     WHERE S.SIGN_TYPE IN ('124', '212')
     GROUP BY I.ECIF_CUST_NO;
  DELETE FROM TMP_YWSJ1;
  COMMIT;
  DELETE FROM MTS_CUST_LABEL;
  COMMIT;
  INSERT INTO MTS_CUST_LABEL
    (AA01,
     AB01,
     AD01,
     AB05,
     AG02,
     CA02,
     BA01,
     CH12,
     CC02,
     CA33,
     CE02,
     CD01,
     CH08)
    SELECT C.HOST_CUST_NO,
           D.PARTY_NAME,
           G.PHONE_NO,
           2020 - SUBSTR(TO_CHAR(D.BIRTH_DATE, 'yyyymmdd'), 1, 4) NL,
           F.JIGOUZWM,
           E.DEPT_BAL,
           E.AUM_M_AD,
           CASE
             WHEN H.QYSJ > 0 THEN
              '1'
             ELSE
              '0'
           END SJQY,
           CASE
             WHEN H.QYLC > 0 THEN
              '1'
             ELSE
              '0'
           END LCQY,
           CASE
             WHEN I.SFCY > 0 THEN
              '1'
             ELSE
              '0'
           END DECD,
           CASE
             WHEN K.KEHUHAOO IS NOT NULL THEN
              '1'
             ELSE
              '0'
           END DFGZ,
           CASE
             WHEN SFDK > 0 THEN
              '1'
             ELSE
              '0'
           END DKKH,
           CASE
             WHEN CH.AA01 IS NOT NULL THEN
              '1'
             ELSE
              '0'
           END YMF
      FROM CDS_TB_CASH_ACCT_INFO A
     INNER JOIN CDS_TB_PROD_PUB_INFO B
        ON A.PROD_CODE = B.PROD_CODE
     INNER JOIN CDS_T1_CUST_INFO C
        ON A.CUST_NO = C.CUST_NO
     INNER JOIN ECIF_T01_P_CUST_INFO D
        ON C.HOST_CUST_NO = D.ECIF_CUST_NO
      LEFT JOIN OCRM_T_PECUST_VALUE_INFO E
        ON D.ECIF_CUST_NO = E.ECIF_CUST_NO
      LEFT JOIN CBS_KBRP_JGCSHU F
        ON E.BELONG_ORG_NO = F.JIGOUHAO
      LEFT JOIN TMP_CUST_TEL_INFO G
        ON D.ECIF_CUST_NO = G.ECIF_CUST_NO
      LEFT JOIN TMP_CUST_SIGN H
        ON D.ECIF_CUST_NO = H.ECIF_CUST_NO
      LEFT JOIN (SELECT A.KEHUHAOO, 1 SFCY
                   FROM CBS_KDPA_ZHXINX A
                  WHERE A.CUNKZLEI = '29'
                    AND A.ZHHUYUEE > 0
                  GROUP BY A.KEHUHAOO) I
        ON D.ECIF_CUST_NO = I.KEHUHAOO
      LEFT JOIN (SELECT B.MFCUSTOMERID, '1' SFDK
                   FROM CMS_ACCT_LOAN A, CMS_CUSTOMER_INFO B
                  WHERE A.CUSTOMERID = B.CUSTOMERID
                    AND A.NORMALBALANCE = 0
                    AND A.FINISHDATE IS NOT NULL
                    AND B.MFCUSTOMERID IS NOT NULL
                  GROUP BY B.MFCUSTOMERID) J
        ON D.ECIF_CUST_NO = J.MFCUSTOMERID
      LEFT JOIN TPM_CUST_DF K
        ON D.ECIF_CUST_NO = K.KEHUHAOO
      LEFT JOIN MTS_CUST_LABEL_CH06 CH
        ON D.ECIF_CUST_NO = CH.AA01
     WHERE A.STATUS = '0'
       AND A.PROD_CODE IN ('736',
                           '739',
                           '733',
                           '724',
                           '782',
                           '781',
                           '723',
                           '795',
                           '783',
                           '730',
                           '784',
                           '779',
                           '729',
                           '740',
                           '731',
                           '780',
                           '796',
                           '737',
                           '726',
                           '732',
                           '725',
                           '738',
                           '728',
                           '727',
                           '734');

  INSERT INTO TMP_DQCPDQ
    SELECT *
      FROM (SELECT A.KEHUHAOO, A.ZHHUYUEE, B.CHANPSHM, A.DOQIRIQI
              FROM CBS_KDPA_ZHXINX A, CBS_KDPF_CHPSHX B
             WHERE A.CHAPBHAO = B.CHAPBHAO
               AND A.CUNKZLEI IN ('01', '02', '03', '04', '05', '06', '07')
               AND A.DOQIRIQI >= '20200901'
               AND A.DOQIRIQI <= '20201231'
               AND A.ZHHUZTAI <> 'C'
            UNION ALL
            SELECT C.HOST_CUST_NO, A.BALANCE, B.PROD_NAME, A.EXPIRE_DATE
              FROM CDS_TB_CASH_ACCT_INFO A,
                   CDS_TB_PROD_PUB_INFO  B,
                   CDS_T1_CUST_INFO      C
             WHERE A.PROD_CODE = B.PROD_CODE
               AND A.CUST_NO = C.CUST_NO
               AND A.EXPIRE_DATE >= '20200901'
               AND A.EXPIRE_DATE <= '20201231'
               AND A.PROD_SUBCLASS IN ('3', '4'));
  DELETE FROM TMP_YWSJ2;
  COMMIT;
  INSERT INTO TMP_YWSJ2
    SELECT A.KEHUHAOO,
           D.PARTY_NAME,
           G.PHONE_NO,
           2020 - SUBSTR(TO_CHAR(D.BIRTH_DATE, 'yyyymmdd'), 1, 4) NL,
           F.JIGOUZWM,
           E.DEPT_BAL,
           E.AUM_M_AD,
           CASE
             WHEN H.QYSJ > 0 THEN
              '1'
             ELSE
              '0'
           END SJQY,
           CASE
             WHEN H.QYLC > 0 THEN
              '1'
             ELSE
              '0'
           END LCQY,
           CASE
             WHEN I.SFCY > 0 THEN
              '1'
             ELSE
              '0'
           END DECD,
           CASE
             WHEN K.KEHUHAOO IS NOT NULL THEN
              '1'
             ELSE
              '0'
           END DFGZ,
           CASE
             WHEN SFDK > 0 THEN
              '1'
             ELSE
              '0'
           END DKKH,
           CASE
             WHEN H.QYYMF > 0 THEN
              '1'
             ELSE
              '0'
           END YMF,
           A.CHANPSHM,
           A.ZHHUYUEE,
           A.DOQIRIQI
      FROM TMP_DQCPDQ A
     INNER JOIN ECIF_T01_P_CUST_INFO D
        ON A.KEHUHAOO = D.ECIF_CUST_NO
      LEFT JOIN OCRM_T_PECUST_VALUE_INFO E
        ON D.ECIF_CUST_NO = E.ECIF_CUST_NO
      LEFT JOIN CBS_KBRP_JGCSHU F
        ON E.BELONG_ORG_NO = F.JIGOUHAO
      LEFT JOIN TMP_CUST_TEL_INFO G
        ON D.ECIF_CUST_NO = G.ECIF_CUST_NO
      LEFT JOIN TMP_CUST_SIGN H
        ON D.ECIF_CUST_NO = H.ECIF_CUST_NO
      LEFT JOIN (SELECT A.KEHUHAOO, 1 SFCY
                   FROM CBS_KDPA_ZHXINX A
                  WHERE A.CUNKZLEI = '29'
                    AND A.ZHHUYUEE > 0
                  GROUP BY A.KEHUHAOO) I
        ON D.ECIF_CUST_NO = I.KEHUHAOO
      LEFT JOIN (SELECT B.MFCUSTOMERID, '1' SFDK
                   FROM CMS_ACCT_LOAN A, CMS_CUSTOMER_INFO B
                  WHERE A.CUSTOMERID = B.CUSTOMERID
                    AND A.NORMALBALANCE = 0
                    AND A.FINISHDATE IS NOT NULL
                    AND B.MFCUSTOMERID IS NOT NULL
                  GROUP BY B.MFCUSTOMERID) J
        ON D.ECIF_CUST_NO = J.MFCUSTOMERID
      LEFT JOIN TPM_CUST_DF K
        ON D.ECIF_CUST_NO = K.KEHUHAOO;
  COMMIT;
  --日志打印
  OUTCDE      := 0;
  V_ERRORTEXT := '加工客户名称处理完成' || SUBSTR(SQLERRM, 1, 1000);
  V_LOGSEC    := ROUND((SYSDATE - V_START_DT) * 24 * 60 * 60);
  MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                        V_PRCNAME,
                        V_RPTNAME,
                        V_ERRORTEXT,
                        V_LOGSEC,
                        V_LOG_BUTTON);
  --异常日志抛出
EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      OUTCDE := -1;
      ROLLBACK;
      --V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000);
      V_ERRORTEXT := SUBSTR(SQLERRM, 1, 1000) || '&' ||
                     SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE(), 1, 200);
      MTS.SYS_PRC_STEP_LOGS(V_SYSDAT,
                            V_PRCNAME,
                            V_RPTNAME,
                            V_ERRORTEXT,
                            V_LOGSEC,
                            V_LOG_BUTTON);
      RETURN;
    END;
  
END;
/

CREATE OR REPLACE PROCEDURE MTS.SYS_DROP_TABLE(TABOWNER IN VARCHAR2,
                                           TABNAME  IN VARCHAR2,
                                           OUTCODE  OUT NUMBER,
                                           MESSAGE  OUT VARCHAR2) AS
  /*
  AUTHOR : SOLIN
  CREATE DATE : 20170922
  CONTENT : 删除表,返回0删除成功，否则返回1.
  */

  V_COUNT INTEGER;
BEGIN
  SELECT COUNT(1)
    INTO V_COUNT
    FROM ALL_TABLES
   WHERE OWNER = UPPER(TABOWNER)
     AND TABLE_NAME = UPPER(TABNAME);
  IF V_COUNT = 1 THEN
    EXECUTE IMMEDIATE 'DROP TABLE ' || TABOWNER || '.' || TABNAME;
    COMMIT;
  END IF;
  OUTCODE := SQLCODE;
  MESSAGE := SUBSTR(SQLERRM, 1, 1000);
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    OUTCODE := SQLCODE;
    MESSAGE := SUBSTR(SQLERRM, 1, 1000);
END;
/

CREATE OR REPLACE PROCEDURE MTS.TEST_CHECK_LOGS(IS_ERROR      VARCHAR2,--是否错误日志
                                            PROC_NAME     VARCHAR2, --存储过程名
                                            CHECK_NO      VARCHAR2, --日志位置
                                            TABLE_NAME    VARCHAR2, --表名
                                            CHECK_TYPE    VARCHAR2, --检查内容
                                            EXE_SQL       VARCHAR2, --执行SQL
                                            ERROR_CODES   VARCHAR2, --错误代码
                                            STATISTICDATE VARCHAR2) --检查日期
 AS
  /********************************************************
  * TITLE      : 数据测试日志
  * DESCRIPTION: 全量
  * COPYRIGHT  :
  * COMPANY    :
  * AUTHOR     : LL
  * VERSION    : 1.0
  * MODIFY BY  :
  * DATE       : 2019-08-15
  ********************************************************/
BEGIN


/*
  --记录日志前防止重复先删数
   DELETE FROM TEST_CHECK_LOG T
         WHERE T.TESTDATE = STATISTICDATE
           AND T.CALL_TYPE = CHECK_TYPE
           AND TABLENAME = TABLE_NAME
           AND PROCNAME = PROC_NAME
           AND EXE_SQL = EXE_SQLS;
 COMMIT;

*/
  --插入检查当天的跑批日志
  INSERT INTO TEST_CHECK_LOG
    VALUES
      (
         IS_ERROR,
         PROC_NAME,
         CHECK_NO,
         TABLE_NAME,
         CHECK_TYPE,
         EXE_SQL,
         ERROR_CODES,
         TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'),
         STATISTICDATE
       );
  COMMIT;

END;
/

CREATE OR REPLACE PROCEDURE MTS.TEST_CHECK (CHECK_DATE VARCHAR2 --检查日期
                                        ,
                                        TEST_NUMBER VARCHAR2) --测试轮次
AS
  /***************************************
  * TITLE      : 《精准营销》数据测试</P>
  * DESCRIPTION: 全量
  * COPYRIGHT  :
  * COMPANY    :
  * AUTHOR     ：LL
  * VERSION    ：1.0
  * MODIFY BY  :
  * DATE       : 2020-06-23
  ***************************************/
  V_SQL VARCHAR2(4000);
  CURSOR CHECK_SOR IS
  SELECT INS_SCRIPT || SEL_SCRIPT AS SCRIPT
    FROM TEST_LOOP_TAB ;
BEGIN
--中间表清数
  DELETE from TEST_LOOP_TAB ;
  INSERT INTO TEST_LOOP_TAB
       SELECT AA,
              AB,
              AC,
              AD,
              'INSERT INTO TEST_LOOP_OUT SELECT '''||AA||''','''||AB||''','''||AC||''','''||AD||''','''||CHECK_DATE||''', ',
              SUBSTR(REPLACE(REPLACE(E,'"'),';'),7),
              ''
       FROM TEST_MATE ;

--中间结果表清数
  EXECUTE IMMEDIATE 'TRUNCATE TABLE MTS.TEST_LOOP_OUT';
--执行游标
  FOR V_SQL IN CHECK_SOR LOOP
    BEGIN
      --测试SQL运行日志存储过程
      TEST_CHECK_LOGS ('0',
                       'TEST_CHECK',
                       '1',
                       '',
                       '',
                       V_SQL.SCRIPT,
                       '',
                       CHECK_DATE) ;
       
      execute immediate V_SQL.SCRIPT;--执行游标
      --测试SQL运行日志存储过程
      TEST_CHECK_LOGS ('0',
                       'TEST_CHECK',
                       '1',
                       '',
                       '',
                       V_SQL.SCRIPT,
                       '',
                       CHECK_DATE) ;
       
      EXCEPTION
        WHEN OTHERS THEN
          TEST_CHECK_LOGS('1',
                          'TEST_CHECK',
                          TEST_NUMBER,
                          '',
                          '',
                          V_SQL.SCRIPT,
                          '',
                          CHECK_DATE); -- 测试SQL错误日志存储过程
         continue;
    end;
  end loop;

--中间表数据进入结果表
  DELETE FROM TEST_OUT WHERE CHE_DATE = CHECK_DATE ;
  INSERT INTO TEST_OUT
  SELECT t2.AA,                  --案例编号
         CHECK_DATE,             --测试时间
         t3.b,                   --目标表英文名
         t3.a,                   --目标表中文名
         t3.d,                   --目标表英文字段名
         t3.c,                   --目标表中文字段名
         t3.m,                   --源数据来源系统
         t3.n,                   --来源表英文表名
         t3.o,                   --来源表中文表名
         t3.p,                   --来源表英文字段名
         t3.q,                   --来源表中文字段名
         t2.ab,                  --测试类型
         t2.b,                   --测试名称
         t2.c,                   --测试描述
         t2.f,                   --预期结果
         t1.CHE_TOTAL,           --测试结果
         t2.E                    --测试SQL
    FROM TEST_LOOP_OUT t1,TEST_MATE T2,TEST_MATE_1 T3
   WHERE T1.CHE_ID = T2.AA
     AND T1.TAB_NAME = T3.B
     AND T1.COL_NAME = T3.D;
  COMMIT;

--空值率录入结果表
  INSERT INTO TEST_OUT
  SELECT T4.AA,
         CHECK_DATE,
         t5.b,
         t5.a,
         t5.d,
         t5.c,
         t5.m,
         t5.n,
         t5.o,
         t5.p,
         t5.q,
         t4.AB,
         t4.B,
         '验证：字段空值率',
         t4.F,
         CHE_TOTAL,
         t3.CHE_TOTAL_1||'/'||t3.CHE_TOTAL_2||'='||CHE_TOTAL||'(字段为空数/整表记录数=空值率)'
    FROM
      (SELECT T1.CHE_ID,T1.TAB_NAME,T1.COL_NAME,t1.CHE_TOTAL CHE_TOTAL_1,t2.CHE_TOTAL CHE_TOTAL_2,ROUND(t1.CHE_TOTAL / NVL(t2.CHE_TOTAL,0) * 100, 2) || ' % ' CHE_TOTAL
         FROM TEST_LOOP_OUT t1,TEST_LOOP_OUT T2
        WHERE T1.TAB_NAME = T2.TAB_NAME
          AND T1.CHE_TYPE = '为空检查'
          AND T2.CHE_TYPE = '完整性'
          AND T1.CHE_DATE = T2.CHE_DATE
          AND T1.CHE_DATE = CHECK_DATE
          AND t2.CHE_TOTAL <> 0 ) T3,TEST_MATE T4,TEST_MATE_1 T5
   WHERE T3.CHE_ID = T4.AA
     AND T3.TAB_NAME = T5.B
     AND T3.COL_NAME = T5.D;
  COMMIT;

END;
/


